    \setlength{\belowcaptionskip}{-0.25cm}
	\centering
 \includegraphics[width=\linewidth,scale=1.00]{figs/framework.pdf}
	%[]里面的参数自己可根据需要调整
	\caption{
    Overview of our proposed FedPG framework. 
 }
	\label{fig: framework}
