\subsection{The CA Mechanism}
\label{app:ca}

We first show that a single draw of the CA score is SD-truthful when $|\Sigma|=2$.

\begin{proof}[Proof of \cref{prop:ca_sdt_single}]
    We first show that the agreement function $T_\Delta$ is an identity matrix if and only if signals are self-predicting.
    For simplicity, let $J_{\sigma,\sigma'}=\Pr(X_a=\sigma, X_b=\sigma')$ be the joint distribution, and let $M^a_\sigma = \Pr(X_a=\sigma)$ and $M^b_\sigma = \Pr(X_b=\sigma)$ be the marginal distribution of Alice and Bob respectively.
    The delta matrix can be written as 
    \begin{align*}
        \Delta_{\sigma,\sigma} &= J_{\sigma,\sigma} - M^a_\sigma\; M^b_\sigma\\
        &= J_{\sigma,\sigma} - M^a_\sigma\;(J_{\sigma,\sigma}+J_{\sigma',\sigma})\\
        &= J_{\sigma,\sigma}\;M^a_{\sigma'} - J_{\sigma',\sigma}\;M^a_\sigma\\
        &= M^a_\sigma\; M^a_{\sigma'}\;\left(\Pr(X_b=\sigma\mid X_a=\sigma) - \Pr(X_b=\sigma\mid X_a=\sigma')\right).
    \end{align*}
    \begin{align*}
        \Delta_{\sigma,\sigma'} &= J_{\sigma,\sigma'} - M^a_\sigma\; M^b_{\sigma'}\\
        &= J_{\sigma,\sigma'} - M^a_\sigma\;(J_{\sigma,\sigma'}+J_{\sigma',\sigma'})\\
        &= J_{\sigma,\sigma'}\;M^a_{\sigma'} - J_{\sigma',\sigma'}\;M^a_\sigma\\
        &= M^a_\sigma\; M^a_{\sigma'}\;\left(\Pr(X_b=\sigma'\mid X_a=\sigma) - \Pr(X_b=\sigma'\mid X_a=\sigma')\right).
    \end{align*}

    Next, we reason about the distribution of scores under different strategies.
    Note that a single draw of the CA score can be $-1$, $0$, or $1$.
    Therefore, to prove SD-truthfulness for a single draw of the CA score, it is sufficient to show that $\Pr\left(S^{CA}_i(\tau)=1\right)\ge \Pr\left(S^{CA}_i(\theta)=1\right)$ and $\Pr\left(S^{CA}_i(\tau)=-1\right)\le \Pr\left(S^{CA}_i(\theta)=-1\right)$ for any strategy $\theta$.
    When signals are binary, there are only three types of untruthful strategy: 1) always reporting 0, 2) always reporting 1, and 3) always flipping 0 to 1 and 1 to 0.
    Any other strategy is a mixture of truth-telling and these strategies.
    Now, we show that all of these strategies are stochastically dominated by truth-telling by discussing two cases.

    When signals are self-predicting, i.e.~$\Pr(X_b=\sigma\mid X_a=\sigma) - \Pr(X_b=\sigma\mid X_a=\sigma')>0$, the distribution of $S^{CA}_i$ is 
    \begin{align*}
         \Pr\left(S^{CA}_i(\tau)=1\right) &= J_{0,0}\;M^b_1 + J_{1,1}\;M^b_0,\\
         \Pr\left(S^{CA}_i(\tau)=-1\right) &= J_{0,1}\;M^b_0 + J_{1,0}\;M^b_1.\\
         % \Pr\left(S^{CA}_i(\mu, \tau)=1\right) &= M^b_0\;M^b_1 = J_{0,0}\;M^b_1 + J_{1,0}\;M^b_1\\
         % \Pr\left(S^{CA}_i(\tau)=1\right) - \Pr\left(S^{CA}_i(\mu, \tau)=1\right)&= J_{j,j}\;M^b_i - J_{i,j}\;M^b_j
     \end{align*}

    Because Bob's signal is self-predicting, $\Pr\left(S^{CA}_i(\tau)=1\right) > \Pr\left(S^{CA}_i(\tau)=-1\right)$.
    Let $\theta_f$ be the strategy where Alice always flips the signals.
    \begin{align*}
         \Pr\left(S^{CA}_i(\theta_f)=1\right) &= J_{0,1}\;M^b_0 + J_{1,0}\;M^b_1 = \Pr\left(S^{CA}_i(\tau)=-1\right),\\
         \Pr\left(S^{CA}_i(\theta_f)=-1\right) &= J_{0,0}\;M^b_1 + J_{1,1}\;M^b_0 = \Pr\left(S^{CA}_i(\tau)=1\right).\\
     \end{align*}
     This means that $S^{CA}_i(\theta_f)$ is dominated by $S^{CA}_i(\tau)$.

     Let $\mu$ be the strategy where Alice always reports the same signal.
    \begin{align*}
         \Pr\left(S^{CA}_i(\mu)=1\right) = \Pr\left(S^{CA}_i(\mu)=-1\right)&= M^b_0\;M^b_1.
     \end{align*}
     Therefore, 
     \begin{align*}
         \Pr\left(S^{CA}_i(\tau)=1\right) - \Pr\left(S^{CA}_i(\mu)=1\right)&= J_{0,0}\;M^b_1 + J_{1,1}\;M^b_0 -M^b_0\;M^b_1\\
         &=J_{0,0}\;M^b_1 + J_{1,1}\;M^b_0 -M^b_0\;(J_{0,1}+J_{1,1})\\
         &= J_{0,0}\;M^b_1 -J_{0,1}\; M^b_0\\
         &= M^b_0\;M^b_1\;\left(\Pr(X_a=0\mid X_b=0) - \Pr(X_b=0\mid X_a=1\right)\\
         &> 0
     \end{align*}
     Similarly, we can observe that $\Pr\left(S^{CA}_i(\tau)=-1\right) < \Pr\left(S^{CA}_i(\mu)=-1\right)$.

     The analysis for the case when signals are not self-predicting, i.e.~$T_\Delta(\sigma,\sigma')=1$ if and only if $\sigma\neq \sigma'$, is analogous.
\end{proof}

Next, we show that when $|\Sigma|=3$, counterexamples exist showing that truth-telling does not FOSD every untruthful strategy.

\begin{example}
    Consider the following joint distribution:
    \[
    J = \begin{pmatrix}
    0.02 & 0.01 & 0.02 \\
    0.2  & 0.4  & 0.25 \\
    0.00 & 0.05 & 0.05
    \end{pmatrix}.
    \]
    The marginal distribution of Alice and Bob are 
    \[M^a = \begin{pmatrix}0.05, & 0.85, & 0.1\end{pmatrix}\;\; \text{and }\; M^b=\begin{pmatrix}0.22, & 0.46, & 0.32\end{pmatrix}.\]
    The product of marginal distribution and the corresponding agreement function are
    \[
    \Delta =
    \begin{pmatrix}
    0.009  & -0.013 & 0.004 \\[1ex]
    0.013  & 0.009  & -0.022 \\[1ex]
    -0.022 & 0.004  & 0.018
    \end{pmatrix},\quad 
    T_\Delta =
    \begin{pmatrix}
    1  & 0 & 1 \\[1ex]
    1  & 1  & 0 \\[1ex]
    0 & 1  & 1
    \end{pmatrix}.
    \]

    When Alice reports truthfully, the probability of obtaining a score of 1, i.e.~obtaining a score of 1 on the bonus question and obtaining a score of 0 on the penalty question, is given by
    \[\Pr(S^{CA}_i(\tau)=1) = \underbrace{(J_{0,0}+J_{0,2})\cdot M^b_1}_{\text{Alice reports 0}} + \underbrace{(J_{1,0}+J_{1,1})\cdot M^b_2}_{\text{Alice reports 1}}+\underbrace{(J_{2,1}+J_{2,2})\cdot M^b_0}_{\text{Alice reports 0}} = 0.2324.\]
    However, when Alice plays a strategy $\mu$ that always reports 0, the probability of obtaining a score of 1 is given by
    \[\Pr(S^{CA}_i(\mu)=1) = (M^b_{0}+M^b_{2})\cdot M^b_1=0.2474>\Pr(S^{CA}_i(\tau)=1).\]
    Therefore, $\mu$ is not first-order stochastically dominated by $\tau$.
\end{example}

\subsection{The Partition Rounding Reduction}
\label{app:Kto1}

\begin{proof}[Proof of \cref{lem:Kto1}]
    Let $S_i(\tau)$ and $S_i(\theta)$ be the random variable of each individual score under truth-telling and strategy $\theta$, respectively.
    $S_i(\tau)$ (and $S_i(\theta)$) is i.i.d.~because questions are assumed to be i.i.d.~and strategies are task-independent.
    We want to show 
    $$S_i(\tau) \quad \succeq_{\text{FOSD}}\quad S_i(\theta) \qquad \Leftrightarrow \qquad S(\tau) \quad \succeq_{\text{FOSD}} \quad S(\theta).$$

    \smallskip
    \textbf{Forward Direction.\quad}
    Suppose $S_i(\tau) \succeq_{\text{FOSD}} S_i(\theta)$ for any $\theta$. 
    By definition, this means for each individual score, we can find a coupling such that whenever $S_i(\theta) = s_i$, $S_i(\tau) = s'_i\ge s_i$.
    Applying this coupling for every individual score and taking the average gives us a coupling for $S(\tau)$ and $S(\theta)$:
    whenever $S(\theta) = \sum_{i\in [K]} s_i$, $S(\tau) = \sum_{i\in [K]} s'_i \ge \sum_{i\in [K]} s_i$ in the coupling.
    Therefore, in this coupling, $\Pr(S(\theta)\le t)\ge \Pr(S(\tau)\le t)$ for any $t\in [K\cdot S_{\inf}, K\cdot S_{\sup}]$ where $S_{\inf}$ and $S_{\sup}$ are the infimun and supremum of each $S_i$, respectively.
    This completes the proof for the sufficiency.

    \smallskip
    \textbf{Reverse Direction.\quad}
    We prove the contrapositive of the statement: if $S_i(\tau)$ does not first-order stochastic dominates $S_i(\theta)$, then $S(\tau)$ does not first-order stochastic dominates $S(\theta)$.
    By the failure of FOSD for the individuals, there exists some threshold $t_1$ and (by the i.i.d. assumption) every $i$ such that $F_\tau(t_1) > F_\theta(t_1)$, where $F_\tau$ and $F_\theta$ denote that c.d.f.~for $S_i(\tau)$ and $S_i(\theta)$ respectively.
    Let $F^{k}_\tau$ and $F^{k}_\theta$ be the c.d.f.~of the sum of $k$ i.i.d.~individual scores, i.e.~$\sum_{i\in [k]}S_i(\tau)$ and $\sum_{i\in [k]}S_i(\theta)$ respectively.
    We want to find a $t_K$ such that $F^{K}_\tau(t_K) > F^{K}_\theta(t_K)$.
    Then, because $S$ is a linear scaling (by $1/K$) of the sum, the inequality transfers directly to the averages.

    We prove this via an inductive argument:
    \begin{itemize}
        \item Base case ($K=1$): by assumption, there exists a $t_1$ such that $F_\tau(t_1) > F_\theta(t_1)$.
        \item Inductive step: suppose that for $K-1$ there exists some threshold $t_{K-1}$ such that 
        $$F^{K-1}_\tau(t_{K-1}) > F^{K-1}_\theta(t_{K-1}).$$
        Now, consider the $K$-fold convolution. 
        Note that the convolution of discrete distributions is a weighted sum of the individual c.d.f..
        $$F^{K}_\tau(t_K) = \sum_{s} \Pr\left(\sum_{i\in [K-1]}S_i(\tau)=s\right)\;F_\tau(t_K-s),$$
        and similarly for $F^{K}_\theta(t_K)$.
        By the base case and the induction assumption, we can set $t_K=t_{K-1}+t_1$ so that $F^K_\tau(t_K)>F^{K}_\theta(t_K)$.
        This means that there exists a threshold $t=t_K/K$ so that 
        \[\Pr\bigl(S(\tau) \le t\bigr) > \Pr\bigl(S(\theta) \le t\bigr).\]
    \end{itemize}
    The completes the proof of the necessity.
\end{proof}

\subsection{SD-truthfulness for the Binary-signal Setting}
\label{app:binary}
\begin{proof}[Proof of \cref{thm:ea_binary}]
    Suppose Alice observes $m_0$ zeros and $m_1$ ones on $n$ questions while the enforced empirical distribution is $\Phi=(n_0, n_1)$.
    Alice's strategy and $\Phi$ thus determines the number of i.i.d.~samples from each of the four binomials.

    To prove SDT, we have to show that truth-telling results in a score distribution that first-order stochastic dominates the score distribution under any other strategy.
    Suppose W.L.O.G.~that $m_0 > n_0$ and the mechanism will randomly flip Alice's reports on $m_0-n_0$ questions from 0 to 1.
    If Alice reports truthfully, there are $n_0$ questions where Alice reports $0$ and will be scored 1 if Bob also reports $0$; there are $m_1$ questions where Alice reports $1$ and will be scored 1 if Bob also reports $1$; and there are $m_0 - n_0$ questions where Alice observes $0$ but her reports are flipped to 1 which means that she will be scored 1 if Bob reports $1$ on those questions.
    Therefore, the final score of Alice can be expressed as 
    \begin{align}\
        n\cdot S(\tau) \sim \textcolor{red}{\mathrm{Bin}(n_0, p_{00})} + \textcolor{blue}{\mathrm{Bin}(m_1, p_{11})} + \textcolor{ForestGreen}{\mathrm{Bin}(m_0-n_0, p_{01})}.
    \end{align}

    To show that $S(\tau)$ dominates $S(\theta)$ for any strategy $\theta$, it is sufficient to focus on deterministic strategies.
    Suppose $x_{i,j}$ is the number of questions that Alice observes $i$ but reports $j$ for $i,j\in \{0,1\}$.
    First note that $x_{0,0}+x_{0,1} = m_0$ and $x_{1,0}+x_{1,1} = m_1$.
    Then, we argue that it is sufficient to focus on strategies that satisfy $x_{0,0}+x_{1,0} = n_0$ and $x_{0,1}+x_{1,1} = n_1$.
    Otherwise, the mechanism will enforce $\Phi$ on behalf of Alice which is identical for Alice to flip her signals by herself.
    Fixing any $\Phi$ and $\Phi_{X_a}$, the above four constraints suggest that there is only one free variable in $x$, meaning that there is only one possible way to cheat --- altering $x_{0,0}\in \{0, \ldots, n_0\}$.

    Now, we show that reporting $x_{0,0} = n_0$ is the best strategy --- reporting any $x_{0,0}$ results in a score distribution dominated by reporting $x_{0,0} = n_0$.
    Also, note that truth-telling is one of the strategies that has $x_{0,0} = n_0$.
    Let $x_{0,0} = n_0 - k$ where $k \ge 0$.
    Then, the final score of Alice and be expressed as 
    \begin{align}
        n\cdot S(\theta) \textcolor{red}{\sim \mathrm{Bin}(n_0-k, p_{00})} + \textcolor{blue}{\mathrm{Bin}(m_1 - k, p_{11})} + \textcolor{ForestGreen}{\mathrm{Bin}(m_0-n_0 + k, p_{01})} + \textcolor{orange}{\mathrm{Bin}(k, p_{10})}.
    \end{align}

    Compared with the truth-telling score distribution in \cref{eq:_dist_tau}, any untruthful reporting can be viewed as subtracting $k$ samples from $\textcolor{red}{\mathrm{Bin}(n_0, p_{00})}$ and draw $k$ more samples from $\textcolor{orange}{\mathrm{Bin}(k, p_{10})}$; subtracting $k$ samples from $\textcolor{blue}{\mathrm{Bin}(m_1, p_{11})}$ and draw $k$ more samples from $\textcolor{ForestGreen}{\mathrm{Bin}(m_0-n_0 + k, p_{01})}$.

    When signals are self-predicting, $p_{00} > p_{10}$ and $p_{11} > p_{01}$.
    We can construct a coupling to show that $S(\theta)$ is dominated by $S(\tau)$.
    In particular, for the $k$ questions whose scores are sampled from $\textcolor{orange}{\mathrm{Bin}(k, p_{10})}$, we couple them with $k$ out of the $n_0$ samples from $S(\theta) \textcolor{red}{\sim \mathrm{Bin}(n_0-k, p_{00})}$; for the $n_0-k$ questions whose scores are sampled from $\textcolor{red}{\sim \mathrm{Bin}(n_0-k, p_{00})}$, we couple them with the remaining $n_0-k$ samples from $\textcolor{red}{\sim \mathrm{Bin}(n_0-k, p_{00})}$; we do the same for the other two Binomial distributions.
    Under this coupling, it is clear that making $x_{0,0}$ as large as possible will have the dominating score distribution, which happens while truth-telling.
\end{proof}


\subsection{SD-truthfulness for the Three-signal Setting}
\label{app:three}

\begin{proof}[Proof of \cref{prop:impossible}]
 \quad

    \textbf{Sufficiency.}\;
    We prove the sufficiency by discussing two cases.
    First, suppose W.L.O.G.~that $m_0\ge n_0$, $m_1\le n_1$, and $m_2\le n_2$.
    Under the minimal enforcement rule, the manipulation matrix corresponds to truth-telling is 
    \[
    \begin{array}{c}
        \vartheta^\tau(\rho^*)= \left[ 
            \begin{array}{ccc}
                n_0 & n_1-m_1 & n_2-m_2 \\
                0   & m_1     & 0      \\
                0   & 0       & m_2
            \end{array}
          \right].
    \end{array}
    \]
    When we score an arbitrary report vector $\hat{X}_a$, it is sufficient to consider its manipulation matrix $\vartheta$.
    Therefore, we want to show that $\vartheta^\tau$ will result in a score distribution that first-order stochastically dominates the score distribution of any other feasible $\vartheta$.
    Note that there are $9$ variables in a $3\times3$ matrix and $5$ constraints: the sum of variables in row $i$ is $m_i$ and the sum of variables in column $j$ is $n_j$ while only $5$ of these $6$ constraints are independent.
    This means that any manipulation matrix be characterized by $4$ independent variables denoted as $t_1,\ldots t_4\ge 0$.
    \[
    \begin{array}{c}
        \vartheta= \left[ 
            \begin{array}{ccc}
                n_0-t_1-t_2 & n_1-m_1+t_1+t_4-t_3 & n_2-m_2+t_2+t_3-t_4 \\
                t_1   & m_1-t_1-t_4     & t_4      \\
                t_2   & t_3       & m_2-t_2-t_3
            \end{array}
          \right].
    \end{array}
    \]
    The variables $t_1,\ldots t_4$ must satisfy the constraints ensuring that every entry in $\vartheta$ remains non-negative.

    % Let $S_{ij}\sim \mathrm{Bin}(\vartheta_{i,j}, p_{ij})$ and $S^*_{ij}\sim \mathrm{Bin}(\vartheta^\tau_{i,j}, p_{ij})$.
    The final score of truth-telling is given by the average of $n$ Bernoulli variables where $\vartheta^\tau(\rho^*)_{i,j}$ of these variables are sampled from $\mathrm{Bernoulli}(p_{i,j})$.
    Similarly, the final score corresponding to the manipulation matrix $\vartheta$ is the average of $n$ Bernoulli variables where $\vartheta^\theta_{i,j}$ of them are sampled from $\mathrm{Bernoulli}(p_{i,j})$.

   Our goal is to construct a coupling of these Bernoulli variables such that, for any given $\Phi_{X_a}$, $\Phi$, and $t_1,\ldots, t_4$, each variable under truth-telling with manipulation matrix $\vartheta^\tau(\rho^*)$ has a weakly higher probability of success than its coupled counterpart under $\vartheta$.
    We denote this coupling by $Z^\tau_{i,j} \xrightarrow{k} Z^\theta_{i',j'}$ to indicate that we pair $k$ Bernoulli variables associated with $\vartheta^\tau(\rho^*)$ --- each drawn from \(\mathrm{Bernoulli}(p_{ij})\) --- with \(k\) Bernoulli variables associated with $\vartheta$ --- each drawn from \(\mathrm{Bernoulli}(p_{i'j'})\). 
    Our coupling is: 
    \[
    \begin{array}{c}\left[ 
            \begin{array}{ccc}
                Z^\tau_{0,0} \xrightarrow{n_0-t_1-t_2} Z^\theta_{0,0} & Z^\tau_{1,1} \xrightarrow{t_1+t_4} Z^\theta_{0,1} & Z^\tau_{2,2} \xrightarrow{t_2+t_3} Z^\theta_{0,2}\\
                Z^\tau_{0,0} \xrightarrow{t_1} Z^\theta_{1,0}   & Z^\tau_{1,1} \xrightarrow{m_1-t_1-t_4} Z^\theta_{1,1}    & Z^\tau_{0,2} \xrightarrow{t_4} Z^\theta_{1,2}      \\
                Z^\tau_{0,0} \xrightarrow{t_2} Z^\theta_{2,0}   & Z^\tau_{0,1} \xrightarrow{t_3} Z^\theta_{2,1}       & Z^\tau_{2,2} \xrightarrow{m_2-t_2-t_3} Z^\theta_{2,2}
            \end{array}
          \right].
    \end{array}
    \]

Under this coupling, every diagonal variable $Z^\theta_{i,i}$ is coupled with $Z^\tau_{i,i}$ which is drawn from the same Bernoulli distribution.
Furthermore, every non diagonal variable $Z^\theta_{i,j}$ is either coupled with $Z^\tau_{i,i}$ which has a larger success probability because of self-prediction, or coupled with $Z^\tau_{k,j}$ which has the same success probability because signals are uniformly self-predicting.

The proof of the second case is analogous. 
suppose W.L.O.G.~that $m_0 > n_0$, $m_1 > n_1$, and $m_2 < n_2$.
Under the minimal enforcement rule, the manipulation matrix corresponds to truth-telling is 
\begin{equation}\label{eq:theta_tau}
    \begin{array}{c}
        \vartheta^\tau= \left[ 
            \begin{array}{ccc}
                n_0 & 0 & m_0-n_0 \\
                0   & n_1     & m_1-n_1      \\
                0   & 0       & m_2
            \end{array}
          \right].
    \end{array}
\end{equation}
Any feasible manipulation matrix can be written as 
\begin{equation}\label{eq:theta_lying}
    \begin{array}{c}
        \vartheta^\theta= \left[ 
            \begin{array}{ccc}
                n_0-t_1-t_2 & t_4 & m_0-n_0+t_1+t_2-t_4 \\
                t_1   & n_1-t_3-t_4     & m_1-n_1+t_3+t_4-t_1     \\
                t_2   & t_3       & m_2-t_2-t_3
            \end{array}
          \right].
    \end{array}
\end{equation}
We construct the following coupling.
If $t_1\ge t_4$, we apply the term in \textcolor{red}{red}; while if $t_1< t_4$, we apply the term in \textcolor{blue}{blue}.
    \[
    \begin{array}{c}\left[ 
            \begin{array}{ccc}
                Z^\tau_{0,0} \xrightarrow{n_0-t_1-t_2} Z^\theta_{0,0} & Z^\tau_{1,1} \xrightarrow{t_4} Z^\theta_{0,1} & Z^\tau_{2,2} \xrightarrow{t_2} Z^\theta_{0,2},\;  \textcolor{red}{Z^\tau_{1,2} \xrightarrow{t_1-t_4} Z^\theta_{0,2}}\\
                Z^\tau_{0,0} \xrightarrow{t_1} Z^\theta_{1,0}   & Z^\tau_{1,1} \xrightarrow{n_1-t_3-t_4} Z^\theta_{1,1}    & Z^\tau_{2,2} \xrightarrow{t_3} Z^\theta_{1,2},\;  \textcolor{blue}{Z^\tau_{0,2} \xrightarrow{t_4-t_1} Z^\theta_{1,2}}  \\
                Z^\tau_{0,0} \xrightarrow{t_2} Z^\theta_{2,0}   & Z^\tau_{1,1} \xrightarrow{t_3} Z^\theta_{2,1}       & Z^\tau_{2,2} \xrightarrow{m_2-t_2-t_3} Z^\theta_{2,2}
            \end{array}
          \right].
    \end{array}
    \]
Under the same argument, we can observe that every $Z^\theta_{i,j}$ is coupled with a $Z^\tau_{i',j'}$ with a weakly larger success probability.
This completes the proof of sufficiency.

\smallskip
\textbf{Necessity.}\;
We first show that if the mechanism's enforcement rule is not minimal, it is not SD-truthful.
For a non-minimal enforcement rule, there must exist a report vector $\hat{X}_a$ and an enforced histogram $\Phi$ such that if Alice reports $\hat{X}_a$ truthfully, there exists a diagonal value in the corresponding manipulation matrix that can be increased without breaking the constraints. 
In other words, there exists a strategy $\theta$ whose corresponding manipulation matrix is $\vartheta^\theta$ and a column $j$ such that  $\vartheta^\theta_{j,j}>\vartheta^\tau_{j,j}$.
Then, the strategy $\theta$ is not dominated by truth-telling even when signals are uniformly self-predicting.
This is because by playing $\theta$, Alice can move $\vartheta^\theta_{j,j}-\vartheta^\tau_{j,j}$ samples from \(\mathrm{Bernoulli}(p_{ij})\) or \(\mathrm{Bernoulli}(p_{kj})\) to \(\mathrm{Bernoulli}(p_{jj})\) where $i,k\neq j$.
For self-predicting signals, $p_{jj}$ is the largest column value.

Next, we show that if signals are not uniformly self-predicting, the enforced agreement mechanism is not SD-truthful even when the enforcement rule is minimal.
We can easily find a counterexample by comparing \cref{eq:theta_tau} with \cref{eq:theta_lying}.
Suppose W.L.O.G.~that $\vartheta^\tau_{0,2}< \vartheta^\tau_{1,2}$, then Alice can set $t_1=t_2=t_3=0$ and $t_4 = \max(n_1, m_0-n_0)$ in which case she can move $t_4$ samples from \(\mathrm{Bernoulli}(p_{0,2})\) to \(\mathrm{Bernoulli}(p_{1,2})\), resulting a score distribution that dominates truth-telling.
This completes the proof of necessity.
\end{proof}


\subsection{Truthfulness of EA}
\label{app:ea_truthful}

Given a report vector of Alice $\hat{X}_a$ with an empirical distribution $\Phi_{\hat{X}_a} = (\hat{m}_0,\ldots, \hat{m}_{c-1})$, EA will apply the \emph{IP enforcement rule} by solving the following integer programming.
\begin{align*}
    \max_{\vartheta} \quad & \sum_{i,j\in\Sigma} \vartheta_{i,j} \;p_{ij} \\
    \text{s.t.} \quad & \sum_{i \in \Sigma} \vartheta_{i,j} = n_j, \quad \forall j \in \Sigma, \\
    & \sum_{j \in \Sigma} \vartheta_{i,j} = \hat{m}_i, \quad \forall i \in \Sigma,\\
    & \vartheta_{i,j} \in \mathbb{Z}_{\geq 0}, \quad \forall i, j\in \Sigma.
\end{align*}

Suppose the optimal solution is $\vartheta^*(\hat{X}_a)$.
The mechanism will then randomly select $\vartheta^*(\hat{X}_a)_{i,j}$ questions on which $\hat{X}_a=i$ and flip them to $j$, for any $i,j\in \Sigma$.
After the enforcement step, Alice will be scored based on the output agreement mechanism.

\begin{prop}\label{prop:ea_truthful}
    For any enforcement $\Phi$ and information structure, if $\Pr(X_b\mid X_a)$ is known, the enforcement agreement mechanism with the IP enforcement rule is truthful.
\end{prop}

The proof is straightforward.
Note that to prove truthfulness, it is sufficient to show that truth-telling maximizes the expected score which is $\sum_{i,j\in\Sigma}\vartheta^\tau_{i,j}\;p_{ij}$.
Because the mechanism will manipulate agents' reports in an optimal way by solving the above integer programming, no strategy can achieve a higher expected score than truth-telling.

Note that when $|\Sigma|=2$ and signals are self-predicting, the optimal solution to the above IP does not depend on the information structure $p_{ij}$. 
In particular, the IP enforcement rule always flips the over-reported signal to enforce $n_0$ zeros and $n-n_0$ ones and does not flip any of the under-reported signal.
This echos \cref{thm:ea_binary} which suggests the EA mechanism is SD-truthful in the binary-signal setting without the knowledge of $p$.

\subsection{Optimal Enforcement}
\label{app:opt_enforce}

\begin{proof}[Proof of \cref{lem:std_EA}]
    Suppose Alice observes 0 on $m_0$ out of the $n$ questions and observes 1 on the remaining $n-m_0$ questions.
    There are two cases.

    First, when $m_0\le n_0$, the final score of Alice is the average of the following three type of questions:
    \begin{itemize}
        \item $m_0$ questions where Alice observes 0 and receives a score of 1 if Bob also reports 0.
        \item $n-n_0$ questions where Alice observes 1 and receives a score of 1 if Bob also reports 1.
        \item $n_0-m_0$ questions where Alice observes 1 but receives a score of 1 if Bob reports 0.
    \end{itemize}
    When Alice exerts full effort ($e=1$), Bob's reports (which match his signals) follow the conditional probability distribution $p_{ij} = \Pr(X_b=j\mid X_a=i)$. 
    In contrast, when Alice exerts no effort ($e=0$), her signals are uninformative about Bob's signals, and thus her belief about Bob's reports follows the marginal distribution $M^b_i= \Pr(X_b=i)$.
    Therefore, conditioned on Alice observing 0 in $m_0$ questions, the score defined by EA follows the sum of three binomials:
    \begin{align*}
       & n\cdot S^{EA}(n_0, e=1\mid m_0\le n_0) \sim \mathrm{Bin}(m_0, p_{00}) + \mathrm{Bin}(n-n_0, p_{11}) + \mathrm{Bin}(n_0-m_0, p_{10}),\\
       & n\cdot S^{EA}(n_0, e=0\mid m_0\le n_0) \sim \mathrm{Bin}(m_0, M^b_{0}) + \mathrm{Bin}(n-n_0, M^b_{1}) + \mathrm{Bin}(n_0-m_0, M^b_{0}).
    \end{align*}

    Note that for any question, the probability of Alice observing 0 while exerting effort is the marginal distribution $\Pr(X_a=0)$, which is identical to the probability of observing 0 while exerting no effort.
    This implies that under our definition of effort, the probability of Alice observing 0 on $m_0$ questions does not depend on the effort.
    Let $\rho_0 = \sum_{j\in [n]} (1-X_{a,j})$ be the number of questions where Alice observes $0$.
    The probability that Alice observes 0 on $m_0$ questions is
    \begin{equation*}
        \Pr\left(\rho_0 = m_0\right) = \binom{n}{m_0} (M_0^a)^{m_0} (1-M_0^a)^{n-m_0}.
    \end{equation*}

    Consequently, when $m_0\le n_0$, Alice's score, conditioned on observing 0 in $m_0\le n_0$ questions (which occurs with probability $\Pr\left(\rho_0 = m_0\right)$), follows the distribution:
    \begin{align*}
        n\cdot S^{EA}(n_0, e\mid m_0\le n_0) \sim & \mathrm{Bin}\left(m_0, e\; p_{00} + (1-e)\; M^b_0\right) + \mathrm{Bin}\left(n-n_0, e\; p_{11} + (1-e)\; M^b_1\right) \\
        &+ \mathrm{Bin}\left(n_0-m_0, e\; p_{10} + (1-e)\; M^b_0\right).
    \end{align*}

    In the second case, where $m_0 > n_0$, the final score of Alice is the average of the following three type of questions:
    \begin{itemize}
        \item $n_0$ questions where Alice observes 0 and receives a score of 1 if Bob also reports 0.
        \item $n-m_0$ questions where Alice observes 1 and receives a score of 1 if Bob also reports 1.
        \item $m_0-n_0$ questions where Alice observes 0 but receives a score of 1 if Bob reports 1.
    \end{itemize}
    By the analogous arguments, we know that Alice's score, conditioned on observing 0 in $m_0> n_0$ questions, follows the distribution:
    \begin{align*}
        n\cdot S^{EA}(n_0, e\mid m_0 > n_0) \sim & \mathrm{Bin}\left(n_0, e\; p_{00} + (1-e)\; M^b_0\right) + \mathrm{Bin}\left(n-m_0, e\; p_{11} + (1-e)\; M^b_1\right)\\
        &+ \mathrm{Bin}\left(m_0-n_0, e\; p_{01} + (1-e)\; M^b_1\right).
    \end{align*}

    Putting everything together,
    \begin{equation}\label{eq:S_EA}
          S^{EA}(n_0, e) \sim \sum_{m_0=0}^{n_0} \Pr\left(\rho_0 = m_0\right)\cdot S^{EA}(n_0, e\mid m_0\le n_0) + \sum_{m_0=n_0+1}^{n} \Pr\left(\rho_0 = m_0\right)\cdot S^{EA}(n_0, e\mid m_0> n_0)
    \end{equation}

    Now, we show that the standard deviation of $S^{EA}(n_0, e)$ is independent of $n_0$.
    For simplicity, let $\eta_{ij} = e\; p_{ij} + (1-e)\; M^b_j$.
    Note that $\eta_{i0}+\eta_{i1} = e\; (p_{i0} + p_{i1}) + (1-e)\; (M^b_0 + M^b_1) = 1$.
    Furthermore, the variance of a binomial with parameters $n ,p$ is $n p(1-p)$.
    When $m_0\le n_0$, the variance of the final score is
    \begin{align*}
        \text{var}\left(n\cdot S^{EA}(n_0, e\mid m_0\le n_0)\right) &= m_0\;\eta_{00}\;(1-\eta_{00}) + (n-n_0)\;\eta_{11}\;(1-\eta_{11}) + (n_0-m_0)\;\eta_{10}\;(1-\eta_{10})\\
        &= m_0\;\eta_{00}\;(1-\eta_{00}) + (n-m_0)\;\eta_{11}\;(1-\eta_{11}).
    \end{align*}

    Similarly, when $m_0 > n_0$,
    \begin{align*}
        \text{var}\left(n\cdot S^{EA}(n_0, e\mid m_0> n_0)\right) &= n_0\;\eta_{00}\;(1-\eta_{00}) + (n-m_0)\;\eta_{11}\;(1-\eta_{11}) + (m_0-n_0)\;\eta_{01}\;(1-\eta_{01})\\
        &= m_0\;\eta_{00}\;(1-\eta_{00}) + (n-m_0)\;\eta_{11}\;(1-\eta_{11}).
    \end{align*}
    Therefore, conditioned on observing 0 on $m_0$ questions, the standard deviation $\text{std}\left(S^{EA}(n_0, e\mid m_0)\right) = \sqrt{m_0\;\eta_{00}\;(1-\eta_{00}) + (n-m_0)\;\eta_{11}\;(1-\eta_{11})}$ is independent of $n_0$.
    Consequently, the standard deviation of the final score, averaging over $m_0$, is also independent of $n_0$.
\end{proof}

\begin{proof}[Proof of \cref{prop:opt_enforce}]
    By \cref{lem:std_EA}, the standard deviation of the EA mechanism is independent of the enforcement $\Phi$.
    Therefore, the enforcement that maximizes the sensitivity is the one that maximizes the derivative of the expected score w.r.t.~effort $e$.
    By \cref{eq:S_EA}, the score given by EA can be expressed as the average of many binomial variables.
    Note that the expectation of a binomial variable with parameter $(n,p)$ is $n\cdot p$. 
    We thus have
    \begin{align*}
        &n\cdot\mathbb{E}\left[S^{EA}(n_0, e\mid m_0\le n_0)\right] = m_0\eta_{00} + (n-n_0)\;\eta_{11} + (n_0-m_0)\;\eta_{10}\\
        &n\cdot\mathbb{E}\left[S^{EA}(n_0, e\mid m_0> n_0)\right] = n_0\eta_{00} + (n-m_0)\;\eta_{11} + (m_0-n_0)\;\eta_{01},   
    \end{align*}
    where $\eta_{ij} = e\; p_{ij} + (1-e)\; M^b_j$.
    The derivative of $\eta_{ij}$ w.r.t.~$e$ is thus $\eta_{ij}' = p_{ij} - M^b_j$.

    We aim to find the $n_0$ that maximizes
    \begin{align*}
        \frac{\partial \mathbb{E}\left[S^{EA}(n_0,e)\right]}{\partial e} =& \sum_{m_0=0}^{n_0} \Pr\left(\rho_0 = m_0\right)\cdot \left(m_0\;\eta'_{00} + (n-n_0)\;\eta'_{11} + (n_0-m_0)\;\eta'_{10}\right)\\
        & + \sum_{m_0=n_0+1}^{n} \Pr\left(\rho_0 = m_0\right)\cdot\left(n_0\;\eta'_{00} + (n-m_0)\;\eta'_{11} + (m_0-n_0)\;\eta'_{01}\right).
    \end{align*}
    Let $n_0$ increase by 1:
    \begin{align*}
        \frac{\partial \mathbb{E}\left[S^{EA}(n_0+1,e)\right]}{\partial e} =& \sum_{m_0=0}^{n_0+1} \Pr\left(\rho_0 = m_0\right)\cdot \left(m_0\;\eta'_{00} + (n-n_0-1)\;\eta'_{11} + (n_0+1-m_0)\;\eta'_{10}\right)\\
        & + \sum_{m_0=n_0+2}^{n} \Pr\left(\rho_0 = m_0\right)\cdot\left((n_0+1)\;\eta'_{00} + (n-m_0)\;\eta'_{11} + (m_0-n_0-1)\;\eta'_{01}\right).
    \end{align*}
    Therefore, the marginal return of increasing $n_0$ is given by
    \begin{align*}
        d \nabla S^{EA}(n_0)&=\frac{\partial \mathbb{E}\left[S^{EA}(n_0+1,e)\right]}{\partial e} - \frac{\partial \mathbb{E}\left[S^{EA}(n_0,e)\right]}{\partial e}\\
        &= \sum_{m_0=0}^{n_0} \Pr\left(\rho_0 = m_0\right)\cdot \left(\eta'_{10} - \eta'_{11}\right)+ \sum_{m_0=n_0+1}^{n} \Pr\left(\rho_0 = m_0\right)\cdot\left(\eta'_{00} - \eta'_{01}\right).
    \end{align*}
    Note that 
    \begin{align*}
        \eta'_{10} - \eta'_{11} &= p_{10}-M^b_0 - p_{11}+M^b_1\\
        &= -2(p_{11}-M^b_1) \tag{$p_{01}=1-p_{11}$, and $M^b_0 = 1-M^b_1$.}\\
        &= -2(p_{11} - (M^a_0\; p_{01} + M^a_1\; p_{11}))\\
        &= -2(p_{11}\; (1-M^a_1) - p_{01}M^a_0)\\
        &= -2\;M^a_0\;(p_{11}-p_{01})\\
        &<0 \tag{By self-prediction.}
    \end{align*}
    Similarly, we can show that $\eta'_{00} - \eta'_{01}>0$.

    Therefore, when $n_0 = 0$, $d \nabla S^{EA}(0)>0$, and when  $n_0 = n$, $d \nabla S^{EA}(n)<0$.
    Furthermore, $d \nabla S^{EA}(n_0)$ decreases in $n_0$.
    The sensitivity-maximizing $n_0$ is thus the largest integer such that $d \nabla S^{EA}(n_0) > 0$.
    Let $F(k) = \sum_{m_0=0}^{k} \Pr\left(\rho_0 = m_0\right)$.
    \begin{align*}
        &d \nabla S^{EA}(n_0) > 0\\
       \Leftrightarrow \quad& F(n_0)\left(\eta'_{10} - \eta'_{11}\right) + (1-F(n_0)) \left(\eta'_{00} - \eta'_{01}\right) >0\\
       \Leftrightarrow \quad& F(n_0) < \frac{\eta'_{00} - \eta'_{01}}{\eta'_{00} - \eta'_{01} + \eta'_{11} - \eta'_{10}}.
    \end{align*}

\end{proof}

\section{Matching Agreement (MA)}
\label{app:matching}

The matching agreement mechanism is a follow-up of the correlated agreement mechanism aiming to address more complex cheating strategies \citep{zhang2023omni}.
Similar to CA, which determines ``agreement'' using the delta matrix (see \cref{subsec:ca}), MA determines ``agreement'' using a different method depending on the information structure.
\begin{definition}
    Let $\Gamma$ be a $|\Sigma|\times|\Sigma|\times|\Sigma|$ tensor where 
    \begin{equation*}
        \Gamma_{\sigma_1,\sigma_2,\sigma_3} = \Pr(X_a = \sigma_1 \mid X_b = \sigma_2) - \Pr(X_a = \sigma_1 \mid X_b = \sigma_3). 
    \end{equation*}
\end{definition}
The agreement function is thus $T_\Gamma = \text{Sign}(\Gamma)$, i.e.~$T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) = 1$ if $\Gamma_{\sigma_1,\sigma_2,\sigma_3} > 0$, and 0 otherwise.

Next, the mechanism randomly samples a bonus question $j$ and a penalty question $k$ uniformly at random.
An individual score computed using these two questions is thus $S^{MA}_i=T_\Gamma(\hat{X}_{a,j}, \hat{X}_{b,j}, \hat{X}_{b,k})$.
In words, the matching agreement mechanism awards Alice a score of 1 if, when predicting her response on question $b$, the posterior conditioned on Bob's response to the same question provides a better prediction than the posterior conditioned on Bob's response on a different question $q$.
Similar to CA, each bonus question can be paired with $n-1$ penalty questions. Therefore, the final score of MA is the average of $n\cdot (n-1)$ individual scores.

\paragraph{The Sensitivity of MA Under the Partition Rounding Reduction}
We further investigate the sensitivity of the MA mechanism under the partition reduction.
The MA mechanism requires two questions to compute an individual score, implying that $K=n/2$.
Clearly, $S_{\inf} = 0$ and $S_{\sup}=1$ by definition.
By \cref{eq:delta_partition}, to compute the sensitivity, we only need to compute the expected individual score $m_i(e)$ and its derivative.
When Alice exerts full effort, the probability of obtaining a score of 1 can be computed as follows:
\begin{align*}
    m_i^{MA}(1) &= \sum_{\sigma_1,\sigma_2,\sigma_3} \Pr(X_{a,j} = \sigma_1, X_{b,j} = \sigma_2, X_{b,k} = \sigma_3) \cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right)\\
    &= \sum_{\sigma_1,\sigma_2,\sigma_3} J_{\sigma_1,\sigma_2}M^b_{\sigma_3}\cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right)\\
    % \intertext{We can sum over the signals twice but reorder the summation over $\sigma_2$ and $\sigma_3$ in the second time. Then, combining the re-ordered summation with the original summation term-wisely gives us}
    &= \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} J_{\sigma_1,\sigma_2}M^b_{\sigma_3}\cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) + \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} J_{\sigma_1,\sigma_3}M^b_{\sigma_2}\cdot T_\Gamma\left(\sigma_1,\sigma_3,\sigma_2\right)\\  
    &= \frac{1}{2} + \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} \left(J_{\sigma_1,\sigma_2}M^b_{\sigma_3}-J_{\sigma_1,\sigma_3}M^b_{\sigma_2}\right)\cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) \tag{Note that $T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) = 1 - T_\Gamma\left(\sigma_1,\sigma_3,\sigma_2\right)$.}\\
    &= \frac{1}{2} + \frac{1}{2} \sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;\Gamma_{\sigma_1,\sigma_2,\sigma_3}\;T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right)\\
    &= \frac{1}{2} + \frac{1}{2} \sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+
\end{align*}
where $(x)^+ = x$ if $x>0$ and 0 otherwise.

When Alice exerts no effort,
\begin{align*}
    m_i^{MA}(0) &= \sum_{\sigma_1,\sigma_2,\sigma_3} \Pr(\hat{X}_{a,j} = \sigma_1, X_{b,j} = \sigma_2, X_{b,k} = \sigma_3) \cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right)\\
    &= \sum_{\sigma_1,\sigma_2,\sigma_3} M^a_{\sigma_1}M^b_{\sigma_2}M^b_{\sigma_3}\cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right)\\
    &= \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} M^a_{\sigma_1}M^b_{\sigma_2}M^b_{\sigma_3}\cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) + \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} M^a_{\sigma_1}M^b_{\sigma_2}M^b_{\sigma_3}\cdot T_\Gamma\left(\sigma_1,\sigma_3,\sigma_2\right)\\  
    &=\frac{1}{2} + \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} \left(M^a_{\sigma_1}M^b_{\sigma_2}M^b_{\sigma_3}-M^a_{\sigma_1}M^b_{\sigma_2}M^b_{\sigma_3}\right)\cdot T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) \tag{Note that $T_\Gamma\left(\sigma_1,\sigma_2,\sigma_3\right) = 1 - T_\Gamma\left(\sigma_1,\sigma_3,\sigma_2\right)$.}\\
    &= \frac{1}{2}
\end{align*}
The expected score while exerting effort $e$ is a convex combination of $m_i^{MA}(1)$ and $m_i^{MA}(0)$, i.e.~$m_i^{MA}(e) = \frac{1}{2} + \frac{e}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+$, and $\nabla m_i^{MA}(e) = \frac{1}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+$.

When signals are binary, we find that MA reduces to CA.
\begin{lemma}\label{lem:ma_ca}
    When signals are binary, $\sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+ = \sum_{\sigma_1,\sigma_2} (\Delta_{\sigma_1,\sigma_2})^+$.
\end{lemma}
\begin{proof}
    First note that by definition, $\Gamma_{\sigma_1,\sigma_2,\sigma_3} = 0$ when $\sigma_2 = \sigma_3$.
    Therefore, when signals are binary, 
    \begin{align*}
        \sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+ &= \sum_{\sigma_1,\sigma_2} M^b_{\sigma_2}M^b_{1-\sigma_2}\;(\Gamma_{\sigma_1,\sigma_2,1-\sigma_2})^+\\
        &= \sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+ \\
        &= \sum_{\sigma_1,\sigma_2} (J_{\sigma_1,\sigma_2}M^b_{1-\sigma_2} - J_{\sigma_1,1-\sigma_2}M^b_{\sigma_2})^+\\
        &= \sum_{\sigma_1,\sigma_2} (J_{\sigma_1,\sigma_2}\;(1-M^b_{\sigma_2}) - ((M^a_{\sigma_1}-J_{\sigma_1,\sigma_2})\;M^b_{\sigma_2})^+ \tag{Signals are binary.}\\
        &= \sum_{\sigma_1,\sigma_2} (J_{\sigma_1,\sigma_2} - M^a_{\sigma_1}M^b_{\sigma_2})^+\\
        &= \sum_{\sigma_1,\sigma_2} (\Delta_{\sigma_1,\sigma_2})^+
    \end{align*}
\end{proof}

An immediate consequence of \cref{lem:ma_ca} is that the expected score under MA is a linear transformation of the expected score under CA.
This further implies that the partition rounding reductions of MA and CA has the same sensitivity under the binary-signal setting.

\begin{prop}
    When signals are binary, $\delta^{MA}(e) = \delta^{CA}(e)$ under the partition rounding reduction.
\end{prop}
\begin{proof}
    By \cref{lem:ma_ca}, we know that \[m_i^{MA}(e) = \frac{1}{2} + \frac{e}{2}\sum_{\sigma_1,\sigma_2,\sigma_3} M^b_{\sigma_2}M^b_{\sigma_3}\;(\Gamma_{\sigma_1,\sigma_2,\sigma_3})^+ =  \frac{1}{2} + \frac{e}{2} \sum_{\sigma_1,\sigma_2} (\Delta_{\sigma_1,\sigma_2})^+ = \frac{1}{2} + \frac{1}{2} m_i^{CA}(e),\]
    \[\nabla m_i^{MA}(e) = \frac{1}{2} \nabla m_i^{CA}(e).\]
    By \cref{eq:delta_partition},
    \begin{align*}
        \delta^{MA}(e) &= \frac{\nabla m_i^{MA}(e)\cdot \sqrt{n/2}}{\sqrt{\left(m_i^{MA}(e) -S^{MA}_{\inf} \right) \left(S^{MA}_{\sup} - m_i^{MA}(e) \right)}}\\
        &= \frac{\frac{1}{2}\nabla m_i^{CA}(e)\cdot \sqrt{n/2}}{\sqrt{\left(\frac{1}{2}m_i^{MA}(e) + \frac{1}{2}\right) \left(\frac{1}{2} - \frac{1}{2} m_i^{MA}(e) \right)}}\\
        &= \frac{\nabla m_i^{CA}(e)\cdot \sqrt{n/2}}{\sqrt{\left(m_i^{MA}(e) + 1\right) \left(1 - m_i^{CA}(e) \right)}}\\
        &= \delta^{CA}(e).
    \end{align*}
\end{proof}

\section{Experiments (Continue)}
\label{app:experiment}
\subsection{Varying the Signal Prior }\label{app:vary_prior}
In \cref{fig:optimal_ea}, we visualize the sensitivities while varying the marginal distribution of the signal prior $\Pr[X_a=0] \in [0.1, 0.9]$.
To do so, we consider the following joint distribution:
\[
J = 
\begin{pmatrix}
\Pr[X_a=0] \cdot 0.75 & \Pr[X_a=0] \cdot 0.25 \\
(1 - \Pr[X_a=0]) \cdot 0.25 & (1 - \Pr[X_a=0]) \cdot 0.75
\end{pmatrix}.
\]
In the figure, we vary $\Pr[X_a=0]$ with a step size 0.01 from 0.1 to 0.9.


\subsection{Information Structure}\label{app:structure}

For Section~\ref{subsec:empirical_comparison} and \ref{subsec:empirical_budgetary_efficiency}, we consider two real-world crowdsourcing datasets, each having a signal space of size $|\Sigma_1|=2$ and $|\Sigma_2|=4$.
The information structure between a pair of agents can be characterized by a Dawid-Skene model \citep{dawid1979maximum}.
In particular, each task has an underlying ground truth $\omega$ that is i.i.d.~sampled from a prior distribution $W$. 
Conditioning on $\omega$, each agent receives a signal $\sigma$ according to conditioned distribution $\Gamma$, where $\Gamma_{i,j} = \Pr[\sigma=j\mid \omega=i]$. 

In the first dataset \citep{baba2018wisdom}, $18$ agents each labels whether a compound is appropriate or inappropriate to be synthesized.
The prior of the ground truth and the conditioned signal distribution are
\[w_1 = \bigl[ \begin{matrix} 0.613 & 0.387\end{matrix}\bigr],\qquad \Gamma_1 = \begin{bmatrix} 
0.905 & 0.095 \\
0.283 & 0.717
\end{bmatrix}.\]
In the second dataset \citep{soton376543}, $110$ agents provide the annotations of the sentiment of $300$ tweets.
There are four ground truth labels and four possible signals where the information structure is
\begin{equation*}
w_2 = \bigl[ \begin{matrix}0.196 & 0.241 & 0.247 & 0.316\end{matrix}\bigr],\qquad \Gamma_2 = \left[ \begin{matrix}0.770 & 0.122 & 0.084 & 0.024\\ 0.091 & 0.735 & 0.130 & 0.044\\0.033 & 0.062 & 0.866 & 0.039 \\ 0.068 & 0.164 & 0.099 & 0.669 \end{matrix}\right].
\end{equation*}

