\section{Proof of Proposition 3}

\noindent
{\em Proposition 3} \\
Given a consistent CondASP program $(\Pi,K)$, entailment from $(\Pi,K)$ satisfies the KLM postulates above.    


\begin{proof}
Let ${\emme^\Pi_K}= \sx \WW, \{<_{A_i}\}, v \dx$.

\noindent
- $\mathit{(Reflexivity)}$ By definition, if $S \in Min_{<_{A}}([[A]]^{{\emme^\Pi_K}})$, then $S \in [[A]]^{{\emme^\Pi_K}}$. Therefore, ${\emme^\Pi_K} \models \tip(A)  \rightarrow A $ holds.


\noindent
- $\mathit{(Right\; Weakening)}$ Let us assume that $\models  \mathit{B \rightarrow  C}$ and that   ${\emme^\Pi_K} \models \mathit{\tip(A) \ri B}$. We have to prove that  ${\emme^\Pi_K} \models \mathit{ \tip(A) \ri C} $ holds. 

From ${\emme^\Pi_K} \models \mathit{\tip(A) \ri B}$, we have 
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[B]]^{{\emme^\Pi_K}}$.

From $\models  \mathit{B \rightarrow  C}$, it follows that
$[[B]]^{\emme^\Pi_K} \subseteq [[C]]^{{\emme^\Pi_K}}$, and the thesis follows as well.

\noindent
- $\mathit{(Left \; Logical\; Equivalence)}$
Let us assume that $\models \mathit{A \equiv B}$ 
and that
$ {\emme^\Pi_K} \models \mathit{\tip(A) \ri C}$. 
We have to prove that ${\emme^\Pi_K} \models\mathit{\tip(B) \ri  C} $.

From $\models \mathit{A \equiv B}$, it follows that 
$[[A]]^{\emme^\Pi_K} = [[B]]^{{\emme^\Pi_K}}$.
From $ {\emme^\Pi_K} \models \mathit{\tip(A) \ri C}$, we have 
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[C]]^{{\emme^\Pi_K}}$.

To prove that ${\emme^\Pi_K} \models \mathit{\tip(B) \ri C}$, assume $S \in Min_{<_{B}}([[B]]^{{\emme^\Pi_K}})$. By the equivalence of $A$ and $B$, 
$S \in Min_{<_{B}}([[A]]^{{\emme^\Pi_K}})$.
By Proposition \ref{prop_equiv_preorders}, $<_A$ and $<_B$ are the same preference relation, and therefore $S \in Min_{<_{A}}([[A]]^{{\emme^\Pi_K}})$. Thus, it follows that $S \in [[C]]^{{\emme^\Pi_K}}$. We have proved that  
$Min_{<_{B}}([[B]]^{{\emme^\Pi_K}}) \subseteq [[C]]^{{\emme^\Pi_K}}$,
that is, ${\emme^\Pi_K} \models \mathit{\tip(B) \ri C}$.

\noindent
- $\mathit{(And)}$
Let us assume that ${\emme^\Pi_K} \models \mathit{\tip(A) \ri B}$ and that ${\emme^\Pi_K} \models \mathit{\tip(A) \ri C}$. We have to prove that ${\emme^\Pi_K} \models \mathit{\tip(A) \ri  B \wedge C} $.

From the hypothesis, 
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[B]]^{{\emme^\Pi_K}}$ and
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[C]]^{{\emme^\Pi_K}}$ hold.

Assume that $S \in Min_{<_{A}}([[A]]^{{\emme^\Pi_K}})$. Then
$ S \in [[B]]^{{\emme^\Pi_K}}$ and $S \in [[C]]^{{\emme^\Pi_K}}$.
It follows that $S \in [[B \wedge C ]]^{{\emme^\Pi_K}}$. Therefore,
${\emme^\Pi_K} \models \mathit{\tip(A) \ri  B \wedge C} $.



\noindent
- $\mathit{(Or)}$ 
Let us assume that ${\emme^\Pi_K} \models \mathit{\tip(A) \ri  C} $ and that  ${\emme^\Pi_K} \models   \mathit{\tip(B) \ri C}$. We have to prove that ${\emme^\Pi_K} \models  \mathit{\tip(A \vee B) \ri C} $. 

From the hypothesis, 
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[C]]^{{\emme^\Pi_K}}$ and
$Min_{<_{B}}([[B]]^{{\emme^\Pi_K}}) \subseteq [[C]]^{{\emme^\Pi_K}}$ hold.
%
Assume that, $S$ is a minimal answer set for $A \vee B$, that is, $S \in Min_{<_{A\vee B}}([[A \vee B]]^{{\emme^\Pi_K}})$. We want to prove that $S \in [[C]]^{{\emme^\Pi_K}}$.

By absurd, suppose $S$ is neither a minimal answer set for $A$, nor a minimal answer set for $B$.
That is,
there is an $S' \in [[A]]^{{\emme^\Pi_K}}$, such that $S' <_A S$ and there is an $S'' \in [[B]]^{{\emme^\Pi_K}}$, such that $S' <_B S$.
It holds that $S',S'' \in [[A \vee B]]^{{\emme^\Pi_K}}$.
However, $S' \not <_{A\vee B} S$ and $S'' \not <_{A\vee B} S$, otherwise $S$ would not be a minimal answer set for $A \vee B$.

From the fact that $S' \not <_{A\vee B} S$, it follows that  $S \leq_{A\vee B} S'$, and that $W_{A \vee B}(S) \geq W_{A \vee B}(S') $. Clearly, from the definition of the weights, $W_{A \vee B}(S') \geq W_A(S') $. From $S' <_A S$, we have $ W_A(S') > W_A(S) $. Therefore, 
$$W_{A \vee B}(S) \geq W_{A \vee B}(S') \geq W_A(S')  > W_A(S), $$ 
so that $W_{A \vee B}(S) > W_A(S) $.

Similarly, from the fact that $S'' \not <_{A\vee B} S$ and $S'' <_B S$,
we get
$$W_{A \vee B}(S) \geq W_{A \vee B}(S'') \geq W_B(S'')  > W_B(S), $$ 
so that $W_{A \vee B}(S) > W_B(S) $.
However, from the definition of the weights $W_{A_1 \vee A_2}(S)= max( W_{A_1}(S), W_{A_2}(S))$, it cannot be the case that $W_{A_1 \vee A_2}(S)> W_A(S)$ and $W_{A_1 \vee A_2}(S)> W_B(S)$, a contradiction.

Therefore, either $S$ ia a minimal answer set for $A$ ($S \in Min_{<_{A}}([[A]]^{{\emme^\Pi_K}})$) or $S$ ia a minimal answer set for $B$ ($S \in Min_{<_{B}}([[B]]^{{\emme^\Pi_K}})$).
In both cases, it follows from the hypothesis that $S \in [[C]]^{{\emme^\Pi_K}}$.
Therefore, 
$Min_{<_{A\vee B}}([[A \vee B]]^{{\emme^\Pi_K}}) \subseteq  [[C]]^{{\emme^\Pi_K}}$, and the thesis follows, that is ${\emme^\Pi_K} \models  \mathit{\tip(A \vee B) \ri C} $. 

\noindent
- $\mathit{(Cautious \; Monotonicity)}$ 

Let us assume that ${\emme^\Pi_K} \models \mathit{\tip(A) \ri  B} $ and that  ${\emme^\Pi_K} \models   \mathit{\tip(A) \ri C}$. We have to prove that ${\emme^\Pi_K} \models  \mathit{\tip(A \wedge B) \ri C} $. 

From the hypothesis, 
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[B]]^{{\emme^\Pi_K}}$ and
$Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) \subseteq [[C]]^{{\emme^\Pi_K}}$ hold.

Let us assume that 
$S \in Min_{<_{A\wedge B}}([[A \wedge B]]^{{\emme^\Pi_K}}) $.
As
$W_{A \wedge B} (S) = min\{ W_A(S), W_B(S) \} $, it holds that $W_{A \wedge B} (S) \geq W_A(S)$.

We want to prove that $S \in Min_{<_{A}}([[A]]^{{\emme^\Pi_K}}) $.
Suppose by absurd that it does not hold.
Then, there must be an answer set $S'$, such that $S' <_A S$ and $S' \in [[A]]^{{\emme^\Pi_K}}$.
Therefore, $W_A(S')>W_A(S)$.
Without loss of generality, we can assume that $S'$ is $<_A$-minimal among the answer sets satisfying $A$.  In this case, it also holds that $S \in [[B]]^{{\emme^\Pi_K}}$, so that $S$ satisfies $A \wedge B$.

As $S$ is a minimal answer set satisfying $A \wedge B$, $W_{A \wedge B}(S) \geq W_{A \wedge B}(S')$. Therefore, 
$W_{A \wedge B}(S) \geq W_{A \wedge B}(S') \geq W_A(S') > W_A(S) $. It follows that, 
$W_{A \wedge B}(S) > W_A(S) $, a contradiction.

Therefore, $S \in Min_{<_{A}}([[A]]^{{\emme^\Pi_K}})$ must hold, and 
and $S \in [[C]]^{{\emme^\Pi_K}}$. 
Therefore, 
$Min_{<_{A\wedge B}}([[A \vee B]]^{{\emme^\Pi_K}}) \subseteq  [[C]]^{{\emme^\Pi_K}}$, and the thesis follows, that is, ${\emme^\Pi_K} \models  \mathit{\tip(A \wedge B) \ri C} $. 


\end{proof}

\section{Rational Monotonicity}


\begin{proposition}
Given a CondASP program $(\Pi,K)$, entailment from $(\Pi,K)$ does not satisfy the Rational Monotonicity.    
\end{proposition}

\begin{proof}
We provide a counterexample to Rational Monotonicity, a CondASP program $(\Pi,K)$ such that, 
${\emme^\Pi_K} \models \mathit{\tip(A) \ri  C} $ and   ${\emme^\Pi_K} \not \models   \mathit{\tip(A) \ri \neg B}$, but ${\emme^\Pi_K} \not \models  \mathit{\tip(A \wedge B) \ri C} $.

Let the ASP program $\Pi$ contain the rules:
\begin{quote}
$ \mathit{
1 \{ penguin; warbler; raven; zebra \} 1.
} $

$ \mathit{
 \{ flies \}  \ \text{:--} \ bird.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 
$ \mathit{has\_wings  \ \text{:--} \ bird.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \  
$ \mathit{  1\{ grey; black \& white \}1   \ \text{:--} \ penguin.
} $

$ \mathit{bird  \ \text{:--} \ penguin.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 
$ \mathit{bird  \ \text{:--} \ warbler.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 
$ \mathit{bird  \ \text{:--} \ raven.
} $


$ \mathit{black \& white  \ \text{:--} \ warbler.
} $
\ \ \ \ \ \ \ \ \ 
$ \mathit{ flies \ \text{:--} \ raven.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \  
$ \mathit{ flies \ \text{:--} \ warbler.
} $



$ \mathit{black \& white  \ \text{:--} \ zebra.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \  
$ \mathit{ has\_4\_legs \ \text{:--} \ zebra.
} $
 \ \ \ \ \ \ \ \ \ \ \ \ \ 
$ \mathit{black  \ \text{:--} \ raven.
} $

$ \mathit{  \text{:--} \ has\_4\_legs, has\_wings.
} $ \ \ \ \ \ \ \ \  
$ \mathit{  \text{:--} \ zebra, bird.
} $ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ \ 
$ \mathit{  \text{:--} \ zebra, flies.
} $


$ \mathit{   \text{:--} \ black \& white, grey.
} $
\ \ \ \ \ \ \ \ \ \ \ \ \ \ 
$ \mathit{   \text{:--} \ black \& white, black.
} $
\ \ \ \ \ \ \ \ \ 
$ \mathit{   \text{:--} \ black,  grey.
} $

\end{quote}
where $\mathit{Bird}$, $\mathit{Penguin}$ and $\mathit{Black \& White}$ 
are distinguished propositions (propositional variables), and $K$ contains the following defeasible implications:

 \begin{quote}
 $\mathit{\tip(bird) \ri flies}$, \ \ +40 

$\mathit{\tip(bird) \ri has\_wings}$, \ \ +50

$\mathit{\tip(bird) \ri  has\_4\_legs}$, \ \ -50 

$\mathit{\tip(penguin) \ri   black \& white}$, \ \ +30 


$\mathit{\tip(black \& white) \ri   penguin}$, \ \  +80


$\mathit{\tip({black \& white}) \ri zebra}$, \ \ +80 

$\mathit{\tip(black \& white) \ri   warbler}$, \ \ +10

$\mathit{\tip(black \& white) \ri   raven}$, \ \ -40


\end{quote}
The answer sets of program $\Pi$ the following: 

$\mathit{S_1= \{bird, warbler, flies, has\_wings, black \& white\} }$

$\mathit{S_2= \{bird, raven, flies, has\_wings, black\} }$

$\mathit{S_3= \{bird, penguin, has\_wings, black \& white\} }$

$\mathit{S_4= \{bird, penguin, has\_wings, grey\} }$

$\mathit{S_5= \{zebra, has\_4\_legs, black \& white\} }$

\noindent
It is easy to see that 
${\emme^\Pi_K} \models \mathit{\tip(bird) \ri  flies} $ and  that  ${\emme^\Pi_K} \not \models   \mathit{\tip(bird) \ri \neg black \& white}$.
%
Note that both $\mathit{S_1}, \mathit{S_2} \in min_{<_{bird}}([[Bird]]^{\emme^\Pi_K})$, while $\mathit{S_3, S_4, S_5} \not\in min_{<_{bird}}([[Bird]]^{\emme^\Pi_K})$ (as $W_{bird}(S_1)= W_{bird}(S_2)= +90$, $W_{bird}(S_3)= W_{bird}(S_4)= +50$ and $W_{bird}(S_5)= -50$).
%
$\mathit{S_1}$ describes  a typical bird, a warbler, who is black and white, while $S_3$ describes a typical black and white bird, a penguin. 

In particular, we have:\\
$\mathit{W_{bird \wedge black \& white} (S_1)}$ 
$= \mathit{ min\{W_{bird}(S_1), W_{black \& white}(S_1) \} }$$=\mathit{min\{+90, +10 \}= +10}$,
\\
$\mathit{W_{bird \wedge black \& white} (S_2)}$ 
$= \mathit{ min\{W_{bird}(S_2), W_{black \& white}(S_2) \} }$$=\mathit{min\{+90, -40 \}= -40}$,
\\
$\mathit{W_{bird \wedge black \& white} (S_3)}$ 
$= \mathit{ min\{W_{bird}(S_3), W_{black \& white}(S_3) \} }$$=\mathit{min\{+50, +80 \}= +50}$,
\\
$\mathit{W_{bird \wedge black \& white} (S_4)}$ 
$= \mathit{ min\{W_{bird}(S_4), W_{black \& white}(S_4) \} }$$=\mathit{min\{+50, +80 \}= +50}$,
\\
$\mathit{W_{bird \wedge black \& white} (S_5)}$ 
$= \mathit{ min\{W_{bird}(S_5), W_{black \& white}(S_5) \} }$$=\mathit{min\{-50, +80 \}= -50}$.


It follows that $S_3$ is the only answer set in $min_{<_{bird \wedge black \& white}}([[bird \wedge black \& white]]^{\emme^\Pi_K})$ (note that $black \& white$ is false in $S_4$).   
As $S_3 \not \in [[flies]]^{\emme^\Pi_K}$, then
${\emme^\Pi_K} \not \models  \mathit{\tip(bird \wedge black \& white) \ri flies} $, which 
falsifies Rational Monotonicity.


\end{proof}


