\begin{algorithm}[H]
\SetAlgoRefName{{\upshape\scshape Evacuation}}
   \caption{(Input: none)}
   \label{alg:Evacuation}
   $\B=2$\;
   \While{there are agents present in the graph}{
      Compute a $\B$-partition $(V_1,\ldots,V_l)$ \label{ln:evac-partition}\;
      Call Algorithm~\ref{alg:OneAttempt}($\B,(V_1,\ldots,V_l)$) \label{ln:evac-phase}\;
      $\B=2\B$
   }
\end{algorithm}
