\texttt{`\hspace{0.05mm}`\hspace{0.05mm}`sql}\\
\textcolor{red!80}{\texttt{SELECT COUNT(ID) AS NumberOfPatients, ID FROM Patient WHERE SEX = 'F' AND strftime('\%Y', Birthday) = '1964' AND Admission = '+'}}; \scalebox{0.8}{\textcolor{red}{\XSolidBrush}} \\
