\section{Current Proposal}
Given: $M$ paths $(y_{[0:T]}^m,x_{[0:T]}^m)_{m=1}^M$.  Fix a reservoir system $\varphi:\mathbb{R}^L\times \mathbb{R}^d\rightarrow \mathbb{R}^p$, for a ``latent dimension'  $L$ and a reservoir dimension ``$p$'', where $L,p\in \mathbb{N}$.  \textit{In practice, $\varphi$ will be a pre-trained DL model like AlexNet or something.}  Consider a ``good'' linear approximation to $\varphi$, $Bz + Cx \approx \varphi$ \textit{to be made precise}.
\begin{enumerate}
    \item \textbf{Proposal Stage:}  Each player proposes (calibrates) a model 
    $X^i_t = X^i_0 + \int_0^t A_i X^i_s ds + \int_0^t \sigma_i d W^i_s$ by minimizing
    \[
    \min_{A,\sigma}\, \frac1{J}\sum_{m=j}^J \mathbb{E}\big[\| X_t^i - x_t^{m_{i,j}}  \|^2 \big]
    \]
    where $(m_{i,1},\dots,m_{i,J})$ is a different (random) subset of the training paths.  \textit{Link to N-fold cross-validation in current formulation.  Link to ``masking'' as a type of noising.  Our objective is then to recover true "full information" ie ``unmasking/denoising''.}
    \item \textbf{Competition State:} Each player competes to justify their proposed model 
    \[
    \begin{aligned}
        & Z^i_t = Z^i_0 + 
\int_0^t \varphi(Z^i_s, X^i_s) ds  \approx 
Z^i_0 + 
\int_0^t B Z^i_s + C X^i_s ds \\ 
& \hat{Y}^i_t = \beta^i Z_0^i + \int_0^t \beta^i_s Z^i_s 
 ds  , \quad i = 1, ..., N . 
    \end{aligned}
    \]
    as being the correct one.  They do so by minimizing~\eqref{Ji}.  
    \item \textbf{Selection State:} Fix a ``memory parameter'' $M\in \mathbb{N}_+$ and consider a compact set of continuous functions $\mathcal{H}$, in the uniform convergence on compacts topology, mapping $w:\mathbb{R}^{(1+d)M}\rightarrow \Delta_N$.  We learn closed-loop dynamics by optimizing
    \[
        \min_{w\in \mathcal{H}}\, \frac1{M}\,\sum_{m=1}^M\,
        \mathbb{E}\Big[
            \sum_{t=0}^T\,e^{-t}\,\|y_t - \sum_{i=1}^N\, w(y_{[t-M:t-1]},x_{[t-M:t-1]})_i \hat{Y}^i\|^2
        \Big]
    \]
    \textit{we will implement $\mathcal{H}$ as a class of NNs, or randomized NNs.  We benchmark against the greedy algorithm~\eqref{Nashw}}
\end{enumerate}

