The objective is to find a 
\begin{align} 
 \min_{\beta^0} \mathbb{E} \Big[ \frac{1}{\tau} \sum_{t=\tau+1}^{T+\tau} \Big\| \beta^{0T}_t 
  Z^0_t - \sum_{i=1}^N \beta^{iT}_t Z^i(X_{[0,t]}) 
 \Big\|^2 \Big]  + \frac{1}{1+T} \sum_{t=0}^T \Big\| \beta^{0T}_t Z^0_t - y_t \Big\|^2 \notag 
\end{align}

First order condition for $t=0, 1, ..., T$: 
\begin{align} 
 \frac{2}{1+T}  Z^0_t (\beta^{0\top}_t Z^0_t - y_t) = 0 , \notag 
\end{align} 
which gives the optimal $\beta^0_t$ for each $t=0$, $1$, ..., $T$: 
\begin{align} 
  \beta^0_t = (Z^0_t Z^{0\top}_t )^{-1} Z^0_t y_t  \notag 
\end{align} 

For $t=T+1$, ..., $T+\tau$, the first order condition 
\begin{align} 
  \frac{2}{\tau} Z^0_t \Big( \beta^{0\top} Z^0_t - \sum_{i=1}^N \beta^{i\top}_t Z^i_t \Big) = 0 \notag 
\end{align} 
which gives the optimal $\beta^0_t$ for each $t=T+1$, $T+2$, ..., $T+\tau$:  
\begin{align} 
  \beta^0_t = (Z^0_t Z^{0\top}_t )^{-1} Z^0_t \sum_{i=1}^N \beta^{i\top}_t Z^i_t .   \notag 
\end{align} 



\subsection{Game-Theoretic Modeling}
Consider $N$ reservoirs 
\begin{equation}
\begin{aligned} 
& Z^i_t = Z^i_0 + 
\int_0^t \varphi(Z^i_s, X^i_s) ds  \\ 
& Y^i_t = \beta^i_t Z^i_t , \quad i = 1, ..., N . 
\end{aligned} 
\label{Ri} 
\end{equation}



We employ a game-theoretic approach to model the interaction between reservoirs. Let the reservoirs be players in the game-theoretic framework. 
The players choose \textit{non-negative} weights $(w^1_\cdot, w^2_\cdot, ..., w^N_\cdot)$ to minimize the distance 
\begin{align} 
 J_i(w^i, w^{-i}) = \int_0^T \Big\| y^i_t - \sum_{i=1}^N w^i_t \beta^i_t Z^i_t \Big\|^2 dt , \quad i = 1, ..., N. \label{Ji}  
\end{align} 
We aim to find a Nash equilibrium $(w^{1\star}_\cdot, ..., w^{N\star}_\cdot)$ 
for \eqref{Ri} and \eqref{Ji} such that 
\begin{align} 
 J_i(w^{i\star}, w^{-i \star}) \leq 
 J_i(w^{i}_\cdot, w^{-i\star}_\cdot) , \quad 
 \forall \, i = 1, 2, ..., N. 
\notag 
\end{align} 
For $(w^{1, \star}, ..., w^{N, \star})$ to be a Nash equilibrium, it should satisfy the first order condition for all $t\in[0, T]$:    
\begin{align} 
 \Big\| y^i_t - \sum_{j=1}^N w^{i,\star}_t \beta^j_t Z^j_t \Big\| \beta^i_t Z^i_t = 0 , \quad i = 1, ..., N , \notag 
\end{align} 
which is equivalent to 
\begin{align} 
 y^i_t \beta^i_t z^i_t - \sum_{i=1}^N w^{i\star} \beta^i_t Z^i_t \beta^j_t Z^j_t = 0 , \quad i = 1, ..., N. \label{NE-firstorder}
\end{align} 

Denote 
\begin{align} 
 B_t = 
 [ \beta^1_t Z^1_t, ..., \beta^N_t Z^N_t ]^\top 
 [ \beta^1_t Z^1_t, ..., 
 \beta^N_t Z^N_t] \notag 
\end{align} 
Then we have the unique Nash equilibrium 
$[w^{1\star}_\cdot, ..., w^{N\star}_\cdot ]$ 
\begin{align} 
 [ w^{1 \star}_t, ..., w^{N \star}_t ]^\top 
  = B_t^{-1} [y^1_t \beta^1_t Z^1_t, ..., y^N_t \beta^N_t Z^N_t ]^\top ,  \quad  
  0\leq t \leq T .
  \label{Nashw}
\end{align} 

\subsection{Modified - Real Game}
Consider 
\begin{equation}
\begin{aligned} 
& X^i_t = X^i_0 + \int_0^t A_i X^i_s ds 
+ \int_0^t \sigma_i d W^i_s\\ 
& Z^i_t = Z^i_0 + 
\int_0^t \varphi(Z^i_s, X^i_s) ds  \approx 
Z^i_0 + 
\int_0^t B Z^i_s + C X^i_s ds \\ 
& \hat{Y}^i_t = \beta^i Z_0^i + \int_0^t \beta^i_s Z^i_s 
 ds  , \quad i = 0, 1, ..., N . 
\end{aligned} 
\label{Ri_linear} 
\end{equation} 
{\color{blue} X: The functions $a(\cdot)$ and $\varphi$ should be linear}

Denote 
\begin{align}
\hat{Y}:=(\hat{Y}^{1\top},..., \hat{Y}^{N \top})^\top , \quad 
Z := (Z^{1\top}, ..., Z^{N\top})^\top, \quad 
X:= (X^{1\top}, ..., X^{N\top})^\top . \notag 
\end{align} 

For each $i=1,\dots,N$, set $\beta^{-i}:= (\beta^j)_{j=1,\dots,N;\,j\neq i}$.  The objectives of the players are 
\allowdisplaybreaks
\begin{align} 
 & J_i(\beta^i, \beta^{-i}) = \int_0^T \Big\| y^i_t - \sum_{i=1}^N w^i_t \hat{Y}^i_t \Big\|^2 
  + \| \beta^i_t \|^2 dt , \quad i = 1, ..., N. \label{Ji}  \\ 
%\end{align} 
%\begin{align} 
& J_0 (\beta^0, \mathbf{w}, \beta^1, ..., \beta^N) =  \int_0^T \Big\| y^0_t - \sum_{i=1}^N w^i_t \hat{Y}^i_t \Big\|^2 
  + \| \beta^0_t \|^2 dt \label{J0}
\end{align} 

We define the value functions for the followers 
\begin{align} 
V_i (t, \hat{\mathbf{y}}, \mathbf{z}, \mathbf{x} ) = \mathbb{E} \Big[ \int_t^T \Big\| y^i_s - \sum_{i=1}^N w^i_s \hat{Y}^i_s \Big\|^2 
 + \| \beta^i_s \|^2 d s \, \Big| \, 
 \hat{Y}_t = \hat{\mathbf{y}} , Z_t = \mathbf{z}, X_t = \mathbf{x} \Big] , \quad i = 1, ..., N.  \notag 
\end{align} 
By the dynamic programming approach, the value functions satisfy the equations  
\begin{align} 
& \frac{\partial}{\partial t} V_i(t, \hat{\mathbf{y}}, \mathbf{z}, \mathbf{x} ) 
 + \sup_{\beta_i} \Big\{ \sum_{j=1}^N \beta_j^\top z_j^\top 
 \frac{\partial V_i}{\partial y_j}   
  + \sum_{j=1}^N \varphi(z_j, x_j) \frac{\partial V_i}{\partial  z_j} 
   + \sum_{j=1}^N a(x_j) \frac{\partial V_i}{\partial x_j} 
+ \Big\| y^i_s - \sum_{i=1}^N w^i \hat{y}_i \Big\|^2 + \| \beta_i \|^2 \Big\} = 0 \notag \\ 
& i = 1, ..., N. \notag 
\end{align} 
By the first order condition, we have 
\begin{align} 
 z_i \frac{\partial V_i}{\partial y_i} + 2 \beta_i = 0 \notag 
\end{align} 

\begin{align} 
  \beta_i = -\frac{1}{2} z_i^\top \frac{\partial V_i(t, \hat{\mathbf{y}, \mathbf{x}, \mathbf{z}} )}{\partial y_i}
\end{align} 



\textbf{The Discrete-time model} 

\begin{align} 
& X^i_{t+1} =  A_i X^i_t + \sigma W^i_t \notag \\  
& Z^i_{t+1} =  \varphi(Z^i_t, X^i_{t+1}) = 
 B_i Z^i_t + C X^i_{t+1} \notag \\ 
& \hat{Y}^i_{t+1} = \hat{Y}^i_t + \hat{\beta}^{i\top}_t Z^i_t , \qquad i = 1, ..., N. \notag 
\end{align} 


\allowdisplaybreaks
\begin{align} 
 & J_i(\beta^i, \beta^{-i}) = \mathbb{E} \Big\{  \sum_{t=0}^{T-1} \Big[ \Big\| y^i_t - \sum_{j=1}^N w^j_t \hat{Y}^j_t \Big\|^2 
  + \| \beta^i_t \|^2  \Big]  + \Big\| y^i_T - \sum_{j=1}^N w^j_T \hat{Y}^j_T \Big\|^2\Big\}   , \quad i = 1, ..., N. 
  %\label{DTJi}  
 \end{align} 

Let $\{e^N_i\}_{i=1}^N$ be the standard basis of $\mathbb{R}^N$, and  
denote 
\begin{align}
& \hat{Y}:=(\hat{Y}^{1\top},..., \hat{Y}^{N \top})^\top , \quad 
Z := (Z^{1\top}, ..., Z^{N\top})^\top, \quad 
X:= (X^{1\top}, ..., X^{N\top})^\top , \notag \\ 
& \mathbf{e}^N_i = e^N_i \otimes I_{dz} = [0, ..., I_{dz} , ..., 0]^T . 
\end{align} 
Then 
\begin{align} 
 \hat{Y}_{t+1} = \hat{Y}_t + \sum_{i=1}^N e_i Z^\top_t 
 \mathbf{e}_i \beta^i_t   
 \notag 
\end{align} 


%\begin{align} 
%& J_0 (\beta^0, \mathbf{w}, \beta^1, ..., \beta^N) =  \sum_{t=0}^T \Big\| y^0_t - \sum_{i=1}^N w^i_t \hat{Y}^i_t \Big\|^2 
%  + \| \beta^0_t \|^2 dt \label{DTJ0}
%\end{align} 

At time $t=T-1$, we have 
\begin{align} 
V_i(T-1, \hat{\mathbf{y}}, \mathbf{z}, \mathbf{x})  = \sup_{\beta^i} \mathbb{E} \Big\{  \Big\| y^i_t - \sum_{j=1}^N w^j \hat{y}^j \Big\|^2 
  + \| \beta^i \|^2  + \Big\| y^i_T - \sum_{j=1}^N w^j ( \hat{y}^j + \beta^{j\top} z^j ) \Big\|^2 \Big\} \notag 
\end{align} 
The equilibrium strategy at $t=T-1$ satisfies 
\begin{align} 
  \beta^i +  z^i \Big[ y^i_T - \sum_{j=1}^N w^j ( \hat{y}^j + \beta^{j\top} z^j ) \Big]    = 0 , \quad i = 1, ..., N ,  
  \label{FOC:betaT-1}
\end{align} 

\begin{align} 
 w^i \beta^{i\top} z^i + w^i z^{i\top} z^i y^i_T - w^i z^{iT} z^i \sum_{j=1}^N w^j(\hat{y}^j + \beta^{j\top} z^j ) = 0 , 
  i = 1, ..., N \notag  
\end{align}  

\begin{align} 
 \sum_{i=1}^N w^i \beta^{i\top} z^i + \sum_{i=1}^N w^i z^{i\top} z^i y^i_T 
  - \sum_{i=1}^N w^i z^{iT} z^i \sum_{j=1}^N w^j(\hat{y}^j + \beta^{j\top} z^j ) = 0 \notag 
\end{align}  

\begin{align} 
 \Big[ 1 - \sum_{j=1}^N w^j z^{j\top} z^j \Big] \sum_{i=1}^N w^i \beta^{i\top} z^i 
 + \sum_{i=1}^N w^i z^{i\top} z^i \Big[ y^i_T  -  \sum_{j=1}^N w^j \hat{y}^j \Big] = 0 \label{MFcontrol}    
\end{align} 

\begin{align} 
  \sum_{i=1}^N w^i \beta^{i\top} z^i =
 - \Big[ 1 - \sum_{j=1}^N w^j z^{j\top} z^j \Big]^{-1} \sum_{i=1}^N w^i z^{i\top} z^i \Big[ y^i_T  -  \sum_{j=1}^N w^j \hat{y}^j \Big]  \notag 
\end{align} 

From \eqref{FOC:betaT-1} and \eqref{MFcontrol}, we have the equilibrium strategy at $t=T-1$ for $i=1, ..., N$: 
\begin{align} 
 \beta^i = & - z^i \Big[ y^i_T - \sum_{j=1}^N w^j \hat{y}^j \Big] + z^i \sum_{j=1}^N w^j \beta^{j\top} z^j  
 \notag \\ 
 = & - z^i \Big[ y^i_T - \sum_{j=1}^N w^j \hat{y}^j \Big] 
   - z^i \Big[ 1 - \sum_{j=1}^N w^j z^{j\top} z^j \Big]^{-1} \sum_{i=1}^N w^i z^{i\top} z^i \Big[ y^i_T  -  \sum_{j=1}^N w^j \hat{y}^j \Big] \notag  
\end{align} 



We have that $V_i(t, \hat{\mathbf{y}}, \mathbf{z}, \mathbf{x})$ takes the form  
\begin{align} 
  V_i(t, \hat{\mathbf{y}}, \mathbf{z} , \mathbf{x} ) = [ \hat{\mathbf{y}}^\top, \mathbf{z}^\top , \mathbf{x}^\top ] P_i(t) [\hat{\mathbf{y}}^\top, \mathbf{z}^\top , \mathbf{x}^\top ]^\top 
  + 2 S_i(t)^\top [\hat{\mathbf{y}}^\top, \, \mathbf{z}^\top ]^\top + r_i(t) \notag  
 \end{align} 
By the dynamic programming principle, $V_i$ satisfy the dynamic programming equation:  
\begin{align} 
V_i(t, \hat{\mathbf{y}}, \mathbf{z}, \mathbf{x})  = & \sup_{\beta^i} \mathbb{E} \Big\{  \Big\| y^i_t - \sum_{i=1}^N w^i \hat{y}^i \Big\|^2 
  + \| \beta^i \|^2  \notag \\ 
& \hspace{2.5cm}  + V_i(t+1, \hat{\mathbf{y}} + \sum_{j=1}^N  \mathbf{z}^\top \mathbf{e}_j \beta^j, Z_{t+1} , X_{t+1} ) 
   \Big| \hat{Y}_t = \mathbf{\hat{y}}, Z_t = \mathbf{z}, 
   X_t = \mathbf{x}  \Big\} \notag \\ 
  =& \sup_{\beta^i} \mathbb{E} 
  \Big\{  \Big\| y^i_t - \sum_{i=1}^N w^i \hat{y}^i \Big\|^2 
  + \| \beta^i \|^2 \notag \\ 
 &  + [ \hat{\mathbf{y}}^\top + \sum_{j=1}^N (\mathbf{z}^\top \mathbf{e}_i \beta^j)^\top , Z_{t+1}^\top , X_{t+1}^\top ] P_i(t+1) 
  [ \hat{\mathbf{y}}^\top + \sum_{j=1}^N (e_j z^{j\top}\beta^j)^\top ,  Z_{t+1}^\top , X_{t+1}^\top ]^\top \notag \\ 
 &   \hspace{3cm}  + 2 S_i(t+1)^\top [ \hat{\mathbf{y}}^\top + \sum_{j=1}^N ( e_j z^{j\top}\beta^j )^\top , Z_{t+1}^\top , X_{t+1}^\top ]^\top 
  + r_i(t+1)   \Big| \hat{Y}_t = \mathbf{\hat{y}}, Z_t = \mathbf{z}, 
   X_t = \mathbf{x}   \Big\} 
  \label{DPeqn}
\end{align} 

By the first order condition, 
\begin{align} 
 -\beta^i =    [ z^i e_i^\top , \, 0, \, 0  ] P_i(t+1) [\hat{\mathbf{y}}^\top + \sum_{j=1}^N ( e_j z^{j\top}\beta^j )^\top , Z_{t+1}^\top, X_{t+1}^\top]^\top  
 +  [z^i e_i^\top, \, 0, \, 0] S_i(t+1) 
 \label{betaifirstorder}
\end{align} 

\begin{align} 
 - \sum_{i=1}^N e_i z^{i\top} \beta^i = &   \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] P_i(t+1) 
 \big[ \sum_{j=1}^N ( e_j z^{j\top} \beta^j )^\top , 0 , 0 \big]^\top \notag \\ 
  & + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] P_i(t+1) \big[ \hat{\mathbf{y}}^\top, Z_{t+1}^\top , X_{t+1}^\top \big]^\top \notag \\ 
  &  + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] S_i(t+1) \notag 
\end{align} 

\begin{align} 
 - \sum_{i=1}^N e_i z^{i\top} \beta^i = &  + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] P_i(t+1) 
 \big[ I_{N \times N} , 0 , 0 \big]^\top \sum_{j=1}^N  e_j z^{j\top} \beta^j  \notag \\ 
  & + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] P_i(t+1) \big[ \hat{\mathbf{y}}^\top, Z_{t+1}^\top , X_{t+1}^\top \big]^\top \notag \\ 
  &  + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] S_i(t+1) \notag 
\end{align} 


\allowdisplaybreaks 
\begin{align}  
 - \sum_{i=1}^N e_i z^{i\top} \beta^i = & - \Big\{ I_{N\times N} + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] P_i(t+1) 
 \big[ I_{N \times N} , 0 , 0 \big]^\top \Big\}^{-1} \cdot  \notag \\ 
  &  \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] 
   \Big( P_i(t+1) \big[ \hat{\mathbf{y}}^\top, Z_{t+1}^\top , X_{t+1}^\top \big]^\top + S_i(t+1) \Big) 
   \label{sumezbeta}
\end{align} 

From \eqref{betaifirstorder} we have   
\begin{align} 
 -\beta^i = &    [ z^i e_i^\top , \, 0, \, 0  ] P_i(t+1) [ I_{N\times N} , 0, 0 ]^\top \sum_{j=1}^N  e_j z^{j\top}\beta^j  \notag \\ 
 & + [ z^i e_i^\top , \, 0, \, 0  ] P_i(t+1) [\hat{\mathbf{y}}^\top  , Z_{t+1}^\top, X_{t+1}^\top]^\top     \notag \\ 
 & +  [z^i e_i^\top, \, 0, \, 0] S_i(t+1) 
 \label{betai=sumezbeta} 
\end{align} 

We substitute \eqref{sumezbeta} into \eqref{betai=sumezbeta} to obtain the equilibrium for $i=1$, ..., $N$:  
\begin{align} 
 -\beta^i = &   - [ z^i e_i^\top , \, 0, \, 0  ] P_i(t+1) [ I_{N\times N} , 0, 0 ]^\top 
 \Big\{ I_{N\times N} + \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] P_i(t+1) 
 \big[ I_{N \times N} , 0 , 0 \big]^\top \Big\}^{-1} \cdot  \notag \\ 
  &  \sum_{i=1}^N \big[ e_i z^{i\top} z^i e_i^\top, 0 , 0 \big] 
   \Big( P_i(t+1) \big[ \hat{\mathbf{y}}^\top, Z_{t+1}^\top , X_{t+1}^\top \big]^\top + S_i(t+1) \Big) \notag \\  
 & + [ z^i e_i^\top , \, 0, \, 0  ] P_i(t+1) [\hat{\mathbf{y}}^\top  , Z_{t+1}^\top, X_{t+1}^\top]^\top     
  +  [z^i e_i^\top, \, 0, \, 0] S_i(t+1) 
