\section{Current Version} 

% Z is input signal
% X is input noise/randomness (no randomness is an option!)

We consider a model with $N$ agents $\{\mathcal{A}_i\}_{i=1}^N$. 
Let each agent $\mathcal{A}_i$ has input signal sequence $\{Z^i_t\}_{t\geq 0}$ and a readout map.  
\begin{equation}
\begin{aligned} 
& X^i_{t+1} =  A_i X^i_t + \sigma W^i_t , \quad X^i_\cdot \in \mathbb{R}^{dx \times 1} , \\  
& Z^i_{t+1} =  \varphi(Z^i_t, X^i_{t+1}) ,  \quad Z^i_\cdot \in \mathbb{R}^{dz \times 1} ,  \\ 
& \hat{Y}^i_{t+1} = \hat{Y}^i_t + \beta^{i\top}_t Z^i_t , \quad \hat{Y}^i_\cdot \in \mathbb{R}^{dy \times 1} , \ i = 1, ..., N ,   
\end{aligned} 
\label{DTRCsystem}
\end{equation} 
where $W^i_t$, $i=1$, ..., $N$, $t=0$, ..., $T$ are identically independently distributed standard normal random variables. 
Consider a major agent who also acts as a central planner and chooses weight vector sequence on the $N$-simplex   
\begin{align} 
w_t= (w^1_t, ..., w^N_t)^\top \in \Delta_N , \quad t = 0, 1, ..., T \notag  
\end{align} 
for the minor players' output $\hat{Y}^i$ in order to minimize the total loss  
\begin{align} 
 J_0(w) = \mathbb{E}  \sum_{t=1}^T \Big[ \sum_{i=1}^N 
 \Big\| y^i_t  - \sum_{j=1}^N w^j_t \hat{Y}^j_t \Big\|^2 
  + \sum_{j=1}^N \kappa_j \big\| w^j_t \big\|^2 \Big] ,  
  \notag 
  \label{DTJ0}
\end{align} 
where $y^i_\cdot$, $i=1$, ..., $N$ are the observed target values, and all $\kappa_j>0$.  

Given the weight $w_t = (w^1_t, ..., w^N_t)$, $t=0$, $1$, ..., $T$, each minor agent $\mathcal{A}_i$ 
chooses $\{\beta^i_t\}_{t=0}^T$ non-cooperatively to minimize the individual cost 
\allowdisplaybreaks
\begin{align} 
 & J_i(\beta^i, \beta^{-i}) = \mathbb{E} \Big\{  \sum_{t=0}^{T-1} \Big[ \Big\| y^i_t - \sum_{j=1}^N w^j_t \hat{Y}^j_t \Big\|^2 
  + \| \beta^i_t \|^2  \Big]  + \Big\| y^i_T - \sum_{j=1}^N w^j_T \hat{Y}^j_T \Big\|^2 \Big\}   , \quad i = 1, ..., N ,  \label{DTJi}  
  \end{align} 
 where $\beta^{-i}=(\beta^1, ..., \beta^{i-1}, \beta{i+1}, ..., \beta^N)$. 




\subsection{The Nash Equilibrium between the Minor Players}
Denote 
\begin{align} 
\mathbf{w}_t=(w^1_t I_{dy}, ..., w^N_t I_{dy})^\top, \quad \hat{Y}_t=(\hat{Y}^{1\top}_t, ..., \hat{Y}^{N\top}_t)^\top, \quad   
\mathbf{e}^N_i = e^N_i \otimes I_{dz} = [0, ..., I_{dz} , ..., 0]^\top,  \notag 
\end{align} 
then the costs \eqref{DTJi} for the $N$ agents can be written as  
\begin{align} 
 & J_i(\beta^i, \beta^{-i}) = \mathbb{E} \Big\{  \sum_{t=0}^{T-1} \Big[ \Big\| y^i_t - \mathbf{w}^\top_t \hat{Y}_t \Big\|^2 
  + \| \beta^i_t \|^2  \Big]  + \Big\| y^i_T - \mathbf{w}_T^\top \hat{Y}_T \Big\|^2 \Big\}   , \quad i = 1, ..., N. 
  \label{DTJicompact}
 \end{align} 

 We aim to find a set of Nash equilibrium strategies $(\beta^1, ..., \beta^N)$ for the $N$ agent such that 
 \begin{align} 
 J_i(\beta^i, \beta^{-i}) 
 \leq J_i(u, \beta^{-i}), 
 \quad \forall u \in \mathbb{R}^{dz \times dy} , 
 \quad  \forall i = 1, ..., N. \label{NEbeta}
 \end{align} 



We introduce the following system of matrix-valued equations for $(P_i, S_i)_{i=1}^N$ on the time span 
$t=0$, $1$ ..., $T$. 
\begin{equation} 
\begin{cases}  
  P_i(t) = 
 [ \mathbf{D}(t)(I+\mathbf{A}(t))^{-1} \mathbf{B}(t) - I ]^\top P_i(t+1) [  \mathbf{D}(t)(I+\mathbf{A}(t))^{-1} \mathbf{B}(t) - I ]  \\ 
  \hspace{2cm} + [ \mathbf{e}_i^\top \mathbf{D}(t)(I+\mathbf{A}(t))^{-1} \mathbf{B}(t) ]^\top 
 [ \mathbf{e}_i^\top \mathbf{D}(t)(I+\mathbf{A}(t))^{-1} \mathbf{B}(t) ] 
 + \mathbf{w}_t \mathbf{w}_t^\top  \\ 
  I + \mathbf{A}(t) \, \text{is invertible}  \\ 
  P_i(T) =  \mathbf{w}_T \mathbf{w}_T^\top  , \quad i = 1, 2, ..., N , 
 \end{cases}
 \label{eqn:Pi}
 \end{equation} 

\allowdisplaybreaks 
\begin{equation}  
 \begin{cases} 
  S_i(t) =   \mathbf{B}(t)^\top (I + \mathbf{A})^{-1} 
 [\mathbf{e}_i \mathbf{e}_i^\top + \mathbf{D}(t)^\top P_i(t+1) \mathbf{D}(t) ] (I+\mathbf{A})^{-1} \mathbf{C}   \\ 
  \hspace{1cm} - P_i(t+1) \mathbf{D}(I+\mathbf{A})^{-1} \mathbf{C} 
 - \mathbf{B}^\top (I + \mathbf{A})^{-1}\mathbf{D} S_i(t+1) 
 - \mathbf{w}_t y^i_t 
 + S_i(t+1) , 
  \\ 
 S_i(T) = - \mathbf{w}_T y^i_T   . 
\end{cases}   
\label{eqn:Si}
\end{equation} 
%The matrices $\mathbf{A}(\cdot) = (A_{ij}(\cdot))_{1\leq i , j \leq N}$,  
%$\mathbf{B}(\cdot) = \big[ B_1(\cdot)^\top, ..., B_N(\cdot)^\top \big]^\top$, 
%and $\mathbf{C}(\cdot) = \big[ C_1(\cdot)^\top, ..., C_N(\cdot)^\top \big]$ are defined by  
%\begin{align} 
%& A_{ij}(t) = \mathbb{E} \Big\{ (e_i Z^{i\top}_t )^\top P_i( t+1 ) e_j Z^{j\top}_t \Big\} ,   \label{Aij} \\ 
%& B_i(t) = \mathbb{E}(Z^i_t) e_i^\top  P_i(t+1)  , \notag \\ 
%& C_i(t) = \mathbb{E}(Z^i_t) e_i^\top  S_i(t+1) , 
%\quad 1 \leq i , j \leq N . \notag 
%\end{align} 
In \eqref{eqn:Pi} and \eqref{eqn:Si}, the matrices $\mathbf{A}(\cdot)$,  
$\mathbf{B}(\cdot)$, $\mathbf{C}(\cdot)$, and $\mathbf{D}(\cdot)$ are defined by  
\allowdisplaybreaks 
\begin{align} 
&\mathbf{A}(t) = \begin{bmatrix} 
 \mathbb{E} [ (e_1 Z^{1\top}_t)^\top P_1(t+1) e_1 Z^{1\top}_t ] & 
 \mathbb{E} [ (e_1 Z^{1\top}_t)^\top P_1(t+1) e_2 Z^{2\top}_t ]
 & \cdots & 
 \mathbb{E} [ (e_1 Z^{1\top}_t)^\top P_1(t+1) e_N Z^{N\top}_t ] \\ 
 \mathbb{E} [ (e_2 Z^{2\top}_t)^\top P_2(t+1) e_1 Z^{1\top}_t ] & 
 \mathbb{E} [(e_2 Z^{1\top}_t)^\top P_2(t+1) e_2 Z^{2\top}_t ]
 & \cdots & 
 \mathbb{E} [ (e_2 Z^{2\top}_t)^\top P_2(t+1) e_N Z^{N\top}_t ] \\ 
 \vdots & \vdots & \ddots & \vdots \\ 
 \mathbb{E}[ (e_N Z^{N\top}_t)^\top P_N(t+1) e_1 Z^{1\top}_t ]& 
 \mathbb{E} [ (e_N Z^{N\top}_t)^\top P_N(t+1) e_2 Z^{2\top}_t ]
 & \cdots & 
 \mathbb{E} [ (e_N Z^{N\top}_t)^\top P_N(t+1) e_N Z^{N\top}_t ]
\end{bmatrix} \notag \\ 
& \mathbf{B}(t) = 
 \begin{bmatrix} 
 \mathbb{E} (e_1 Z^{1\top}_t )^\top P_1(t+1) \\ 
 \mathbb{E}(e_2 Z^{2\top}_t )^\top P_2(t+1) \\ 
 \vdots \\  
 \mathbb{E} (e_N Z^{N\top}_t) P_N(t+1) 
 \end{bmatrix} ,  
 \qquad 
 \mathbf{C}(t) = 
 \begin{bmatrix} 
 \mathbb{E}(e_1 Z^{1\top}_t )^\top S_1(t+1) \\ 
 \mathbb{E}(e_2 Z^{2\top}_t )^\top S_2(t+1) \\ 
 \vdots \\ 
 \mathbb{E}(e_N Z^{N\top}_t) S_N(t+1) 
 \end{bmatrix} , 
 \notag \\ 
& \mathbf{D}(t) 
 = 
 \begin{bmatrix} 
 \mathbb{E}( e_1 Z^{1\top}_t ) , \, 
\mathbb{E} ( e_2 Z^{2\top}_t ) ,  \,
 \cdots , \, 
\mathbb{E} ( e_N Z^{N\top}_t )
 \end{bmatrix} . 
 \notag 
\end{align} 

