The following proposition links the existence of a Nash equilibrium of \eqref{DTRCsystem} and \eqref{DTJi} to the solvability of the system \eqref{eqn:Pi}. 
\begin{proposition} 
\label{prop:NashEqmExistence}
Suppose the system \eqref{eqn:Pi} for $(P_i)_{i=1}^N$ admits a solution for $t=0$, $1$, ..., $T$.  
Then the $N$-player Nash game \eqref{DTJi} admits a unique feedback Nash equilibrium 
\begin{align} 
\boldsymbol{\beta}_t = [\beta^{1\top}_t, ..., \beta^{N \top}_t ]^\top = - ( I + \mathbf{A}(t) )^{-1} 
\big( \mathbf{B}(t) \hat{Y}_t + \mathbf{C}(t) \big) , \quad t = 0, 1, ..., T. 
\label{eqmvecbeta} 
\end{align} 
\end{proposition}





\subsection{The Major Player's Selection of Optimal Weights} 

Consider the objective of the major player/central planner is to optimize 
\begin{align} 
    \min_{w_{\cdot}}\,
 J_0(w) = \mathbb{E}  \sum_{t=1}^T \Big[ \sum_{i=1}^N 
 \Big\| y^i_t  - \sum_{j=1}^N w^j_t \hat{y}^j_t \Big\|^2 
  + \sum_{j=1}^N \kappa_j \big\| w^j_t \big\|^2 \Big] .  
  \label{DTJ0}
\end{align} 
where the minimization is taken over all decision rules $w_{\cdot}:=\{w_t\}_{t=1}^T = \{(w^1_t, ..., w^N_t)\}_{t=1}^T$ whose paths lie in the $N$-simplex $\Delta_N:= \{w\in [0,1]^N:\, \sum_{n=1}^N\, w_n=1\}$.  
Our first main result shows that there exists a unique solution to the optimization problem~\eqref{DTJ0}.
\begin{theorem}[Optimal Coordination]
\label{thm:OptimalWeights}
The quadratic programming problem \eqref{MajorPlayer:QP} admits a unique solution $w^\star = (w^{1, \star}, ..., w^{N, \star})$ given by 
\begin{align} 
  w^\star   = &  \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1}  \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t 
  \notag \\    
  & -  \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1}   G^\top 
  \Big[ G \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1} G^\top \Big]^{-1} 
 \Big[ G \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1} \hat{Y}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) -  \mathbf{c} \Big] .
  \label{eqn:OptimalWeights}  
\end{align} 
\end{theorem} 

