From \eqref{DTJicompact}, the value functions at time $T$ with $\hat{Y}_T=\hat{\mathbf{y}}$ satisfy 
\begin{align} 
 V_i(T, \hat{\mathbf{y}}) 
 =  \Big\| y^i_T - \sum_{j=1}^N w^j_T \hat{y}^j \Big\|^2 
 = \hat{\mathbf{y}}^\top \mathbf{w} \mathbf{w}^\top \hat{\mathbf{y}} 
 - 2 y^i_T \mathbf{w}^\top \hat{\mathbf{y}} + |y^i_T|^2 .  
 \label{Vi(T)}
\end{align} 
By the dynamic programming principle, the value functions at $T-1$ with $\hat{Y}_{T-1}= \hat{\mathbf{y}}=(\hat{y}^{1\top}, ..., \hat{y}^{N\top})^\top$ satisfies  
\begin{align} 
V_i(T-1, \hat{\mathbf{y}}) 
= & \sup_{\beta^i} \mathbb{E} \Big\{  \Big\| y^i_{T-1} - \sum_{i=1}^N w^i \hat{y}^i \Big\|^2 
  + \| \beta^i \|^2    + V_i(T, \hat{\mathbf{y}} + \sum_{j=1}^N  e_j Z^{j\top}_{T-1} \beta^j ) 
   \Big| \hat{Y}_{T-1} = \mathbf{\hat{y}}  \Big\} \notag \\ 
   = & \sup_{\beta^i} \mathbb{E} \Big\{  \Big\| y^i_{T-1} - \sum_{i=1}^N w^i \hat{y}^i \Big\|^2 
  + \| \beta^i \|^2     + \Big\| y^i_T - \sum_{j=1}^N w^j_T \Big( \hat{y}^j +  Z^{j\top}_{T-1}  \beta^j \Big)  \Big\|^2 
   \Big| \hat{Y}_{T-1} = \mathbf{\hat{y}}  \Big\} .  
   \label{DPeqnVi(T-1)}
\end{align} 
By the first order condition for the right side of \eqref{DPeqnVi(T-1)}, we have 
\begin{align} 
 \beta^i -  Z^i_{T-1} w^i_T \Big[ y^i_T - \sum_{j=1}^N w^j_T \Big( \hat{y}^j +  Z^{j\top}_{T-1} \beta^j \Big) \Big]   =0 , \quad 
 i=1, ..., N , \notag 
\end{align} 
which can be written in the compact form 
\begin{align} 
 [\beta^{1\top}, ..., \beta^{N \top}]^\top = - \mathbf{A}(T-1) [\beta^{1\top}, ..., \beta^{N \top}]^\top 
 - \mathbf{B} (T-1) \hat{\mathbf{y}} - \mathbf{C}(T-1) .  
\end{align} 
Since \eqref{eqn:Pi} admits a solution by the hypothesis of the proposition, we have $I + \mathbf{A}(T-1)$ is invertible, and hence 
\begin{align} 
  \boldsymbol{\beta}_{T-1} = [\beta^{1\top}_{T-1}, ..., \beta^{N \top}_{T-1} ]^\top = - ( I + \mathbf{A}(T-1) )^{-1} 
\big( \mathbf{B}(T-1) \hat{Y}_{T-1} + \mathbf{C}(T-1) \big) . 
\label{eqmbetaT-1}
