\subsection{{Proof of Theorem~\ref{thm:OptimalWeights}}}
\label{s:Proofs__ss:OptimalWeights}
We minimize \eqref{DTJ0} over all $\Delta_N$-valued decision rules $w_{\cdot}$.  
At each time $t$, the major player needs to solve the nonlinear programming problem 
\begin{equation} 
\begin{aligned}  
& \min_{w=(w^1, ..., w^N) } \sum_{i=1}^N \big\| y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big\|^2 
 + \sum_{j=1}^N \kappa_j \big\| w^j \big\|^2 \\ 
& \text{subject to} \ \mathbf{g}(w)=(w^1-1, ..., w^N-1, -w^1, ..., -w^N) \leq 0 , \quad 
 h(w) = w^1 + ... + w^N - 1 = 0 . 
\end{aligned} 
\label{MajorPlayer:NLoptim}
\end{equation} 

Denote 
\begin{align} 
% \hat{\mathbf{Y}}_t = \big[ \hat{y}^1_t, \cdots , \hat{y}^N_t \big] , \quad 
  \mathbf{1}_{1\times N} = \big[ 1, ..., 1 \big] \in \mathbb{R}^{1\times N} , \quad 
 % \hat{\boldsymbol{\lambda}} = \big[ \hat{\lambda}_1, ..., \hat{\lambda}_N \big]^\top , \quad 
  \mathrm{K} = \diag[\kappa_1, ..., \kappa_N] \in \mathbb{R}^{N\times N} . \notag 
\end{align} 



Since the objective function of the nonlinear programming problem \eqref{MajorPlayer:NLoptim} can be written as 
\begin{align} 
 \sum_{i=1}^N \Big\| y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \Big\|^2 
  + \sum_{j=1}^N \kappa_j \big\| w^j \big\|^2 
 = & \sum_{i=1}^N \Big( y^{i\top}_t - \sum_{j=1}^N w^j \hat{y}^{j\top}_t \Big) 
 \Big( y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \Big) + \sum_{j=1}^N \kappa_j w^{j 2}   \notag \\ 
 = & N \sum_{i,j=1}^N w^i \hat{y}^{i\top}_t \hat{y}^j_t w^j 
  - 2  \sum_{i=1}^N y^{i\top}_t   \sum_{j=1}^N w^j \hat{y}^j_t 
   + \sum_{i=1}^N y^{i\top}_t y^i_t + \sum_{j=1}^N \kappa_j w^{j 2} \notag \\ 
 = &  w^\top \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) w 
  - 2 \Big( \sum_{i=1}^N y^{i\top}_t \Big) \hat{\mathbf{Y}}_t w 
   + \sum_{i=1}^N y^{i\top}_t y^i_t . \notag 
\end{align} 
Therefore the nonlinear programming problem \eqref{MajorPlayer:NLoptim} is equivalent to the following quadratic programming problem 
\begin{equation} 
\begin{aligned}  
& \min_{w=(w^1, ..., w^N)^\top } \frac{1}{2}  w^\top \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t     + \mathrm{K} \big) w 
  -  \Big( \sum_{i=1}^N y^{i\top}_t \Big) \hat{\mathbf{Y}}_t w , \\ 
& \text{subject to} \ G w \leq \mathbf{c} ,
\end{aligned} 
\label{MajorPlayer:QP}
\end{equation} 
where we denote 
\begin{align} 
 G = \begin{bmatrix} I_N \\ -I_N \\ \mathbf{1}_{1\times N} \\ - \mathbf{1}_{1\times N}  \end{bmatrix} , \quad 
  \mathbf{c} =  \begin{bmatrix} 1_{N\times 1} \\ 0_{N\times 1} \\ 1 \\ -1   \end{bmatrix} . \notag 
\end{align} 




To prove Theorem~\ref{thm:OptimalWeights}, we need to use the results of the following Theorems~\ref{thm:NSQP} and \ref{thm:QPdual} from \cite{Berkovitz2001}. 
According to \cite[Theorem V.6.1]{Berkovitz2001}, the following theorem gives a necessary and sufficient condition for solutions of \eqref{MajorPlayer:QP}. 
\begin{theorem} 
\label{thm:NSQP}
A necessary and sufficient condition for a point $w^\star=(w^{1, \star}, ..., w^{N, \star})^\top$ to be a solution of the quadratic programming problem \eqref{MajorPlayer:QP} is that 
\begin{align} 
G w^\star \leq \mathbf{c} \label{NSQP:Gw<=c} 
\end{align} 
and there exists a vector $\boldsymbol{\lambda} \geq 0$ in $\mathbb{R}^{2N+2}$ such that 
\begin{align} 
 & \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big)  w^\star - \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t 
  + G^\top \boldsymbol{\lambda} = 0 , \label{NSQP:w+lambda} \\ 
 & \boldsymbol{\lambda}^\top (G w^\star - \mathbf{c}) = 0 . \label{NSQP:wlambda}  
\end{align} 
\end{theorem}

Introduce the dual quadratic programming problem: 
\begin{equation} 
\begin{aligned}  
& \max \big\{ \theta (\boldsymbol{\lambda}) : \ \boldsymbol{\lambda} \geq 0 , \ \theta(\boldsymbol{\lambda}) > -\infty \big\} , 
 \\ 
& \theta(\boldsymbol{\lambda}) = \inf \{ L( \mathbf{x}, \boldsymbol{\lambda}) : \ \mathbf{x} \in \mathbb{R}^N \} ,  \\ 
& L( \mathbf{x}, \boldsymbol{\lambda}) 
 = \frac{1}{2}  \mathbf{x}^\top \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) \mathbf{x}  
  -  \Big( \sum_{i=1}^N y^{i\top}_t \Big) \hat{\mathbf{Y}}_t \mathbf{x} 
   + \boldsymbol{\lambda}^\top (G \mathbf{x} - \mathbf{c} ) .   
\end{aligned} 
\label{MajorPlayer:DQP} 
\end{equation} 

By \cite[Theorem V.6.2]{Berkovitz2001}, we have the following relation between the quadratic programming problem \eqref{MajorPlayer:QP} and the dual problem \eqref{MajorPlayer:DQP}. 
\begin{theorem} 
\label{thm:QPdual}
Let the quadratic programming problem \eqref{MajorPlayer:QP} has a solution $w^\star=(w^{1, \star}, ..., w^{N, \star})$. Then the dual problem \eqref{MajorPlayer:DQP} has a solution $\boldsymbol{\lambda}_\star$, and the solution $\boldsymbol{\lambda}_\star$ is exactly the multiplier $\boldsymbol{\lambda}$ in Theorem~\ref{thm:NSQP} corresponding to $w^\star$. 
\end{theorem} 

With Theorems~\ref{thm:NSQP} and \ref{thm:QPdual}, we are ready to prove Theorem~\ref{thm:OptimalWeights}. 
\begin{proof}[Proof of Theorem~\ref{thm:OptimalWeights}]  

By Theorem~\ref{thm:NSQP}, we can determine the optimal weights $w^\star=(w^{1,\star}, ..., w^{N,\star})$ from 
\eqref{NSQP:w+lambda}. The multiplier $\boldsymbol{\lambda}$ in \eqref{NSQP:w+lambda} is the solution of the dual problem \ref{MajorPlayer:DQP}. 

We first solve the dual problem \eqref{MajorPlayer:DQP} for the optimal $\boldsymbol{\lambda}$. 
The function $L(\mathbf{x}, \boldsymbol{\lambda})$ in \eqref{MajorPlayer:DQP} can be rewritten as  
\begin{align} 
 L( \mathbf{x}, \boldsymbol{\lambda}) 
 = & \frac{1}{2}  \mathbf{x}^\top \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big)  \mathbf{x}  
  -  \Big( \sum_{i=1}^N y^{i\top}_t \Big) \hat{\mathbf{Y}}_t \mathbf{x} 
   + \boldsymbol{\lambda}^\top (G \mathbf{x} - \mathbf{c} ) \notag \\ 
   = &  \frac{1}{2}  \mathbf{x}^\top \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) \mathbf{x}  
  - \Big[ \Big( \sum_{i=1}^N y^{i\top}_t \Big) \hat{\mathbf{Y}}_t - \boldsymbol{\lambda}^\top G \Big] \mathbf{x} 
   - \boldsymbol{\lambda}^\top \mathbf{c} . 
   \label{L(x,lambda)2}   
\end{align} 
For each $\boldsymbol{\lambda}$ fixed, the function $L(\cdot, \boldsymbol{\lambda})$ given by \eqref{L(x,lambda)2} is a convex function on $\mathbb{R}^N$. Then $\mathbf{x}_{\boldsymbol{\lambda}}$ is a minimizer of $L(\cdot, \boldsymbol{\lambda})$ if and only if $\nabla_{\mathbf{x}} L(\mathbf{x}_{\boldsymbol{\lambda}} , \boldsymbol{\lambda}) = 0$. 
It then follows from \eqref{L(x,lambda)2} that 
\begin{align} 
 0 = & \nabla_{\mathbf{x}} L(\mathbf{x}_{\boldsymbol{\lambda}} , \boldsymbol{\lambda})  \notag \\ 
 = & \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) \mathbf{x}_{\boldsymbol{\lambda}} 
  - \Big[  \hat{\mathbf{Y}}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) - G^\top \boldsymbol{\lambda}  \Big] , 
 \notag 
\end{align} 
which further gives that 
\begin{align} 
0 = &   \mathbf{x}_{\boldsymbol{\lambda}}^\top \big(   N\hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t 
 + \mathrm{K} \big) \mathbf{x}_{\boldsymbol{\lambda}} 
  - \mathbf{x}_{\boldsymbol{\lambda}}^\top \Big[  \hat{\mathbf{Y}}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) - G^\top \boldsymbol{\lambda}  \Big] .  
  \label{0=<x,gradL>}  
\end{align} 
Substituting \eqref{0=<x,gradL>} into \eqref{MajorPlayer:DQP}, we obtain an explicit form of $\theta(\boldsymbol{\lambda})$
\begin{align} 
 \theta(\boldsymbol{\lambda}) = & L(\mathbf{x}_{\boldsymbol{\lambda}}, \boldsymbol{\lambda}) \notag \\ 
 =& \frac{1}{2}  \mathbf{x}_{\boldsymbol{\lambda}}^\top 
  \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big)  
  \mathbf{x}_{\boldsymbol{\lambda}}   
  - \Big[ \Big( \sum_{i=1}^N y^{i\top}_t \Big) \hat{\mathbf{Y}}_t - \boldsymbol{\lambda}^\top G \Big] 
   \mathbf{x}_{\boldsymbol{\lambda}}  
   - \boldsymbol{\lambda}^\top \mathbf{c} \notag \\ 
   =& \frac{1}{2}  \mathbf{x}_{\boldsymbol{\lambda}}^\top\big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t  + \mathrm{K} \big) 
    \mathbf{x}_{\boldsymbol{\lambda}}   
  -  \mathbf{x}_{\boldsymbol{\lambda}}^\top \big( N\hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t 
   + \mathrm{K} \big)    \mathbf{x}_{\boldsymbol{\lambda}}   
   - \boldsymbol{\lambda}^\top \mathbf{c} \notag \\ 
   =&  - \frac{1}{2}  \mathbf{x}_{\boldsymbol{\lambda}}^\top 
   \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) \mathbf{x}_{\boldsymbol{\lambda}}   
   - \boldsymbol{\lambda}^\top \mathbf{c} . \notag 
\end{align}  

With the above explicit form of $\theta(\boldsymbol{\lambda})$, the dual quadratic programming problem \eqref{MajorPlayer:DQP} is then equivalent to 
\begin{equation} 
\begin{aligned} 
& \max_{\mathbf{x}, \ \boldsymbol{\lambda}} \ 
- \frac{1}{2}  \mathbf{x}^\top \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) \mathbf{x}   
   - \boldsymbol{\lambda}^\top \mathbf{c} ,   \\ 
& \text{subject to:} \ 
 \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big) \mathbf{x} 
  - \Big[  \hat{\mathbf{Y}}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) - G^\top \boldsymbol{\lambda}  \Big] = 0 .  
\end{aligned} 
\label{MajorPlayer:DQPequiv} 
\end{equation} 
Since $N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K}$ is positive definite, the equality constraint in \eqref{MajorPlayer:DQPequiv} 
implies that 
\begin{align} 
   \mathbf{x} 
=  \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big)^{-1} \Big[  \hat{\mathbf{Y}}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) - G^\top \boldsymbol{\lambda}  \Big] . 
\label{xsublambda}
\end{align} 
With \eqref{xsublambda} substituted into \eqref{MajorPlayer:DQPequiv}, 
the dual problem \eqref{MajorPlayer:DQPequiv} is then equivalent to the following unconstrained optimization problem: 
\begin{align} 
 \max_{\boldsymbol{\lambda}} \ -\frac{1}{2}  \Big[  \hat{\mathbf{Y}}^\top_t 
  \Big( \sum_{i=1}^N y^i_t \Big) - G^\top \boldsymbol{\lambda}  \Big]^\top 
   \big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \big)^{-1} 
 \Big[  \hat{\mathbf{Y}}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) - G^\top \boldsymbol{\lambda}  \Big] 
 - \boldsymbol{\lambda}^\top \mathbf{c} . 
\label{MajorPlayer:DQPunconstrained} 
\end{align} 
We solve the unconstrained optimization problem \eqref{MajorPlayer:DQPunconstrained} for a $\boldsymbol{\lambda}_\star$:  
\begin{align} 
 \boldsymbol{\lambda}_\star = \Big[ G \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1} G^\top \Big]^{-1} 
 \Big[ G \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1} \hat{Y}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) -  \mathbf{c} \Big] . 
 \label{lambdasubstar}
\end{align} 
Then we substitute $\boldsymbol{\lambda}_\star$ into \eqref{NSQP:w+lambda} to solve for the optimal weight vector $w^\star=(w^{1,\star}, ..., w^{N,\star})^\top$: 
\begin{align} 
   w^\star = &  \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K}  \Big)^{-1} \Big[ \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t 
  - G^\top \boldsymbol{\lambda}_\star \Big]  \notag  \\ 
  = &  \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1}  \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t 
  \notag \\    
  & -  \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1}   G^\top 
  \Big[ G \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1} G^\top \Big]^{-1} 
 \Big[ G \Big( N \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t + \mathrm{K} \Big)^{-1} \hat{Y}^\top_t \Big( \sum_{i=1}^N y^i_t \Big) -  \mathbf{c} \Big] , 
  \notag  
\end{align} 
which is \eqref{eqn:OptimalWeights}.  
\end{proof} 








