\end{equation} 
By the Karush-Kuhn-Tucker theorem, if $w=(w_1, ..., w_N)^\top$ is a solution of the nonlinear programming problem 
\eqref{MajorPlayer:NLoptim}, then there exist $\lambda_0\geq 0$, $\boldsymbol{\lambda}=(\lambda_1, ..., \lambda_N, \lambda_{N+1}, ..., \lambda_{2N})^\top \geq 0$, and $\mu$ such that 
\begin{equation} 
\begin{aligned}  
 & \text{(i)}. \ (\lambda_0, \boldsymbol{\lambda}, \mu ) \neq 0 .  \\ 
 & \text{(ii)}. \ \langle \boldsymbol{\lambda} ,  \mathbf{g}(w) \rangle = 0 .  \\ 
 & \text{(iii)}. \ \lambda_0  \nabla_{w} \Big[ \sum_{i=1}^N \big\| y^i_t - \sum_{i=1}^N w^i \hat{y}^i_t \big\|^2 \Big]  
  + \boldsymbol{\lambda}^\top \nabla \mathbf{g}(w) + \mu \nabla h(w) = 0 .  
\end{aligned} 
\label{KKT(i)-(iii)} 
\end{equation} 

Condition \eqref{KKT(i)-(iii)}-(ii) can be written as 
\begin{align} 
 (\lambda_1 - \lambda_{N+1} ) w^1 + (\lambda_2 - \lambda_{N+2}) w^2 + \cdots + 
 (\lambda_N - \lambda_{2N}) w^N - \lambda_1 - \cdots - \lambda_N = 0 . 
 \label{KKT(ii)MajorPlayer}
\end{align} 

Condition \eqref{KKT(i)-(iii)}-(iii) can be written as 
\begin{equation} 
\begin{aligned} 
 & - 2 \lambda_0 \hat{y}^{1\top}_t  \sum_{i=1}^N \big( y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big) + \lambda_1 - \lambda_{N+1} 
 + \mu = 0  , \\ 
 & - 2 \lambda_0 \hat{y}^{2\top}_t  \sum_{i=1}^N \big( y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big) + \lambda_2 - \lambda_{N+2} 
 + \mu = 0 , \\ 
 & \qquad \vdots  \\ 
 & - 2 \lambda_0 \hat{y}^{N\top}_t  \sum_{i=1}^N \big( y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big) + \lambda_N - \lambda_{2N} 
 + \mu = 0  . 
\end{aligned} 
\label{KKT(iii)MajorPlayer}
\end{equation} 

Let 
\begin{align} 
 \hat\lambda_1 = \lambda_1 - \lambda_{N+1}, \quad \hat\lambda_2 = \lambda_2 - \lambda_{N+2}, \cdots, \quad   
 \hat\lambda_N = \lambda_N - \lambda_{2N} . \notag 
\end{align} 
Then conditions \eqref{KKT(ii)MajorPlayer} and \eqref{KKT(iii)MajorPlayer} can be written respectively as 
\begin{align} 
 \hat\lambda_1 w^1 + \hat\lambda_2 w^2 + \cdots + \hat\lambda_N w^N 
  -\lambda_1 - \cdots - \lambda_N = 0  
 \label{KKT(ii)MajorPlayer:<hatlambda,w>=0}
\end{align} 
and 
\begin{align} 
\lambda_0 
\begin{bmatrix} 
 \hat{y}^{1\top}_t \hat{y}^1_t & \hat{y}^{1\top}_t \hat{y}^2_t & \cdots & \hat{y}^{1\top}_t \hat{y}^N_t \\ 
 \hat{y}^{2\top}_t \hat{y}^1_t & \hat{y}^{2\top}_t \hat{y}^2_t & \cdots & \hat{y}^{2\top}_t \hat{y}^N_t \\
 \vdots & \vdots & \ddots & \vdots \\ 
 \hat{y}^{N\top}_t \hat{y}^1_t & \hat{y}^{N\top}_t \hat{y}^2_t & \cdots & \hat{y}^{N\top}_t \hat{y}^N_t
\end{bmatrix} 
\begin{bmatrix} 
w^1 \\ w^2 \\ \vdots \\ w^N 
\end{bmatrix} 
= 
\frac{1}{2} 
\begin{bmatrix} 
2 \lambda_0 \hat{y}^{1\top}_t \sum_{i=1}^N y^i_t + \hat{\lambda}_1 + \mu \\ 
2 \lambda_0 \hat{y}^{2\top}_t \sum_{i=1}^N y^i_t + \hat{\lambda}_2 + \mu \\ 
\vdots \\ 
2 \lambda_0 \hat{y}^{N\top}_t \sum_{i=1}^N y^i_t + \hat{\lambda}_N + \mu 
\end{bmatrix} .
\label{KKT(iii)MajorPlayermatrix}
\end{align} 



If $\lambda_0=0$, we have from \eqref{KKT(iii)MajorPlayermatrix} that 
\begin{align} 
 \hat\lambda_1 = \hat\lambda_2 = \cdots = \hat\lambda_N = -\mu . 
 \label{hatlambda=-mu} 
\end{align} 
If $\lambda_0=0$ and $\mu\neq 0$, we have from \eqref{KKT(ii)MajorPlayer:<hatlambda,w>=0} and 
\eqref{hatlambda=-mu} that 
$-\mu = \lambda_1 + \cdots + \lambda_N >0$. 
If $\lambda_0=0$ and $\mu=0$, we have from \eqref{KKT(i)-(iii)}-(i) and \eqref{hatlambda=-mu} that 
\begin{align} 
\boldsymbol\lambda=(\lambda_1, ..., \lambda_N, \lambda_{N+1}, ..., \lambda_{2N}) \neq 0 
\quad \text{and}  \quad 
\lambda_1=\lambda_{N+1} - \mu, \ \lambda_2 = \lambda_{N+2} - \mu , \ ..., \ \lambda_{N}=\lambda_{2N} - \mu . 
\notag 
\end{align} 
It then follows from \eqref{KKT(ii)MajorPlayer:<hatlambda,w>=0} that any $(w^1, ..., w^N)\in \Delta_N$ solves the programming problem 
\eqref{MajorPlayer:NLoptim}. (Xuwei: This scenario needs to be addressed and excluded!)  


If \eqref{MajorPlayer:NLoptim} admits an interior solution $w=(w^1, ..., w^N)$ with $0<w^i<1$ for all $i=1$, ..., $N$, we have 
$\mathbf{g}(w)=(w^1 -1, ..., w^N-1, -w^1, ..., -w^N) < 0$. Also note that $\nabla h(w) = [1, 1, ..., 1]\in \mathbb{R}^N$ is an independent vector. 
If \eqref{MajorPlayer:NLoptim} admits a solution $w=(w^1, ..., w^N)$ such that $w^{i_1}=\cdots=w^{i_k}=0$ for some 
$\{i_1, \cdots, i_k\} \subset \{1, ..., N\}$. We have that $\nabla g_{i_l}(w) = -(e^{N}_{i_l})^\top$ and therefore the vectors
$\nabla g_{i_1}(w)$, ... $\nabla g_{i_k}(w)$, and $\nabla h(w)$ are linearly independent. 
By \cite[Theorem 5.2, Corollary 1]{Berkovitz2001}, we have that $\lambda_0 \neq 0$. 






For $\lambda_0>0$, up to rescaling the multipliers, we can let $\lambda_0=1$. Then \eqref{KKT(iii)MajorPlayermatrix} can be written as 
\begin{align} 
\begin{bmatrix} 
 \hat{y}^{1\top}_t \hat{y}^1_t & \hat{y}^{1\top}_t \hat{y}^2_t & \cdots & \hat{y}^{1\top}_t \hat{y}^N_t \\ 
 \hat{y}^{2\top}_t \hat{y}^1_t & \hat{y}^{2\top}_t \hat{y}^2_t & \cdots & \hat{y}^{2\top}_t \hat{y}^N_t \\
 \vdots & \vdots & \ddots & \vdots \\ 
 \hat{y}^{N\top}_t \hat{y}^1_t & \hat{y}^{N\top}_t \hat{y}^2_t & \cdots & \hat{y}^{N\top}_t \hat{y}^N_t
\end{bmatrix} 
\begin{bmatrix} 
w^1 \\ w^2 \\ \vdots \\ w^N 
\end{bmatrix} 
= 
\begin{bmatrix} 
  \hat{y}^{1\top}_t  \\ 
  \hat{y}^{2\top}_t   \\ 
\vdots \\ 
  \hat{y}^{N\top}_t   
\end{bmatrix} 
\sum_{i=1}^N y^i_t
+ 
\frac{1}{2} 
\begin{bmatrix} 
 \hat{\lambda}_1  \\ 
 \hat{\lambda}_2  \\ 
\vdots \\ 
 \hat{\lambda}_N  
\end{bmatrix} 
+ 
\frac{1}{2} 
\begin{bmatrix} 
  \mu \\ 
 \mu \\ 
\vdots \\ 
 \mu 
\end{bmatrix} \notag  
\end{align} 

\begin{align} 
\begin{bmatrix} 
w^1 \\ w^2 \\ \vdots \\ w^N 
\end{bmatrix} 
= 
\begin{bmatrix} 
 \hat{y}^{1\top}_t \hat{y}^1_t & \hat{y}^{1\top}_t \hat{y}^2_t & \cdots & \hat{y}^{1\top}_t \hat{y}^N_t \\ 
 \hat{y}^{2\top}_t \hat{y}^1_t & \hat{y}^{2\top}_t \hat{y}^2_t & \cdots & \hat{y}^{2\top}_t \hat{y}^N_t \\
 \vdots & \vdots & \ddots & \vdots \\ 
 \hat{y}^{N\top}_t \hat{y}^1_t & \hat{y}^{N\top}_t \hat{y}^2_t & \cdots & \hat{y}^{N\top}_t \hat{y}^N_t
\end{bmatrix}^{-1} 
\left\{ 
\begin{bmatrix} 
  \hat{y}^{1\top}_t  \\ 
  \hat{y}^{2\top}_t   \\ 
\vdots \\ 
  \hat{y}^{N\top}_t   
\end{bmatrix} 
\sum_{i=1}^N y^i_t
+ 
\frac{1}{2} 
\begin{bmatrix} 
 \hat{\lambda}_1  \\ 
 \hat{\lambda}_2  \\ 
\vdots \\ 
 \hat{\lambda}_N  
\end{bmatrix} 
+ 
\frac{1}{2} 
\begin{bmatrix} 
  \mu \\ 
 \mu \\ 
\vdots \\ 
 \mu 
\end{bmatrix} \right\} \geq 0 .  \label{w>=0}  
\end{align} 
From \eqref{KKT(ii)MajorPlayer:<hatlambda,w>=0}, we further have that 
\begin{align} 
 \sum_{i=1}^N \lambda_i = & \big[ \hat\lambda_1 \ \hat\lambda_2 \ \cdots \ \hat\lambda_N \big]
 \begin{bmatrix} 
w^1 \\ w^2 \\ \vdots \\ w^N 
\end{bmatrix}  \notag \\ 
= & 
\big[ \hat\lambda_1 \ \hat\lambda_2 \ \cdots \ \hat\lambda_N \big] 
\begin{bmatrix} 
 \hat{y}^{1\top}_t \hat{y}^1_t & \hat{y}^{1\top}_t \hat{y}^2_t & \cdots & \hat{y}^{1\top}_t \hat{y}^N_t \\ 
 \hat{y}^{2\top}_t \hat{y}^1_t & \hat{y}^{2\top}_t \hat{y}^2_t & \cdots & \hat{y}^{2\top}_t \hat{y}^N_t \\
 \vdots & \vdots & \ddots & \vdots \\ 
 \hat{y}^{N\top}_t \hat{y}^1_t & \hat{y}^{N\top}_t \hat{y}^2_t & \cdots & \hat{y}^{N\top}_t \hat{y}^N_t
\end{bmatrix}^{-1} 
\left\{ 
\begin{bmatrix} 
  \hat{y}^{1\top}_t  \\ 
  \hat{y}^{2\top}_t   \\ 
\vdots \\ 
  \hat{y}^{N\top}_t   
\end{bmatrix} 
\sum_{i=1}^N y^i_t
+ 
\frac{1}{2} 
\begin{bmatrix} 
 \hat{\lambda}_1  \\ 
 \hat{\lambda}_2  \\ 
\vdots \\ 
 \hat{\lambda}_N  
\end{bmatrix} 
+ 
\frac{1}{2} 
\begin{bmatrix} 
  \mu \\ 
 \mu \\ 
\vdots \\ 
 \mu 
\end{bmatrix} \right\} .  
\label{constraint:sumlambda=hatlambdaw} 
\end{align} 



Since $\sum_{i=1}^N w^i = 1$, we have 
\begin{align} 
 1 = & \big[ 1 \ 1 \ \cdots \ 1 \big]
 \begin{bmatrix} 
w^1 \\ w^2 \\ \vdots \\ w^N 
\end{bmatrix}  \notag \\ 
= & 
\big[ 1 \ 1 \ \cdots \ 1 \big] 
\begin{bmatrix} 
 \hat{y}^{1\top}_t \hat{y}^1_t & \hat{y}^{1\top}_t \hat{y}^2_t & \cdots & \hat{y}^{1\top}_t \hat{y}^N_t \\ 
 \hat{y}^{2\top}_t \hat{y}^1_t & \hat{y}^{2\top}_t \hat{y}^2_t & \cdots & \hat{y}^{2\top}_t \hat{y}^N_t \\
 \vdots & \vdots & \ddots & \vdots \\ 
 \hat{y}^{N\top}_t \hat{y}^1_t & \hat{y}^{N\top}_t \hat{y}^2_t & \cdots & \hat{y}^{N\top}_t \hat{y}^N_t
\end{bmatrix}^{-1} 
\left\{ 
\begin{bmatrix} 
  \hat{y}^{1\top}_t  \\ 
  \hat{y}^{2\top}_t   \\ 
\vdots \\ 
  \hat{y}^{N\top}_t   
\end{bmatrix} 
\sum_{i=1}^N y^i_t
+ 
\frac{1}{2} 
\begin{bmatrix} 
 \hat{\lambda}_1  \\ 
 \hat{\lambda}_2  \\ 
\vdots \\ 
 \hat{\lambda}_N  
\end{bmatrix} 
+ 
\frac{1}{2} 
\begin{bmatrix} 
  \mu \\ 
 \mu \\ 
\vdots \\ 
 \mu 
\end{bmatrix} \right\} \label{constraint:1=sumw}
\end{align} 

We need to find $w=(w^1, ..., w^N)$ and the multipliers $\{ \lambda_i \}_{i=1}^{2N}$ and $\mu$ that satisfy 
\eqref{w>=0}, \eqref{constraint:sumlambda=hatlambdaw}, and \eqref{constraint:1=sumw}. 
Since $w=(w^1, ..., w^N)$ is uniquely determined by \eqref{w>=0}, we focus on finding $\{ \lambda_i \}_{i=1}^{2N}$ and $\mu$ 
that satisfy 
\eqref{w>=0}, \eqref{constraint:sumlambda=hatlambdaw}, and \eqref{constraint:1=sumw}. 


Denote 
\begin{align} 
 \hat{\mathbf{Y}}_t = \big[ \hat{y}^1_t, \cdots , \hat{y}^N_t \big] , \quad 
  \mathbf{1} = \big[ 1, ..., 1 \big] , \quad 
  \hat{\boldsymbol{\lambda}} = \big[ \hat{\lambda}_1, ..., \hat{\lambda}_N \big]^\top  \notag 
\end{align} 
Then \eqref{constraint:1=sumw} can be written as 
\begin{align} 
 1 = \mathbf{1} (\hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \Big[ \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t + \frac{1}{2} \hat{\boldsymbol{\lambda}} 
  + \frac{1}{2} \mathbf{1}^\top \mu \Big] \notag 
\end{align} 
Then we have 
\begin{align} 
 \mu = 2 \big[ \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} \mathbf{1}^\top \big]^{-1} 
 \Big\{ 1 - \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \Big[ \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t + \frac{1}{2} \hat{\boldsymbol{\lambda}}  \Big] 
 \Big\} . \label{muhatlambda} 
\end{align} 
We substitute \eqref{muhatlambda} into \eqref{constraint:sumlambda=hatlambdaw} to obtain
\begin{align} 
 \sum_{i=1}^N \lambda_i = & \hat{\boldsymbol{\lambda}}^\top 
  ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \Big[ \hat{\mathbf{Y}}^\top_t \sum_{i=1}^N y^i_t + \frac{1}{2}\hat{\boldsymbol{\lambda}} + \frac{1}{2}\mathbf{1}^\top \mu \Big] \notag \\ 
 = & \hat{\boldsymbol{\lambda}}^\top ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \Big[ \hat{\mathbf{Y}}^\top_t \sum_{i=1}^N y^i_t + \frac{1}{2}\hat{\boldsymbol{\lambda}}  \Big] 
 \notag \\ 
  & + \hat{\boldsymbol{\lambda}}^\top ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \mathbf{1}^\top  \big[ \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} \mathbf{1}^\top \big]^{-1} \notag \\ 
 & - \hat{\boldsymbol{\lambda}}^\top ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \mathbf{1}^\top  \big[ \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} \mathbf{1}^\top \big]^{-1} 
   \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \Big[ \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t + \frac{1}{2} \hat{\boldsymbol{\lambda}}  \Big]  
\end{align} 


We substitute \eqref{muhatlambda} into \eqref{w>=0} to obtain 
\begin{align} 
 \mathbf{0} \leq & ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} \Big[ \hat{\mathbf{Y}}^\top_t \sum_{i=1}^N y^i_t + \frac{1}{2} 
 \hat{\boldsymbol{\lambda}} + \frac{1}{2} \mathbf{1}^\top \mu \Big] \notag \\ 
= & ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} \Big[ \hat{\mathbf{Y}}^\top_t \sum_{i=1}^N y^i_t + \frac{1}{2} 
 \hat{\boldsymbol{\lambda}}  \Big] \notag \\ 
 & +  (\hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1}  \mathbf{1}^\top 
  \big[ \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} \mathbf{1}^\top \big]^{-1} 
 \Big\{ 1 - \mathbf{1} ( \hat{\mathbf{Y}}^\top_t \hat{\mathbf{Y}}_t)^{-1} 
 \Big[ \hat{\mathbf{Y}}_t^\top \sum_{i=1}^N y^i_t + \frac{1}{2} \hat{\boldsymbol{\lambda}}  \Big] 
 \Big\} .  \notag 
\end{align} 

Since 
\begin{align} 
& \frac{\partial}{\partial w^k} 
 \sum_{i=1}^N \big\| y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big\|^2 
 = \hat{y}^{k\top}_t \sum_{i=1}^N \big( y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big) ,  \notag \\ 
 %%% 
& \frac{\partial^2}{\partial w^k \partial w^l } 
 \sum_{i=1}^N \big\| y^i_t - \sum_{j=1}^N w^j \hat{y}^j_t \big\|^2 
 = \hat{y}^{k\top}_t \hat{y}^l_t , \notag 
\end{align}  
the Hessian matrix of the major player's objective function \eqref{MajorPlayer:NLoptim} is given by
\begin{align} 
H = \big( \hat{y}^{k\top}_t \hat{y}^l_t \big)_{1\leq k, l \leq N} 
= \begin{bmatrix} 
  \hat{y}^{1\top}_t  \\ 
  \hat{y}^{2\top}_t   \\ 
\vdots \\ 
  \hat{y}^{N\top}_t   
\end{bmatrix} 
\begin{bmatrix} 
  \hat{y}^1_t  & 
  \hat{y}^2_t   & 
\cdots & 
  \hat{y}^N_t   
\end{bmatrix} ,  
\label{HessianMajorPlayer}
\end{align} 
which is semi-positive definite. 
Therefore the major player's objective is convex.  
\end{comment} 



