    \Fn{\FSub{$m$}}{
        $\Z \gets \{\}$ \tcp*{set of groups}
        \For{$s\gets 0$ \KwTo $m$}{
            Initialize $\Z[s] \gets []$ \tcp*{for degree-$s$ monomials}
            $i \gets \operatorname{bin2dec}([1]\times(m-s)+[0]\times s)$\;
            Append $i$ to $\Z[s]$\;
            \For{$d \gets 0$ \KwTo $s\times(m-s)$}{
                $\mathcal{L} \gets []$ \tcp*{for $|\lambda_f|=d$, Lemma \ref{lma:lambda_bounds}}
                \For{$i \gets \Z[s][-1]$}{
                    $f \gets \bin(i, m)$\;
                    \ForEach{\( j \) \textbf{in} indices of \( f \)}{
                        \If{\( f[j] = 0 \) \textbf{and} \( j > 0 \) \textbf{and} \( f[j-1] = 1 \)}{
                            Create a copy \( g \gets f \)\;
                            Swap \( g[j] \) and \( g[j-1] \): \( g[j] \gets 1 \), \( g[j-1] \gets 0 \) \tcp*{Lemma \ref{lma:lambda+1}}
                            Append \( \operatorname{bin2dec}(g) \) to \( \mathcal{L} \)\;
                        }
                    }
                }
                Append \( \Unique(\mathcal{L}) \) to \( \Z[s] \)\;
            }
        } 
        \KwRet $\Z$;
    }
\end{algorithm}

