\section{A sufficient condition for termination}

The purpose of this section is to prove the following theorem.

\begin{theorem} \label{thm-sufficient}
    Let $(U_1,U_2,<)$ be a coherent extended word equation. If $G_{U_1,U_2,<}$ is acyclic, then $(U_1,U_2,<)$ is terminating. Furthermore, $(U_1,U_2,<)$ terminates after the application of at most $2^N$ coherent extended Nielsen transformations, where $N = |U_1| + |U_2|$.
\end{theorem}

\noindent
We need the following definitions.
\begin{definition}
    Given an extended word equation $(U_1, U_2, <)$ such that $G_{U_1, U_2, <} = (B,E)$ is acyclic, the \emph{fecundity} of the boundary $(i,j)$ is recursively defined as
    \[
        f_{U_1,U_2,<}(i,j) = 1 + \max_{\substack{(i'',j'') \in B \\ (i,j) \ \text{cuts} \ (i'',j'')}} \sum_{\substack{(i',j') \in B \\ (i'',j'') \ \text{mirrors} \ (i',j')}} f_{U_1,U_2,<}(i',j').
    \]
\end{definition}
\noindent
Note that the definition of $f_{U_1,U_2,<}(i,j)$ only depends on the values of $f_{U_1,U_2,<}(i',j')$ where $((i,j),(i',j')) \in E$, so the recursion is well-founded if $G_{U_1, U_2, <}$ is acyclic.
\begin{definition}
    Given an extended word equation $(U_1, U_2, <)$ such that $G_{U_1, U_2, <} = (B,E)$ is acyclic, its \emph{measure} is
    \[
        m(U_1, U_2, <) = \sum_{(i,j) \in B} f_{U_1,U_2,<}(i,j).
    \]
\end{definition}
We will prove Theorem~\ref{thm-sufficient} by showing that with each application of a coherent extended Nielsen transformation, the measure decreases. To that end, let $(U'_1,U'_2,<')$ be the result of applying a coherent extended Nielsen transformation to $(U_1,U_2,<)$. Write $G_{U_1, U_2, <} = (B,E)$ and $G_{U'_1, U'_2, <'} = (B',E')$. Assume that $G_{U_1, U_2, <}$ is acyclic. We aim to show that $m(U'_1, U'_2, <') < m(U_1, U_2, <)$.

Before going into the details, a brief description of the proof strategy is in order. The difficult part is proving the measure decreases when a case II extended Nielsen transformation is applied. In this case, let $B^-$, $B'^-$, and $B'^+$ be defined as in Section~\ref{sec-ext-nielsen}. Lemma~\ref{lem-walk-case2} shows that $G_{U'_1, U'_2, <'}$ is acyclic, so $f_{U'_1,U'_2,<'}$ is well-defined. Lemma~\ref{lem-mu-decrease} implies that the fecundity of every boundary in $B'^-$ is at most the fecundity of its corresponding boundary in $B^-$. Lemma~\ref{lem-less-21} shows that the sum of the fecundities of the boundaries in $B'^+$ is strictly less than the fecundity of $(2,1)$ in $(U_1,U_2,<)$. The boundary $(2,1)$ in $(U_1,U_2,<)$ does not correspond to any boundary in $(U'_1,U'_2,<')$. Thus, in the process of going from $(U_1,U_2,<)$ to $(U'_1,U'_2,<')$, we lose the boundary $(2,1)$, add some boundaries whose fecundities sum to strictly less than that of $(2,1)$ in $(U_1,U_2,<)$, and retain some boundaries whose fecundities do not increase. Therefore, $m(U'_1, U'_2, <') < m(U_1, U_2, <)$.

First, we prove a few lemmas for when a case I extended Nielsen transformation is applied.

\begin{lemma} \label{lem-mirror-case1}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case I coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$, then either $(i,j+1)$ mirrors $(i',j'+1)$ with respect to $(U_1,U_2,<)$ or $\{U_{i,j+1}, U_{i',j'+1}\} = \{U_{1,1}, U_{2,1}\}$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$. Then, $(i,j) \not\approx' (i',j')$, so $(i,j+1) \not\approx (i',j'+1)$. If $U_{i,j+1} = U_{i',j'+1}$, then $(i,j+1)$ mirrors $(i',j'+1)$ with respect to $(U_1,U_2,<)$, and we are done. So suppose $U_{i,j+1} \neq U_{i',j'+1}$.

    Now, we have $U'_{i,j} = T(U_{i,j+1})$ and $U'_{i',j'} = T(U_{i',j'+1})$, where $T$ is the endomorphism on $\mathcal{X}^*$ given by $T(U_{2,1}) = U_{1,1}$ and the identity function on other elements of $\mathcal{X}$. Since $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$, we have
    \[
        T(U_{i,j+1}) = U'_{i,j} = U'_{i',j'} = T(U_{i',j'+1}).
    \]
    Thus, $\{U_{i,j+1}, U_{i',j'+1}\} = \{U_{1,1}, U_{2,1}\}$, as desired.
\end{proof}

\begin{lemma} \label{lem-walk-case1}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case I coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $G_{U_1,U_2,<}$ is acyclic, then so is $G_{U'_1,U'_2,<'}$.
\end{lemma}
\begin{proof}
    It suffices to show that if $((i,j),(i',j')) \in E'$, then there is a walk of length at least 1 from $(i,j+1)$ to $(i',j'+1)$ in $G_{U_1, U_2, <}$. So suppose $((i,j),(i',j')) \in E'$. Then, with respect to $(U'_1,U'_2,<')$, $(i,j)$ cuts some $(i'',j'') \in B'$ and $(i'',j'')$ mirrors $(i',j')$. It follows that with respect to $(U_1,U_2,<)$, $(i,j+1)$ cuts $(i'',j''+1)$. If $(i'',j''+1)$ mirrors $(i',j'+1)$ with respect to $(U_1,U_2,<)$, then $((i,j+1),(i',j'+1)) \in E$, and we are done. Otherwise, $\{U_{i'',j''+1}, U_{i',j'+1}\} = \{U_{1,1}, U_{2,1}\}$ by Lemma~\ref{lem-mirror-case1}.

    If $U_{i'',j''+1} = U_{1,1}$ and $U_{i',j'+1} = U_{2,1}$, then $(i'',j''+1)$ mirrors $(1,1)$ with respect to $(U_1,U_2,<)$. Thus, $((i,j+1),(1,1)) \in E$. Also, with respect to $(U_1,U_2,<)$, $(1,1)$ cuts $(2,1)$, which mirrors $(i',j'+1)$. Thus, $((1,1),(i',j'+1)) \in E$. The walk $((i,j+1),(1,1),(i',j'+1))$ is our desired walk in $G_{U_1, U_2, <}$.

    Similarly, if $U_{i'',j''+1} = U_{2,1}$ and $U_{i',j'+1} = U_{1,1}$, then $((i,j+1),(2,1),(i',j'+1))$ is our desired walk in $G_{U_1, U_2, <}$.
\end{proof}

\begin{lemma} \label{lem-case1}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case I coherent extended Nielsen transformation to $(U_1,U_2,<)$. Then, for every $(i,j) \in B'$, we have $f_{U'_1,U'_2,<'}(i,j) \le \break f_{U_1,U_2,<}(i,j+1)$.
\end{lemma}
\begin{proof}
    First, $G_{U'_1,U'_2,<'}$ is acyclic by Lemma~\ref{lem-walk-case1}, so $f_{U'_1,U'_2,<'}$ is well-defined. We may inductively assume that the lemma is true for every $(i',j') \in B'$ such that $((i,j),(i',j')) \in E'$.

    We have
    \[
        f_{U'_1,U'_2,<'}(i,j) = 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j')
    \]
    for some $(i'',j'') \in B'$ such that $(i,j)$ cuts $(i'',j'')$ with respect to $(U'_1,U'_2,<')$. Then, $(i,j+1)$ cuts $(i'',j''+1)$ with respect to $(U_1,U_2,<)$.

    First, suppose $U_{i'',j''+1} \notin \{U_{1,1}, U_{2,1}\}$. Then,
    \begin{align*}
        f_{U'_1,U'_2,<'}(i,j) &= 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j') \\
        &\le 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U_1,U_2,<}(i',j'+1) \\
        &\le 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j''+1) \ \text{mirrors} \ (i',j'+1) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j'+1) \quad \text{by Lemma~\ref{lem-mirror-case1}} \\
        &= 1 + \sum_{\substack{(i',j') \in B \\ (i'',j''+1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') \le f_{U_1,U_2,<}(i,j+1).
    \end{align*}

    Next, suppose $U_{i'',j''+1} = U_{1,1}$. Then,
    \begin{align*}
        f_{U'_1,U'_2,<'}(i,j) = 1 &+ \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j') \\
        \le 1 &+ \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U_1,U_2,<}(i',j'+1) \\
        \le 1 &+ \sum_{\substack{(i',j') \in B' \\ (i'',j''+1) \ \text{mirrors} \ (i',j'+1) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j'+1) \\
        &+ \sum_{\substack{(i',j') \in B' \\ U_{i',j'+1} = U_{2,1}}} f_{U_1,U_2,<}(i',j'+1) \quad \text{by Lemma~\ref{lem-mirror-case1}} \\
        = 1 &+ \sum_{\substack{(i',j') \in B \setminus \{(1,1),(2,1)\} \\ (i'',j''+1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') + \sum_{\substack{(i',j') \in B \\ (2,1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') \\
        < 1 &+ \sum_{\substack{(i',j') \in B \setminus \{(1,1)\} \\ (i'',j''+1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') + f_{U_1,U_2,<}(1,1) \le f_{U_1,U_2,<}(i,j+1).
    \end{align*}

    Finally, if $U_{i'',j''+1} = U_{2,1}$, then we similarly have
    \[
        f_{U'_1,U'_2,<'}(i,j) < 1 + \sum_{\substack{(i',j') \in B \setminus \{(2,1)\} \\ (i'',j''+1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') + f_{U_1,U_2,<}(2,1) \le f_{U_1,U_2,<}(i,j+1). \qedhere
    \]
\end{proof}

If a case I extended Nielsen transformation is not applied, we may assume without loss of generality that a case II extended Nielsen transformation is applied, since cases II and III are symmetric. We need several lemmas for this case. Let $\mu$, $\nu$, $B^-$, $B'^-$, and $B'^+$ be defined as in Section~\ref{sec-ext-nielsen}.

\begin{lemma} \label{lem-mu-preserve}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. Then, for every $(i,j) \in B^-$, we have $U_{i,j} = U'_{i,\mu(i,j)}$.
\end{lemma}
\begin{proof}
    We have $U'_i = T(U_i)^+$, where $T$ is the endomorphism on $\mathcal{X}^*$ given by $T(U_{1,1}) = U_{2,1} U_{1,1}$ and the identity function on other elements of $\mathcal{X}$. We have
    \[
        T(U_i) = T(U_{i,1} \cdots U_{i,j-1}) T(U_{i,j}) T(U_{i,j+1} \cdots).
    \]
    Also,
    \[
        |T(U_{i,1} \cdots U_{i,j-1})| = j-1 + |\{(i,j') \mid j' \le j-1 \ \text{and} \ U_{i,j'} = U_{1,1}\}|,
    \]
    where $\left|\cdot\right|$ is the length function on $\mathcal{X}^*$.

    Suppose first that $U_{i,j} \neq U_{1,1}$. Then,
    \[
        T(U_i) = T(U_{i,1} \cdots U_{i,j-1}) U_{i,j} T(U_{i,j+1} \cdots).
    \]
    Thus, $U_{i,j}$ is equal to the variable in position
    \[
        j + |\{(i,j') \mid j' \le j-1 \ \text{and} \ U_{i,j'} = U_{1,1}\}| = j + |\{(i,j') \mid j' \le j \ \text{and} \ U_{i,j'} = U_{1,1}\}| = \mu(i,j) + 1
    \]
    of $T(U_i)$. Hence, $U'_{i,\mu(i,j)} = U_{i,j}$.

    On the other hand, suppose that $U_{i,j} = U_{1,1}$. Then,
    \[
        T(U_i) = T(U_{i,1} \cdots U_{i,j-1}) U_{2,1} U_{1,1} T(U_{i,j+1} \cdots).
    \]
    Thus, $U_{i,j}$ is equal to the variable in position
    \[
        j + |\{(i,j') \mid j' \le j-1 \ \text{and} \ U_{i,j'} = U_{1,1}\}| + 1 = j + |\{(i,j') \mid j' \le j \ \text{and} \ U_{i,j'} = U_{1,1}\}| = \mu(i,j) + 1
    \]
    of $T(U_i)$. Hence, $U'_{i,\mu(i,j)} = U_{i,j}$.
\end{proof}

\begin{lemma} \label{lem-nu-plus-2}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^+$, then $U'_{i,j} = U_{2,1}$ and $U'_{i,j+1} = U_{1,1}$.
\end{lemma}
\begin{proof}
    Since $(i,j) \in B'^+$, we have $j+1 = \mu(i,k)$ for some $k$ such that $U_{i,k} = U_{1,1}$. By Lemma~\ref{lem-mu-preserve},
    \[
        U'_{i,j+1} = U'_{i,\mu(i,k)} = U_{i,k} = U_{1,1}.
    \]
    Recall that $U'_i = T(U_i)^+$, where $T$ is the endomorphism on $\mathcal{X}^*$ given by $T(U_{1,1}) = U_{2,1} U_{1,1}$ and the identity function on other elements of $\mathcal{X}$. Since $U'_{i,j}$ immediately precedes $U'_{i,j+1} = U_{1,1}$, we have $U'_{i,j} = U_{2,1}$.
\end{proof}

\begin{lemma} \label{lem-nu-j-plus-1}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^+$, then $\nu(i,j) = \nu(i,j+1)$.
\end{lemma}
\begin{proof}
    Lemma~\ref{lem-nu-plus-2} implies
    \[
        \left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le j+1 \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right| - \left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le j \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right| = 1.
    \]
    Hence,
    \begin{align*}
        \nu(i,j) &= j - \left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le j \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right| + 1 \\
        &= j+1 - \left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le j+1 \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right| + 1 = \nu(i,j+1). \qedhere
    \end{align*}
\end{proof}

\begin{lemma} \label{lem-boundary-order}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^-$ and $(i,j) <' (i',j')$, then $(i,\nu(i,j)) < (i',\nu(i',j'))$.
\end{lemma}
\begin{proof}
    If $(i',j') \in B'^-$, then this is true by the definition of an extended Nielsen transformation. So suppose $(i',j') \in B'^+$. Then, $(i',j'+1) \in B'^-$, so $(i,\nu(i,j)) < (i',\nu(i',j'+1))$. By Lemma~\ref{lem-nu-j-plus-1}, $\nu(i',j') = \nu(i',j'+1)$, so $(i,\nu(i,j)) < (i',\nu(i',j'))$.
\end{proof}

\begin{lemma} \label{lem-consec-plus}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^+$, then $(i,j+1) \notin B'^+$.
\end{lemma}
\begin{proof}
    Recall that $B'^- = \{(i',\mu(i',j')) \mid (i',j') \in B^-\}$ and $B'^+ = B' \setminus B'^-$. The lemma follows from the observation that $\mu(i',j'+1) \le \mu(i',j') + 2$ for all $i',j'$.
\end{proof}

\begin{lemma} \label{lem-cut-nu}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j)$ cuts $(i',j')$ with respect to $(U'_1,U'_2,<')$, then $(i,\nu(i,j))$ cuts $(i',\nu(i',j'))$ with respect to $(U_1,U_2,<)$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ cuts $(i',j')$ with respect to $(U'_1,U'_2,<')$. This means
    \begin{align*}
        (i,j) &\neq (i',j'), \\
        (i,j-1) &<' (i',j'), \quad\text{and} \\
        (i',j'-1) &<' (i,j),
    \end{align*}
    which implies $\{i,i'\} = \{1,2\}$. Thus, $(i,\nu(i,j)) \neq (i',\nu(i',j'))$.

    We claim that $(i,\nu(i,j)-1) < (i',\nu(i',j'))$, which we prove by splitting into a few cases.

    If $(i,j-1) \in B'^-$, then $(i,\nu(i,j-1)) < (i',\nu(i',j'))$ by Lemma~\ref{lem-boundary-order}. We have $\nu(i,j) - 1 \le \nu(i,j-1)$, so $(i,\nu(i,j)-1) < (i',\nu(i',j'))$ in this case.

    If $(i,j-1) \in B'^+$ and $j \neq 2$, then $(i,j-2) \in B'^-$ by Lemma~\ref{lem-consec-plus}, so $(i,\nu(i,j-2)) < (i',\nu(i',j'))$ by Lemma~\ref{lem-boundary-order}. We have $\nu(i,j-1) - 1 \le \nu(i,j-2)$, and by Lemma~\ref{lem-nu-j-plus-1}, $\nu(i,j-1) = \nu(i,j)$. Hence, $\nu(i,j) - 1 \le \nu(i,j-2)$, so $(i,\nu(i,j)-1) < (i',\nu(i',j'))$ in this case.

    If $(i,j-1) \in B'^+$ and $j=2$, then we claim $i=2$. Indeed, $(1,\mu(1,1)) = (1,1)$, so $(1,1) \in B'^-$. Now, we have $(i,\nu(i,j-1)-1) = (2,1) < (i',\nu(i',j'))$, since $i \not=i'$ and $(2,1)$ is the least element in $B$. By Lemma~\ref{lem-nu-j-plus-1}, $\nu(i,j-1) = \nu(i,j)$, so $(i,\nu(i,j)-1) < (i',\nu(i',j'))$ in this case.

    Finally, if $(i,j-1) \notin B'^- \cup B'^+ = B'$, then $j=1$. If $i=1$, then $\nu(i,j) = 1$, so $(i,\nu(i,j)-1) = (i,0) < (i',\nu(i',j'))$. If $i=2$, then $\nu(i,j) = 2$, so $(i,\nu(i,j)-1) = (2,1) < (i',\nu(i',j'))$.

    We have proved that $(i,\nu(i,j)-1) < (i',\nu(i',j'))$. By symmetry, we can also conclude that $(i',\nu(i',j')-1) < (i,\nu(i,j))$. Therefore, $(i,\nu(i,j))$ cuts $(i',\nu(i',j'))$ with respect to $(U_1,U_2,<)$.
\end{proof}

\begin{lemma} \label{lem-left-inverse}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B^-$, then $\nu(i,\mu(i,j)) = j$.
\end{lemma}
\begin{proof}
    We claim that
    \[
        |\{(i,j') \mid j' \le j \ \text{and} \ U_{i,j'} = U_{1,1}\}| = \left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le \mu(i,j) \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right|.
    \]
    Observe that the left-hand side is the number of variables equal to $U_{1,1}$ in
    \[
        U_{i,1} U_{i,2} \cdots U_{i,j},
    \]
    and the right-hand side is the number of variables equal to $U_{1,1}$ in
    \[
        U'_{i,1} U'_{i,2} \cdots U'_{i,\mu(i,j)} = T(U_{i,1} U_{i,2} \cdots U_{i,j})^+,
    \]
    where $T$ is the endomorphism on $\mathcal{X}^*$ given by $T(U_{1,1}) = U_{2,1} U_{1,1}$ and the identity function on other elements of $\mathcal{X}$. Now, $T$ preserves the number of instances of $U_{1,1}$ in a word, and the first variable in $T(U_{i,1} U_{i,2} \cdots U_{i,j})$ is not $U_{1,1}$. It follows that $U_{i,1} U_{i,2} \cdots U_{i,j}$ and $T(U_{i,1} U_{i,2} \cdots U_{i,j})^+$ have the same number of variables equal to $U_{1,1}$, establishing the claim.

    Now, we have
    \begin{align*}
        \nu(i,\mu(i,j)) &= \mu(i,j)-\left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le \mu(i,j) \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right| + 1 \\
        &= j+|\{(i,j') \mid j' \le j \ \text{and} \ U_{i,j'} = U_{1,1}\}|-\left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le \mu(i,j) \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right| \\
        &= j. \qedhere
    \end{align*}
\end{proof}

\begin{lemma} \label{lem-nu-minus}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^-$, then $U_{i,\nu(i,j)} = U'_{i,j}$.
\end{lemma}
\begin{proof}
    Let $k$ be such that $\mu(i,k) = j$. By Lemmas~\ref{lem-left-inverse} and \ref{lem-mu-preserve}, we have
    \[
        U_{i,\nu(i,j)} = U_{i,\nu(i,\mu(i,k))} = U_{i,k} = U'_{i,\mu(i,k)} = U'_{i,j}. \qedhere
    \]
\end{proof}

\begin{lemma} \label{lem-nu-plus-1}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^+$, then $(i,\nu(i,j))$ mirrors $(1,1)$ with respect to $(U_1,U_2,<)$.
\end{lemma}
\begin{proof}
    Suppose $(i,j) \in B'^+$. Then, $(i,j+1) \in B'^-$ by Lemma~\ref{lem-consec-plus}, so by Lemmas~\ref{lem-nu-j-plus-1}, \ref{lem-nu-minus}, and \ref{lem-nu-plus-2}, we have
    \[
        U_{i,\nu(i,j)} = U_{i,\nu(i,j+1)} = U'_{i,j+1} = U_{1,1}.
    \]
    It remains to show that $(i,\nu(i,j)) \not\approx (1,1)$. Suppose for contradiction that $(i,\nu(i,j)) \approx (1,1)$. By coherence, $(i,\nu(i,j)-1) \approx (1,0)$, so $\nu(i,j) = 1$. Hence,
    \[
        j = \left|\left\{(i,j') \mathrel{}\middle|\mathrel{} j' \le j \ \text{and} \ U'_{i,j'} = U_{1,1}\right\}\right|,
    \]
    which implies that $U'_{i,j'} = U_{1,1}$ for all $j' \le j$. In particular, $U'_{i,j} = U_{1,1}$, contradicting Lemma~\ref{lem-nu-plus-2}.
\end{proof}

\begin{lemma} \label{lem-nu-neq}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$ and $U_{i,\nu(i,j)} = U_{i',\nu(i',j')}$, then $(i,\nu(i,j))$ mirrors $(i',\nu(i',j'))$ with respect to $(U_1,U_2,<)$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$ and $U_{i,\nu(i,j)} = U_{i',\nu(i',j')}$. It suffices to show that $(i,\nu(i,j)) \not\approx (i',\nu(i',j'))$. Without loss of generality, $(i,j) <' (i',j')$. If $(i,j) \in B'^-$, then by Lemma~\ref{lem-boundary-order}, $(i,\nu(i,j)) < (i',\nu(i',j'))$, as desired. If $(i,j) \in B'^+$ and $(i',j') \in B'^-$, then by Lemmas~\ref{lem-nu-plus-1}, \ref{lem-nu-minus}, and \ref{lem-nu-plus-2}, we have
    \[
        U_{1,1} = U_{i,\nu(i,j)} = U_{i',\nu(i',j')} = U'_{i',j'} = U'_{i,j} = U_{2,1},
    \]
    a contradiction. Finally, if $(i,j), (i',j') \in B'^+$, then by Lemma~\ref{lem-nu-plus-2}, $U'_{i,j+1} = U'_{i',j'+1} = U_{1,1}$. By coherence, $(i,j+1) <' (i',j'+1)$. Since $(i,j+1), (i',j'+1) \in B'^-$ by Lemma~\ref{lem-consec-plus}, we have $(i,\nu(i,j+1)) < (i',\nu(i',j'+1))$. By Lemma~\ref{lem-nu-j-plus-1}, $\nu(i,j) = \nu(i,j+1)$ and $\nu(i',j') = \nu(i',j'+1)$. Therefore, $(i,\nu(i,j)) < (i',\nu(i',j'))$, as desired.
\end{proof}

\begin{lemma} \label{lem-mirror-case2}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$ and $(i,\nu(i,j))$ does not mirror $(i',\nu(i',j'))$ with respect to $(U_1,U_2,<)$, then either $(i,j) \in B'^+$ and $(i',j') \in \{(i'',j'') \in B'^- \mid U'_{i'',j''} = U_{2,1}\}$ or else $(i,j) \in \{(i'',j'') \in B'^- \mid U'_{i'',j''} = U_{2,1}\}$ and $(i',j') \in B'^+$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$ and $(i,\nu(i,j))$ does not mirror $(i',\nu(i',j'))$ with respect to $(U_1,U_2,<)$. By Lemma~\ref{lem-nu-neq}, $U_{i,\nu(i,j)} \neq U_{i',\nu(i',j')}$. We first show that either $(i,j) \in B'^+$ and $(i',j') \in B'^-$ or else $(i,j) \in B'^-$ and $(i',j') \in B'^+$. If not, then either $(i,j), (i',j') \in B'^+$ or $(i,j), (i',j') \in B'^-$. In the former case, Lemma~\ref{lem-nu-plus-1} implies that $U_{i,\nu(i,j)} = U_{1,1} = U_{i',\nu(i',j')}$, a contradiction. In the latter case, Lemma~\ref{lem-nu-minus} implies that
    \[
        U_{i,\nu(i,j)} = U'_{i,j} = U'_{i',j'} = U_{i',\nu(i',j')},
    \]
    a contradiction.

    If $(i,j) \in B'^+$ and $(i',j') \in B'^-$, then by Lemma~\ref{lem-nu-plus-2}, $U'_{i',j'} = U'_{i,j} = U_{2,1}$, so $(i',j') \in \{(i'',j'') \in B'^- \mid U'_{i'',j''} = U_{2,1}\}$. Similarly, if $(i,j) \in B'^-$ and $(i',j') \in B'^+$, then $(i,j) \in \{(i'',j'') \in B'^- \mid U'_{i'',j''} = U_{2,1}\}$.
\end{proof}

\begin{lemma} \label{lem-nu-mirror}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j) \in B'^-$ and $U'_{i,j} = U_{2,1}$, then $(i,\nu(i,j))$ mirrors $(2,1)$ with respect to $(U_1,U_2,<)$.
\end{lemma}
\begin{proof}
    Suppose $(i,j) \in B'^-$ and $U'_{i,j} = U_{2,1}$. Then, by Lemma~\ref{lem-nu-minus}, $U_{i,\nu(i,j)} = U'_{i,j} = U_{2,1}$. It remains to show that $(i,\nu(i,j)) \not\approx (2,1)$. If not, then $(i,\nu(i,j)) = (2,1)$, so $i=2$. But $\nu(2,j) \ge 2$ for all $j \ge 1$, a contradiction. Hence, $(i,\nu(i,j))$ mirrors $(2,1)$ with respect to $(U_1,U_2,<)$.
\end{proof}

\begin{lemma} \label{lem-walk-case2}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $G_{U_1,U_2,<}$ is acyclic, then so is $G_{U'_1,U'_2,<'}$.
\end{lemma}
\begin{proof}
    It suffices to show that if $((i,j),(i',j')) \in E'$, then there is a walk of length at least 1 from $(i,\nu(i,j))$ to $(i',\nu(i',j'))$ in $G_{U_1, U_2, <}$. So suppose $((i,j),(i',j')) \in E'$. Then, with respect to $(U'_1,U'_2,<')$, $(i,j)$ cuts some $(i'',j'') \in B'$ and $(i'',j'')$ mirrors $(i',j')$. By Lemma~\ref{lem-cut-nu}, $(i,\nu(i,j))$ cuts $(i'',\nu(i'',j''))$ with respect to $(U_1,U_2,<)$. If $(i'',\nu(i'',j''))$ mirrors $(i',\nu(i',j'))$ with respect to $(U_1,U_2,<)$, then $((i,\nu(i,j)),(i',\nu(i',j'))) \in E$, and we are done. Otherwise, by Lemma~\ref{lem-mirror-case2}, either $(i'',j'') \in B'^+$ and $(i',j') \in \{(i''',j''') \in B'^- \mid U'_{i''',j'''} = U_{2,1}\}$ or else $(i'',j'') \in \{(i''',j''') \in B'^- \mid U'_{i''',j'''} = U_{2,1}\}$ and $(i',j') \in B'^+$.

    First, suppose $(i'',j'') \in B'^+$ and $(i',j') \in \{(i''',j''') \in B'^- \mid U'_{i''',j'''} = U_{2,1}\}$. Then, by Lemma~\ref{lem-nu-plus-1}, $(i'',\nu(i'',j''))$ mirrors $(1,1)$ with respect to $(U_1,U_2,<)$, so $((i,\nu(i,j)), (1,1)) \in E$. Also, $(1,1)$ cuts $(2,1)$ with respect to $(U_1,U_2,<)$. By Lemma~\ref{lem-nu-mirror}, $(i',\nu(i',j'))$ mirrors $(2,1)$ with respect to $(U_1,U_2,<)$. Thus, $((1,1), (i',\nu(i',j'))) \in E$. The walk $((i,\nu(i,j)), (1,1), \break (i',\nu(i',j')))$ is our desired walk in $G_{U_1, U_2, <}$.

    Similarly, if $(i'',j'') \in \{(i''',j''') \in B'^- \mid U'_{i''',j'''} = U_{2,1}\}$ and $(i',j') \in B'^+$, then \break $((i,\nu(i,j)), (2,1), (i',\nu(i',j')))$ is our desired walk in $G_{U_1, U_2, <}$.
\end{proof}

\begin{lemma} \label{lem-mu-decrease}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. Then, for every $(i,j) \in B'$, we have $f_{U'_1,U'_2,<'}(i,j) \le f_{U_1,U_2,<}(i,\nu(i,j))$.
\end{lemma}
\begin{proof}
    First, $G_{U'_1,U'_2,<'}$ is acyclic by Lemma~\ref{lem-walk-case2}, so $f_{U'_1,U'_2,<'}$ is well-defined. We may inductively assume that the lemma is true for every $(i',j') \in B'$ such that $((i,j),(i',j')) \in E'$.

    We have
    \[
        f_{U'_1,U'_2,<'}(i,j) = 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j')
    \]
    for some $(i'',j'') \in B'$ such that $(i,j)$ cuts $(i'',j'')$ with respect to $(U'_1,U'_2,<')$. Then, by Lemma~\ref{lem-cut-nu}, $(i,\nu(i,j))$ cuts $(i'',\nu(i'',j''))$ with respect to $(U_1,U_2,<)$.

    First, suppose $(i'',j'') \notin B'^+ \cup \{(i',j') \in B'^- \mid U'_{i',j'} = U_{2,1}\}$. Then, $U'_{i'',j''} \neq U_{2,1}$, so by Lemma~\ref{lem-nu-plus-2}, $(i'',j'')$ does not mirror any boundary in $B'^+$ with respect to $(U'_1,U'_2,<')$. Hence,
    \begin{align*}
        f_{U'_1,U'_2,<'}(i,j) &= 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j') \\
        &= 1 + \sum_{\substack{(i',j') \in B'^- \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j') \\
        &\le 1 + \sum_{\substack{(i',j') \in B'^- \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U_1,U_2,<}(i',\nu(i',j')) \\
        &\le 1 + \sum_{\substack{(i',j') \in B'^- \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',\nu(i',j')) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',\nu(i',j')) \quad \text{by Lemma~\ref{lem-mirror-case2}} \\
        &= 1 + \sum_{\substack{(i',j') \in B^- \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',\nu(i',\mu(i',j'))) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',\nu(i',\mu(i',j'))) \\
        &= 1 + \sum_{\substack{(i',j') \in B^- \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') \quad \text{by Lemma~\ref{lem-left-inverse}} \\
        &\le f_{U_1,U_2,<}(i,\nu(i,j)).
    \end{align*}

    Next, suppose $(i'',j'') \in B'^+$. Then,
    \begin{align*}
        f_{U'_1,U'_2,<'}(i,j) &= 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U'_1,U'_2,<'}(i',j') \\
        &\le 1 + \sum_{\substack{(i',j') \in B' \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}} f_{U_1,U_2,<}(i',\nu(i',j')) \\
        &= 1 + \smashoperator[r]{\sum_{\substack{(i',j') \in B'^+ \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j')) + \smashoperator[r]{\sum_{\substack{(i',j') \in B'^- \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j')).
    \end{align*}
    We bound each of these sums as follows. For the first sum, we have
    \begin{align*}
        \smashoperator[r]{\sum_{\substack{(i',j') \in B'^+ \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j')) &\le \smashoperator[r]{\sum_{\substack{(i',j') \in B'^+ \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',\nu(i',j')) \\ \text{w.r.t.} \ (U_1,U_2,<)}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j')) \quad \text{by Lemma~\ref{lem-mirror-case2}} \\
        &= \qquad \smashoperator{\sum_{\substack{(i',j') \in B'^+ \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',\nu(i',j'+1)) \\ \text{w.r.t.} \ (U_1,U_2,<)}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j'+1)) \quad \text{by Lemma~\ref{lem-nu-j-plus-1}} \\
        &\le \smashoperator[r]{\sum_{\substack{(i',j') \in B'^- \setminus \{(1,1),(2,1)\} \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',\nu(i',j')) \\ \text{w.r.t.} \ (U_1,U_2,<)}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j')) \quad \text{by Lemma~\ref{lem-consec-plus}} \\
        &\le \sum_{\substack{(i',j') \in B^- \setminus \{(1,1)\} \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',\nu(i',\mu(i',j'))) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',\nu(i',\mu(i',j'))) \\
        &= \sum_{\substack{(i',j') \in B^- \setminus \{(1,1)\} \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') \quad \text{by Lemma~\ref{lem-left-inverse}}.
    \end{align*}
    If $(i',j') \in B'^-$ and $(i'',j'')$ mirrors $(i',j')$ with respect to $(U'_1,U'_2,<')$, then by Lemma~\ref{lem-nu-plus-2}, $U'_{i',j'} = U'_{i'',j''} = U_{2,1}$. Hence, for the second sum, we have
    \begin{align*}
        \smashoperator[r]{\sum_{\substack{(i',j') \in B'^- \\ (i'',j'') \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U'_1,U'_2,<')}}} \qquad f_{U_1,U_2,<}(i',\nu(i',j')) &\le \sum_{\substack{(i',j') \in B'^- \\ (2,1) \ \text{mirrors} \ (i',\nu(i',j')) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',\nu(i',j')) \quad \text{by Lemma~\ref{lem-nu-mirror}} \\
        &= \sum_{\substack{(i',j') \in B^- \\ (2,1) \ \text{mirrors} \ (i',\nu(i',\mu(i',j'))) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',\nu(i',\mu(i',j'))) \\
        &= \sum_{\substack{(i',j') \in B^- \\ (2,1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') \quad \text{by Lemma~\ref{lem-left-inverse}}.
    \end{align*}
    By Lemma~\ref{lem-nu-plus-1}, $(i'',\nu(i'',j''))$ mirrors $(1,1)$ with respect to $(U_1,U_2,<)$. Hence,
    \begin{align*}
        f_{U'_1,U'_2,<'}(i,j) &\le 1 + \sum_{\substack{(i',j') \in B^- \setminus \{(1,1)\} \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') + \sum_{\substack{(i',j') \in B^- \\ (2,1) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') \\
        &< 1 + \sum_{\substack{(i',j') \in B^- \setminus \{(1,1)\} \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') + f_{U_1,U_2,<}(1,1) \le f_{U_1,U_2,<}(i,\nu(i,j)).
    \end{align*}

    Finally, if $(i'',j'') \in \{(i',j') \in B'^- \mid U'_{i',j'} = U_{2,1}\}$, then we similarly have
    \[
        f_{U'_1,U'_2,<'}(i,j) < 1 + \sum_{\substack{(i',j') \in B^- \\ (i'',\nu(i'',j'')) \ \text{mirrors} \ (i',j') \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i',j') + f_{U_1,U_2,<}(2,1) \le f_{U_1,U_2,<}(i,\nu(i,j)). \qedhere
    \]
\end{proof}

\begin{lemma} \label{lem-less-21}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. Then,
    \[
        \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) < f_{U_1,U_2,<}(2,1).
    \]
\end{lemma}
\begin{proof}
    First, $G_{U'_1,U'_2,<'}$ is acyclic by Lemma~\ref{lem-walk-case2}, so $f_{U'_1,U'_2,<'}$ is well-defined. Now, we have
    \begin{align*}
        \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) &\le \sum_{(i,j) \in B'^+} f_{U_1,U_2,<}(i,\nu(i,j)) \quad \text{by Lemma~\ref{lem-mu-decrease}} \\
        &= \sum_{\substack{(i,j) \in B'^+ \\ (1,1) \ \text{mirrors} \ (i,\nu(i,j)) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i,\nu(i,j)) \quad \text{by Lemma~\ref{lem-nu-plus-1}} \\
        &= \sum_{\substack{(i,j) \in B'^+ \\ (1,1) \ \text{mirrors} \ (i,\nu(i,j+1)) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i,\nu(i,j+1)) \quad \text{by Lemma~\ref{lem-nu-j-plus-1}} \\
        &\le \sum_{\substack{(i,j) \in B'^- \setminus \{(1,1),(2,1)\} \\ (1,1) \ \text{mirrors} \ (i,\nu(i,j)) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i,\nu(i,j)) \quad \text{by Lemma~\ref{lem-consec-plus}} \\
        &\le \sum_{\substack{(i,j) \in B^- \setminus \{(1,1)\} \\ (1,1) \ \text{mirrors} \ (i,\nu(i,\mu(i,j))) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i,\nu(i,\mu(i,j))) \\
        &= \sum_{\substack{(i,j) \in B^- \setminus \{(1,1)\} \\ (1,1) \ \text{mirrors} \ (i,j) \\ \text{w.r.t.} \ (U_1,U_2,<)}} f_{U_1,U_2,<}(i,j) \quad \text{by Lemma~\ref{lem-left-inverse}} \\
        &< f_{U_1,U_2,<}(2,1). \qedhere
    \end{align*}
\end{proof}

We can now prove Theorem~\ref{thm-sufficient}.

\begin{proof}[Proof of Theorem~\ref{thm-sufficient}]
    If $(U'_1,U'_2,<')$ is the result of applying a case I coherent extended Nielsen transformation to $(U_1,U_2,<)$, then we have
    \begin{align*}
        m(U'_1,U'_2,<') &= \sum_{(i,j) \in B'} f_{U'_1,U'_2,<'}(i,j) \\
        &= \sum_{(i,j) \in B \setminus \{(1,1),(2,1)\}} f_{U'_1,U'_2,<'}(i,j-1) \\
        &\le \sum_{(i,j) \in B \setminus \{(1,1),(2,1)\}} f_{U_1,U_2,<}(i,j) \quad \text{by Lemma~\ref{lem-case1}} \\
        &< \sum_{(i,j) \in B} f_{U_1,U_2,<}(i,j) = m(U_1, U_2, <).
    \end{align*}

    Otherwise, we may assume without loss of generality that $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. In this case, we have
    \begin{align*}
        m(U'_1,U'_2,<') &= \sum_{(i,j) \in B'} f_{U'_1,U'_2,<'}(i,j) \\
        &= \sum_{(i,j) \in B'^-} f_{U'_1,U'_2,<'}(i,j) + \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) \\
        &= \sum_{(i,j) \in B^-} f_{U'_1,U'_2,<'}(i,\mu(i,j)) + \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) \\
        &\le \sum_{(i,j) \in B^-} f_{U_1,U_2,<}(i,\nu(i,\mu(i,j))) + \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) \quad \text{by Lemma~\ref{lem-mu-decrease}} \\
        &= \sum_{(i,j) \in B^-} f_{U_1,U_2,<}(i,j) + \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) \quad \text{by Lemma~\ref{lem-left-inverse}} \\
        &= \sum_{(i,j) \in B} f_{U_1,U_2,<}(i,j) - f_{U_1,U_2,<}(2,1) + \sum_{(i,j) \in B'^+} f_{U'_1,U'_2,<'}(i,j) \\
        &< \sum_{(i,j) \in B} f_{U_1,U_2,<}(i,j) \quad \text{by Lemma~\ref{lem-less-21}} \\
        &= m(U_1,U_2,<).
    \end{align*}

    It remains to show that $m(U_1,U_2,<) \le 2^N$, where $N = |U_1| + |U_2|$. Consider the function $g_{U_1,U_2,<}$ recursively defined as
    \[
        g_{U_1,U_2,<}(i,j) = 1 + \sum_{\substack{(i',j') \in B \\ ((i,j),(i',j')) \in E}} g_{U_1,U_2,<}(i',j').
    \]
    Then, $f_{U_1,U_2,<}(i,j) \le g_{U_1,U_2,<}(i,j)$, so
    \[
        m(U_1,U_2,<) = \sum_{(i,j) \in B} f_{U_1,U_2,<}(i,j) \le \sum_{(i,j) \in B} g_{U_1,U_2,<}(i,j).
    \]
    But $g_{U_1,U_2,<}(i,j)$ has a graph-theoretic interpretation: it is the number of walks in $G_{U_1, U_2, <}$ starting at $(i,j)$. We therefore conclude by observing that for an acyclic graph on $N$ vertices, the total number of walks is at most $2^N$.
\end{proof}

