\begin{definition}
    The set of \emph{hereditarily staggered} extended word equations is the largest set of staggered coherent extended word equations such that
    \begin{itemize}
        \item if $(U_1, U_2, <)$ is hereditarily staggered and nontrivial, then it is possible to apply a coherent extended Nielsen transformation to $(U_1, U_2, <)$ that yields a staggered extended word equation;\footnote{This condition is perhaps less strong than it seems, because it is possible to apply a coherent extended Nielsen transformation to every nontrivial coherent extended word equation (see Proposition~\ref{prop-coherent-ext}).} and
        \item if $(U_1, U_2, <)$ is hereditarily staggered and $(U'_1, U'_2, <')$ is a staggered extended word equation obtained from $(U_1, U_2, <)$ by a coherent extended Nielsen transformation, then $(U'_1, U'_2, <')$ is hereditarily staggered.
    \end{itemize}
\end{definition}

The purpose of this section is to prove the following theorem, which is a partial converse of Theorem~\ref{thm-sufficient}.

\begin{theorem} \label{thm-necessary}
    If $(U_1,U_2,<)$ is hereditarily staggered and terminating, then $G_{U_1,U_2,<}$ is acyclic.
\end{theorem}

We prove Theorem~\ref{thm-necessary} by proving its contrapositive. That is, we start with a hereditarily staggered extended word equation $(U_1,U_2,<)$ such that $G_{U_1,U_2,<}$ is cyclic and prove that there is an infinite sequence of coherent extended Nielsen transformations that can be applied to $(U_1,U_2,<)$. Since $(U_1,U_2,<)$ is chosen arbitrarily and is hereditarily staggered, it suffices to show that it is possible to apply a coherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$ such that $G_{U'_1,U'_2,<'}$ is cyclic. We will show this by proving several lemmas.  First, given a cycle in $G_{U_1,U_2,<}$, Lemmas~\ref{lem-not-minimum} and \ref{lem-minimum} describe how to apply an extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$ such that $G_{U'_1,U'_2,<'}$ is cyclic. But an issue arises: the extended Nielsen transformations described by Lemmas~\ref{lem-not-minimum} and \ref{lem-minimum} may be incoherent. Fortunately, we have a fallback for that case. Lemma~\ref{lem-fallback} proves that if $(U'_1,U'_2,<')$ is incoherent, then it is possible to apply a coherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<'')$ such that $G_{U'_1,U'_2,<''}$ is cyclic. This argument reveals the surprising fact that incoherence is related to the presence of cycles in the cut graph (see also Proposition~\ref{prop-acyclic-coherent}).

\subsection{The incoherent case}

We start with a fact from linear algebra, which is related to Farkas' lemma. Given vectors $\mathbf{x}$ and $\mathbf{y}$, the inequality $\mathbf{x} < \mathbf{y}$ should be interpreted coordinate-wise (and similarly with $\le$ in place of $<$). We write $\mathbf{x} \lneq \mathbf{y}$ as an abbreviation for $\mathbf{x} \le \mathbf{y}$ and $\mathbf{x} \neq \mathbf{y}$.
\begin{lemma} \label{lem-alternative-z}
    Let $A$ be an $m \times n$ matrix over $\mathbb{Z}$. Exactly one of the following holds:
    \begin{enumerate}
        \item For some $\mathbf{x} \in \mathbb{Z}^n$ satisfying $\mathbf{x} > \mathbf{0}$, we have $A\mathbf{x} \le \mathbf{0}$.
        \item For some $\mathbf{y} \in \mathbb{Z}^m$ satisfying $y \ge \mathbf{0}$, we have $A^T \mathbf{y} \gneq \mathbf{0}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    This is stated with $\mathbb{R}$ in place of $\mathbb{Z}$ in \cite[p.~95]{marlow}. Since $\mathbb{Q}$ is dense in $\mathbb{R}$, the result is true over $\mathbb{Q}$ too. Clearing denominators gives the desired result.
\end{proof}

We next prove a simple variant of the previous lemma that is more suited to our purposes.

\begin{lemma} \label{lem-alternative-n}
    Let $A$ and $B$ be $m \times n$ matrices over $\mathbb{N}$. Exactly one of the following holds:
    \begin{enumerate}
        \item For some $\mathbf{x} \in \mathbb{N}^n$ satisfying $\mathbf{x} > \mathbf{0}$, we have $A\mathbf{x} \le B\mathbf{x}$.
        \item For some $\mathbf{y} \in \mathbb{N}^m$, we have $A^T \mathbf{y} \gneq B^T \mathbf{y}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Apply Lemma~\ref{lem-alternative-z} to $A-B$.
\end{proof}

Throughout the following discussion, let $(U_1, U_2, <)$ be an extended word equation, and write
 \begin{align*}
    U_1 &= U_{1,1} U_{1,2} \cdots U_{1,m} \quad\text{and} \\
    U_2 &= U_{2,1} U_{2,2} \cdots U_{2,n},
\end{align*}
where $U_{i,j} \in \mathcal{X}$ for all $i,j$. Let
\[
    \ang{i,[j,k]} = \{(i,\ell) \mid \ell \in [j,k]\}.
\]
We think of $\ang{i,[j,k]}$ as representing an interval of boundaries. Note that we may have $k<j$, in which case the interval is empty, although we assume $k \ge j-1$. Let
\[
    U_{\ang{i,[j,k]}} = \sum_{\ell=j}^k U_{i,\ell} \in \mathbb{N}[\mathcal{X}].
\]

\begin{definition}
    Given an extended word equation $(U_1, U_2, <)$, we say that $(\ang{i,[j,k]}, \break \ang{i',[j',k']})$ is a \emph{cover} if
    \begin{align*}
        i &\neq i', \\
        (i',j'-1) &\lesssim (i,j-1), \quad\text{and} \\
        (i,k) &\lesssim (i',k').
    \end{align*}
    If at least one of the above inequalities is strict, we say that $(\ang{i,[j,k]}, \ang{i',[j',k']})$ is a \emph{strict cover}. We say that a cover $(\ang{i,[j,k]}, \ang{i',[j',k']})$ is \emph{tight} if $(\ang{i,[j,k]}, \ang{i',[j'+1,k']})$ and $(\ang{i,[j,k]}, \ang{i',[j',k'-1]})$ are not covers.
\end{definition}
Based on the meaning of the boundary order, if $(\ang{i,[j,k]}, \ang{i',[j',k']})$ is a cover, then $U_{i',j'} U_{i',j'+1} \cdots U_{i',k'}$ is at least as long as $U_{i,j} U_{i,j+1} \cdots U_{i,k}$ in a hypothetical solution; if $(\ang{i,[j,k]}, \ang{i',[j',k']})$ is a strict cover, then $U_{i',j'} U_{i',j'+1} \cdots U_{i',k'}$ is longer than $U_{i,j} U_{i,j+1} \cdots U_{i,k}$ in a hypothetical solution.

Central to our argument is the notion of an \emph{incoherent core}, which isolates the parts of an incoherent extended word equation that are responsible for incoherence.

\begin{definition}
    Given an extended word equation $(U_1, U_2, <)$ and set of covers $C$, let $C' \subseteq C$ be the set of strict covers contained in $C$. An \emph{incoherent core} is a set of covers $C$ such that the following set of inequalities has no solutions over $\mathbb{Z}_{>0}$
    \[
        \{U_{A} \le U_{B} \mid (A, B) \in C\} \cup \{U_{A} < U_{B} \mid (A, B) \in C'\}.
    \]
\end{definition}

Using Lemma~\ref{lem-alternative-n}, we can give a characterization of incoherent cores.

\begin{lemma} \label{lem-incoherent-char}
    Let $C = \{(A_\ell, B_\ell) \mid \ell \in [N]\}$ be a set of covers with respect to some extended word equation $(U_1, U_2, <)$. Then, $C$ is an incoherent core if and only if for some $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$, we have
    \[
        \sum_{\ell \in [N]} y_\ell \cdot U_{B_\ell} \subseteq \sum_{\ell \in [N]} y_\ell \cdot U_{A_\ell}
    \]
    such that either the inclusion is strict or $y_\ell > 0$ for some $\ell \in [N]$ such that $(A_\ell, B_\ell)$ is a strict cover.
\end{lemma}
\begin{proof}
    Let $C' \subseteq C$ be the set of strict covers contained in $C$. Since $C$ is an incoherent core, the following set of inequalities has no solutions over $\mathbb{Z}_{>0}$
     \[
        \{U_{A} \le U_{B} \mid (A, B) \in C\} \cup \{U_{A} < U_{B} \mid (A, B) \in C'\}.
    \]
    The lemma follows by adding slack variables to the strict inequalities and appealing to Lemma~\ref{lem-alternative-n}.
\end{proof}

Our goal now is to prove Lemma~\ref{lem-disjoint-incoherent-core}, which says that any incoherent word equation has an incoherent core of a special form that will be useful for forming a cycle. We need a few lemmas on the way to this result.

\begin{lemma} \label{lem-cover-cut}
    Let $(U_1, U_2, <)$ be an extended word equation. If $(A,B)$ is a cover and $(i,j) \in A$ cuts $(i',j')$, then $(i',j') \in B$.
\end{lemma}
\begin{proof}
    Write $B = \ang{i',[\ell,k]}$. We have
    \begin{align*}
        (i',\ell-1) &\lesssim (i,j-1) < (i',j') \quad\text{and} \\
        (i',j'-1) &< (i,j) \lesssim (i',k).
    \end{align*}
    Thus, $j' \in [\ell,k]$, so $(i',j') \in B$.
\end{proof}

\begin{lemma} \label{lem-tight-cut}
    Let $(U_1, U_2, <)$ be an extended word equation. If $(A,B)$ is a tight cover, then any $(i,j) \in B$ cuts some $(i',j') \in A$.
\end{lemma}
\begin{proof}
    Write $(A,B) = (\ang{i',[\ell',k']}, \ang{i,[\ell,k]})$. Since $(A,B)$ is tight,
    \begin{align*}
        (i',\ell'-1) &< (i,\ell) \lesssim (i,j) \quad\text{and} \\
        (i,j-1) &\lesssim (i,k-1) < (i',k').
    \end{align*}
    Thus, there is some $j' \in [\ell',k']$ such that
    \begin{align*}
        (i',j'-1) &< (i,j) \quad\text{and} \\
        (i,j-1) &< (i',j'),
    \end{align*}
    so $(i,j)$ cuts $(i',j') \in A$.
\end{proof}

\begin{definition}
    Let $(A_1,B_1)$ and $(A_2,B_2)$ be covers with respect to some extended word equation. We say that $(A_1,B_1)$ \emph{impinges on} $(A_2,B_2)$ if $B_1 \cap A_2 \neq \emptyset$.
\end{definition}

\begin{lemma} \label{lem-tight}
    Suppose $(A_1,B_1)$ and $(A_2,B_2)$ are covers and $(A_1,B_1)$ is tight with respect to some extended word equation. If $(A_1,B_1)$ impinges on $(A_2,B_2)$, then $(A_2,B_2)$ impinges on $(A_1,B_1)$.
\end{lemma}
\begin{proof}
    Suppose $(A_1,B_1)$ impinges on $(A_2,B_2)$. Then, for some boundary $(i,j)$, we have $(i,j) \in B_1 \cap A_2$. Since $(A_1,B_1)$ is tight, $(i,j)$ cuts some $(i',j') \in A_1$ by Lemma~\ref{lem-tight-cut}. By Lemma~\ref{lem-cover-cut}, $(i',j') \in B_2$. Thus, $(i',j') \in B_2 \cap A_1$, so $(A_2,B_2)$ impinges on $(A_1,B_1)$.
\end{proof}

\begin{lemma} \label{lem-disjoint-incoherent-core}
    If $(U_1, U_2, <)$ is incoherent, then there is an incoherent core such that no cover impinges on another.
\end{lemma}
\begin{proof}
    First, we observe that there is an incoherent core, namely
    \[
        \{(\ang{i, [1,j]}, \ang{i', [1,j']}) \mid (i,j) \lesssim (i',j')\}.
    \]

    Now, let $C = \{(A_\ell, B_\ell) \mid \ell \in [N]\}$ be an incoherent core. By Lemma~\ref{lem-incoherent-char}, for some $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$, we have
    \begin{equation} \label{subset-1}
        \sum_{\ell \in [N]} y_\ell \cdot U_{B_\ell} \subseteq \sum_{\ell \in [N]} y_\ell \cdot U_{A_\ell}\quad ,
    \end{equation}
    such that either the inclusion is strict or $y_\ell > 0$ for some $\ell \in [N]$ such that $(A_\ell, B_\ell)$ is a strict cover. We may choose $C$ and the coefficients $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$ so that $y_\ell > 0$ for all $\ell \in [N]$ and
    \begin{equation} \label{minimizer-1}
        \sum_{\ell \in [N]} y_\ell \cdot (|A_\ell| + |B_\ell|)
    \end{equation}
    is minimal. It follows that all the covers in $C$ are tight.

    We claim that no cover of $C$ impinges on another. For the sake of contradiction, suppose otherwise. Without loss of generality, $B_1 \cap A_2 \neq \emptyset$. By Lemma~\ref{lem-tight}, we have $B_2 \cap A_1 \neq \emptyset$ too. We will contradict our assumption that \eqref{minimizer-1} is minimal.

    Write
    \begin{align*}
        A_1 &= \ang{i, [j_1,k_1]} \\
        B_1 &= \ang{i', [j_2,k_2]} \\
        A_2 &= \ang{i', [j_3,k_3]} \\
        B_2 &= \ang{i, [j_4,k_4]}.
    \end{align*}
    Without loss of generality, $j_1 \le j_4$. Let
    \begin{align*}
        A'_1 &= \ang{i, [j_1,j_4 - 1]} \\
        B'_1 &= \ang{i', [j_2,j_3 - 1]}.
    \end{align*}
    If $k_1 \le k_4$, let
    \begin{align*}
        A'_2 &= \ang{i', [k_2 + 1,k_3]} \\
        B'_2 &= \ang{i, [k_1 + 1,k_4]}.
    \end{align*}
    On the other hand, if $k_1 > k_4$, let
    \begin{align*}
        A'_2 &= \ang{i, [k_4+1,k_1]} \\
        B'_2 &= \ang{i', [k_3+1,k_2]}.
    \end{align*}
    In either case, $(A'_1,B'_1)$ and $(A'_2,B'_2)$ are covers.

    If $k_1 \le k_4$, we have
    \[
        U_{A_1} + U_{A_2} + U_{B'_1} + U_{B'_2} = U_{\ang{i,[j_1,k_4]}} + U_{\ang{i',[j_2,k_3]}} = U_{B_1} + U_{B_2} + U_{A'_1} + U_{A'_2}.
    \]
    Similarly, if $k_1 > k_4$, we have
    \[
        U_{A_1} + U_{A_2} + U_{B'_1} + U_{B'_2} = U_{\ang{i,[j_1,k_1]}} + U_{\ang{i',[j_2,k_2]}} = U_{B_1} + U_{B_2} + U_{A'_1} + U_{A'_2}.
    \]
    Hence,
    \[
        U_{A_1} + U_{A_2} + U_{B'_1} + U_{B'_2} + \sum_{\ell \in [N]} y_\ell \cdot U_{B_\ell} \subseteq U_{B_1} + U_{B_2} + U_{A'_1} + U_{A'_2} + \sum_{\ell \in [N]} y_\ell \cdot U_{A_\ell}.
    \]
    Canceling terms, we get
    \begin{equation} \label{subset-2}
    \begin{split}
        &U_{B'_1} + U_{B'_2} + (y_1 - 1) \cdot U_{B_1} + (y_2 - 1) \cdot U_{B_2} + \sum_{\ell \in [3,N]} y_\ell \cdot U_{B_\ell} \subseteq \\
        &U_{A'_1} + U_{A'_2} + (y_1 - 1) \cdot U_{A_1} + (y_2 - 1) \cdot U_{A_2} + \sum_{\ell \in [3,N]} y_\ell \cdot U_{A_\ell}.
    \end{split}
    \end{equation}
    If the inclusion \eqref{subset-1} is strict, then so is \eqref{subset-2}. If either $(A_1,B_1)$ or $(A_2,B_2)$ is a strict cover, then at least one of $(A'_1,B'_1)$ and $(A'_2,B'_2)$ is a strict cover. Thus, \eqref{subset-2} satisfies the condition from Lemma~\ref{lem-incoherent-char}.

    We claim
    \begin{align*}
        |A'_1| &< |A_1| \\
        |B'_1| &< |B_1|.
    \end{align*}
    Indeed, since $B_2 \cap A_1 \neq \emptyset$, we have $j_4 \le k_1$, so $|A'_1| < |A_1|$. And since $B_1 \cap A_2 \neq \emptyset$, we have $j_3 \le k_2$, so $|B'_1| < |B_1|$. We can similarly show that if $k_1 \le k_4$, then
    \begin{align*}
        |A'_2| &< |A_2| \\
        |B'_2| &< |B_2|,
    \end{align*}
    and if $k_1 > k_4$, then
    \begin{align*}
        |A'_1| + |A'_2| &< |A_1| \\
        |B'_1| + |B'_2| &< |B_1|.
    \end{align*}
    Hence,
    \[
        |A'_1| + |B'_1| + |A'_2| + |B'_2| < |A_1| + |B_1| + |A_2| + |B_2|.
    \]
    This inequality together with the inclusion \eqref{subset-2} contradicts our assumption that \eqref{minimizer-1} is minimal.
\end{proof}

Let $(U_1,U_2,<)$ be a staggered coherent extended word equation, and assume without loss of generality that $(1,1) > (2,1)$. Let $(U'_1,U'_2,<')$ be an extended word equation obtained from $(U_1,U_2,<)$ by an extended Nielsen transformation, and let $B'^+$ be defined as in Section~\ref{sec-ext-nielsen}. If $(i,j) \in B'^+$ with $(i,j)$ adjacent to $(3-i,j')$ with respect to $<'$ for some $j'$, then we have an extended word equation $(U'_1,U'_2,<'')$, where $<''$ is obtained by swapping the order of $(i,j)$ and $(3-i,j')$ in $<'$. We say that $(U'_1,U'_2,<'')$ is a \emph{swap} of $(U'_1,U'_2,<')$.

Given any two staggered extended word equations $(U'_1,U'_2,<')$ and $(U'_1,U'_2,<'')$ obtained from a staggered coherent extended word equation $(U_1,U_2,<)$ by an extended Nielsen transformation, we can reach one from the other by a sequence of swaps. This is because an extended Nielsen transformation is determined by the choice of how to order each boundary $(i,j) \in B'^+$ relative to every boundary of the form $(3-i,j') \in B'$.

\begin{lemma} \label{lem-fallback}
    Let $(U_1,U_2,<)$ be a hereditarily staggered extended word equation. Suppose it is possible to apply an incoherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$. Then, it is possible to apply a coherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<'')$ such that $G_{U'_1,U'_2,<''}$ is cyclic.
\end{lemma}
\begin{proof}
    By the assumptions of the lemma, $(U_1,U_2,<)$ is nontrivial, so it is possible to apply a coherent extended Nielsen transformation to $(U_1, U_2, <)$ that yields a staggered extended word equation $(U'_1,U'_2,<'')$. For any choice of $(U'_1,U'_2,<')$ and $(U'_1,U'_2,<'')$, we can reach the latter from the former by a sequence of swaps, at least one of which must go from an incoherent extended word equation to a coherent one. Thus, we may choose $(U'_1,U'_2,<')$ and $(U'_1,U'_2,<'')$ so that each is a swap of the other. Let $B'^+$ be defined as in Section~\ref{sec-ext-nielsen}. Then, for some $(i,j) \in B'^+$ and $j'$, the boundary order $<''$ is obtained by swapping the order of adjacent elements $(i,j)$ and $(3-i,j')$ in $<'$. We claim that $G_{U'_1,U'_2,<''}$ is cyclic.

    By Lemma~\ref{lem-disjoint-incoherent-core}, $(U'_1,U'_2,<')$ has an incoherent core $C = \{(A_\ell, B_\ell) \mid \ell \in [N]\}$ such that no cover impinges on another. By Lemma~\ref{lem-incoherent-char}, there are some $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$ such that
    \begin{equation} \label{subset-3}
        \sum_{\ell \in [N]} y_\ell \cdot U'_{B_\ell} \subseteq \sum_{\ell \in [N]} y_\ell \cdot U'_{A_\ell}.
    \end{equation}
    By Lemma~\ref{lem-cover-cut}, for any $\ell \in [N]$, if $(i_1,j_1) \in A_\ell$ cuts some $(i'_1,j'_1)$ with respect to $(U'_1,U'_2,<')$, then $(i'_1,j'_1) \in B_\ell$. We first claim that for any $\ell \in [N]$, every $(i_1,j_1) \in A_\ell$ cuts some $(i'_1,j'_1) \in B_\ell$ with respect to $(U'_1,U'_2,<'')$. Since $(U'_1,U'_2,<')$ and $(U'_1,U'_2,<'')$ are swaps of each other, this follows immediately from the previous assertion unless $(i_1,j_1) \in \{(i,j),(i,j+1),(3-i,j'),(3-i,j'+1)\}$. Since $(i,j)$ and $(3-i,j')$ are adjacent with respect to both $<'$ and $<''$, we have
    \begin{align*}
        (i,j-1) &<' (3-i,j') \\
        (3-i,j'-1) &<' (i,j),
    \end{align*}
    and similarly with $<''$ in place of $<'$. Thus, if $(i_1,j_1) = (i,j)$, then $(i_1,j_1)$ cuts $(3-i,j')$ with respect to both $(U'_1,U'_2,<')$ and $(U'_1,U'_2,<'')$. In particular, $(3-i,j') \in B_\ell$ by Lemma~\ref{lem-cover-cut}, which proves the claim when $(i_1,j_1) = (i,j)$. The remaining three cases can be handled similarly.

    Next, we claim that for any $\ell \in [N]$, every $(i'_1,j'_1) \in B_\ell$ mirrors some $(i_2,j_2) \in A_{\ell'}$ with respect to $(U'_1,U'_2,<'')$ for some $\ell' \in [N]$. Let $(i'_1,j'_1) \in B_\ell$. By the inclusion \eqref{subset-3}, there is some $(i_2,j_2) \in A_{\ell'}$ with $U'_{i'_1,j'_1} = U'_{i_2,j_2}$. Since no cover of $C$ impinges on another, $(i'_1,j'_1) \neq (i_2,j_2)$. And since $(U'_1,U'_2,<'')$ is staggered and coherent, $(i'_1,j'_1) \not\approx'' (i_2,j_2)$. Hence, $(i'_1,j'_1)$ mirrors $(i_2,j_2)$ with respect to $(U'_1,U'_2,<'')$.

    Therefore, for any $(i_1,j_1) \in A_\ell$, there is some $(i_2,j_2) \in A_{\ell'}$ such that $((i_1,j_1), (i_2,j_2)) \in E''$, where $G_{U'_1,U'_2,<''} = (B',E'')$. Hence, we have an infinite walk in $G_{U'_1,U'_2,<''}$. It follows that $G_{U'_1,U'_2,<''}$ is cyclic.
\end{proof}

\subsection{The coherent case}

In light of Lemma~\ref{lem-fallback}, we can now ignore coherence issues. Given a hereditarily staggered extended word equation $(U_1,U_2,<)$ such that $G_{U_1,U_2,<}$ is cyclic, we now aim to describe how to apply an extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$ such that $G_{U'_1,U'_2,<'}$ is cyclic.

\begin{definition}
    Given an extended word equation $(U_1,U_2,<)$ and a cycle
    \[
        C = ((i_1,j_1), (i_2,j_2), \dots, (i_{n-1},j_{n-1}), (i_1,j_1))
    \]
    in $G_{U_1,U_2,<}$, there is a set of boundaries
    \[
        S = \left\{(i_1,j_1), (i'_1,j'_1), (i_2,j_2), (i'_2,j'_2), \dots, (i_{n-1},j_{n-1}), (i'_{n-1},j'_{n-1})\right\}
    \]
    such that for each $k \in [n-1]$, we have $(i_k,j_k)$ cuts $(i'_k,j'_k)$ and $(i'_k,j'_k)$ mirrors $(i_{k+1},j_{k+1})$ (where $(i_n,j_n) = (i_1,j_1)$). We say that $S$ is an \emph{auxiliary set of $C$}. We say that $C$ is \emph{pointed with respect to $S$} if the boundary $(i_1,j_1)$ is a minimal element of $S$ with respect to $<$.
\end{definition}

\begin{lemma} \label{lem-pointed}
    If $G_{U_1,U_2,<}$ is cyclic, then there is some cycle of minimum length in $G_{U_1,U_2,<}$ that is pointed with respect to some auxiliary set.
\end{lemma}
\begin{proof}
    Let
    \[
        C = ((i_1,j_1), (i_2,j_2), \dots, (i_{n-1},j_{n-1}), (i_1,j_1))
    \]
    be a cycle of minimum length in $G_{U_1,U_2,<}$, and let
    \[
        S = \left\{(i_1,j_1), (i'_1,j'_1), (i_2,j_2), (i'_2,j'_2), \dots, (i_{n-1},j_{n-1}), (i'_{n-1},j'_{n-1})\right\}
    \]
    be an auxiliary set of $C$, where for each $k \in [n-1]$, we have $(i_k,j_k)$ cuts $(i'_k,j'_k)$ and $(i'_k,j'_k)$ mirrors $(i_{k+1},j_{k+1})$ (where $(i_n,j_n) = (i_1,j_1)$). If $(i_k,j_k)$ is a minimal element of $S$ with respect to $<$ for some $k \in [n-1]$, then we have the cycle
    \[
        ((i_k,j_k), (i_{k+1},j_{k+1}), \dots, (i_{n-1},j_{n-1}), (i_1,j_1), \dots, (i_{k-1},j_{k-1}), (i_k,j_k)),
    \]
    which is of minimum length in $G_{U_1,U_2,<}$ and pointed with respect to $S$. If $(i'_k,j'_k)$ is a minimal element of $S$ with respect to $<$ for some $k \in [n-1]$, then we have the cycle
    \[
        \left((i'_k,j'_k), (i'_{k-1},j'_{k-1}), \dots, (i'_1,j'_1), (i'_{n-1},j'_{n-1}), \dots, (i'_{k+1},j'_{k+1}), (i'_k,j'_k)\right),
    \]
    which is of minimum length in $G_{U_1,U_2,<}$ and pointed with respect to $S$.
\end{proof}

Throughout the remainder of this section, if $(U_1,U_2,<)$ and $(U'_1,U'_2,<')$ are extended word equations, let their boundaries be $B$ and $B'$ respectively. If $(U'_1,U'_2,<')$ is the result of applying a case II extended Nielsen transformation to $(U_1,U_2,<)$, let $\mu$, $\nu$, $B^-$, $B'^-$, and $B'^+$ be defined as in Section~\ref{sec-ext-nielsen}.

\begin{lemma} \label{lem-mu-order}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j),(i',j') \in B$ and $(i,j) < (i',j')$, then \break $(i,\mu(i,j)) <' (i',\mu(i',j'))$.
\end{lemma}
\begin{proof}
    If $(i,j),(i',j') \in B^-$, then by Lemma~\ref{lem-left-inverse}, $(i,\nu(i,\mu(i,j))) < (i',\nu(i',\mu(i',j')))$, which implies $(i,\mu(i,j)) <' (i',\mu(i',j'))$. Otherwise, $(i,j) = (2,1)$ and $(i',j') \in B^-$, in which case $(i,\mu(i,j)) = (i,0) <' (i',\mu(i',j'))$.
\end{proof}

\begin{lemma} \label{lem-mu-minus-1-order}
    Suppose $(U'_1,U'_2,<')$ is a staggered extended word equation resulting from applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. Let $(i,j), (i',j') \in B^-$, and assume that if $(i,\mu(i,j)-1) \in B'^+$, then $(i,\mu(i,j)-2) \lessdot' (i,\mu(i,j)-1)$. Then, if $(i,j-1) < (i', j')$, we have $(i,\mu(i,j)-1) <' (i',\mu(i',j'))$.
\end{lemma}
\begin{proof}
    Suppose $(i,j-1) < (i', j')$. If $j = 1$, then $(i,j) = (1,1)$, so $(i,\mu(i,j)-1) = (i,0) <' (i',\mu(i',j'))$. Otherwise, $(i,\mu(i,j-1)) <' (i',\mu(i',j'))$ by Lemma~\ref{lem-mu-order}. If $(i,\mu(i,j)-1) \in B'^-$, then $\mu(i,j-1) = \mu(i,j)-1$, so $(i,\mu(i,j)-1) <' (i',\mu(i',j'))$. If $(i,\mu(i,j)-1) \in B'^+$, then $\mu(i,j-1) = \mu(i,j)-2$. Hence, $(i,\mu(i,j-1)) \lessdot' (i,\mu(i,j)-1)$, so $(i,\mu(i,j)-1) <' (i',\mu(i',j'))$ in this case too. Finally, if $(i,\mu(i,j)-1) \notin B'^- \cup B'^+ = B'$, then $\mu(i,j) = 1$, so $(i,\mu(i,j)-1) = (i,0) <' (i',\mu(i',j'))$. In any case, $(i,\mu(i,j)-1) <' (i',\mu(i',j'))$.
\end{proof}

\begin{lemma} \label{lem-mu-mirror}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $(i,j), (i',j') \in B^-$ and $(i,j)$ mirrors $(i',j')$ with respect to $(U_1,U_2,<)$, then $(i,\mu(i,j))$ mirrors $(i',\mu(i',j'))$ with respect to $(U'_1,U'_2,<')$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ mirrors $(i',j')$ with respect to $(U_1,U_2,<)$. Then, $U_{i,j} = U_{i', j'}$ and $(i,j) \not\approx (i', j')$. By Lemmas~\ref{lem-mu-preserve} and \ref{lem-mu-order}, $U'_{i,\mu(i,j)} = U'_{i',\mu(i',j')}$ and $(i,\mu(i,j)) \not\approx' (i', \mu(i', j'))$, so $(i,\mu(i,j))$ mirrors $(i',\mu(i',j'))$ with respect to $(U'_1,U'_2,<')$.
\end{proof}

\begin{lemma} \label{lem-not-minimum}
    Let $(U_1,U_2,<)$ be a hereditarily staggered extended word equation. Suppose $G_{U_1,U_2,<}$ contains a cycle
    \[
        C = ((i_1,j_1), (i_2,j_2), \dots, (i_{n-1},j_{n-1}), (i_1,j_1))
    \]
    that is pointed with respect to some auxiliary set. If $(i_1,j_1)$ is not the minimum boundary of $B$, then it is possible to apply a coherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$ such that $G_{U'_1,U'_2,<'}$ is cyclic.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem-fallback}, we may assume that every extended Nielsen transformation applied to $(U_1,U_2,<)$ yielding a staggered extended word equation is in fact a coherent extended Nielsen transformation.

    Without loss of generality, assume that $(1,1) > (2,1)$. Let $(U'_1,U'_2,<')$ be the unique staggered extended word equation resulting from applying a case II extended Nielsen transformation to $(U_1,U_2,<)$ such that for each $(i,j) \in B'^+$, we have $(i,j-1) \lessdot' (i,j)$.

    The cycle $C$ is pointed with respect to some auxiliary set
    \[
        S = \left\{(i_1,j_1), (i'_1,j'_1), (i_2,j_2), (i'_2,j'_2), \dots, (i_{n-1},j_{n-1}), (i'_{n-1},j'_{n-1})\right\},
    \]
    where for each $k \in [n-1]$, we have $(i_k,j_k)$ cuts $(i'_k,j'_k)$ and $(i'_k,j'_k)$ mirrors $(i_{k+1},j_{k+1})$ with respect to $(U_1,U_2,<)$ (where $(i_n,j_n) = (i_1,j_1)$). Since $(i_1,j_1) \in B^-$ and $C$ is pointed with respect to $S$, we have $(i_k,j_k), (i'_k,j'_k) \in B^-$ for each $k \in [n-1]$. It follows that $(i_k,\mu(i_k,j_k)), (i'_k,\mu(i'_k,j'_k)) \in B'$ for each $k \in [n-1]$. We claim that
    \[
        C' = ((i_1,\mu(i_1,j_1)), (i_2,\mu(i_2,j_2)), \dots, (i_{n-1},\mu(i_{n-1},j_{n-1})), (i_1,\mu(i_1,j_1)))
    \]
    is a cycle in $G_{U'_1,U'_2,<'}$.

    First, we show that for each $k \in [n-1]$, we have $(i_k,\mu(i_k,j_k))$ cuts $(i'_k,\mu(i'_k,j'_k))$ with respect to $(U'_1,U'_2,<')$. Since $(i_k,j_k)$ cuts $(i'_k,j'_k)$ with respect to $(U_1,U_2,<)$, we have $(i_k,j_k-1) < (i'_k, j'_k)$ and $(i'_k,j'_k-1) < (i_k,j_k)$. Hence, by Lemma~\ref{lem-mu-minus-1-order}, we have $(i_k,\mu(i_k,j_k)-1) <' (i'_k,\mu(i'_k,j'_k))$ and $(i'_k,\mu(i'_k,j'_k)-1) <' (i_k, \mu(i_k,j_k))$. Therefore, $(i_k,\mu(i_k,j_k))$ cuts $(i'_k,\mu(i'_k,j'_k))$ with respect to $(U'_1,U'_2,<')$.

    Next, for each $k \in [n-1]$, we have $(i'_k,\mu(i'_k,j'_k))$ mirrors $(i_{k+1},\mu(i_{k+1},j_{k+1}))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-mirror}. Therefore, $C'$ is a cycle in $G_{U'_1,U'_2,<'}$.
\end{proof}

\begin{lemma} \label{lem-mu-minus-1-cut}
    Suppose $(U'_1,U'_2,<')$ is a staggered extended word equation resulting from applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. Let $(i,j), (i',j') \in B^-$. Assume that $(i,\mu(i,j)-1) \in B'^+$, $(i,\mu(i,j)-1) \lessdot' (i,\mu(i,j))$, and that if $(i',\mu(i',j')-1) \in B'^+$, then $(i',\mu(i',j')-2) \lessdot' (i',\mu(i',j')-1)$. Then, if $(i,j)$ cuts $(i',j')$ with respect to $(U_1,U_2,<)$, we have $(i,\mu(i,j)-1)$ cuts $(i',\mu(i',j'))$ with respect to $(U'_1,U'_2,<')$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ cuts $(i',j')$ with respect to $(U_1,U_2,<)$. Then, $(i,j - 1) < (i',j')$. We have $j \neq 1$, so by Lemma~\ref{lem-mu-order}, $(i,\mu(i,j - 1)) <' (i',\mu(i',j'))$. Since $(i,\mu(i,j)-1) \in B'^+$, we have $\mu(i,j - 1) = \mu(i,j)-2$, so $(i,\mu(i,j)-2) <' (i',\mu(i',j'))$. By Lemma~\ref{lem-mu-minus-1-order}, we have $(i',\mu(i',j') - 1) <' (i,\mu(i,j))$. Together with the assumption that $(i,\mu(i,j)-1) \lessdot' (i,\mu(i,j))$, this implies $(i',\mu(i',j') - 1) <' (i,\mu(i,j)-1)$. Therefore, $(i,\mu(i,j)-1)$ cuts $(i',\mu(i',j'))$ with respect to $(U'_1,U'_2,<')$.
\end{proof}

\begin{lemma} \label{lem-mu-minus-1-mirror}
    Suppose $(U'_1,U'_2,<')$ is a staggered extended word equation resulting from applying a case II coherent extended Nielsen transformation to $(U_1,U_2,<)$. Let $(i,j),(i',j') \in B^-$, and assume that $(i',\mu(i',j')-1) \in B'^+$. Then, if $(i,j)$ mirrors $(2,1)$ with respect to $(U_1,U_2,<)$, we have $(i,\mu(i,j))$ mirrors $(i',\mu(i',j')-1)$ with respect to $(U'_1,U'_2,<')$.
\end{lemma}
\begin{proof}
    Suppose $(i,j)$ mirrors $(2,1)$ with respect to $(U_1,U_2,<)$. Then, $U_{i,j} = U_{2,1}$. By Lemmas~\ref{lem-mu-preserve} and \ref{lem-nu-plus-2},
    \[
        U'_{i,\mu(i, j)} = U_{i,j} = U_{2,1} = U'_{i',\mu(i',j')-1}.
    \]
    Since $(U'_1,U'_2,<')$ is staggered, $(i,\mu(i, j)) \not\approx' (i',\mu(i',j')-1)$. Therefore, $(i,\mu(i, j))$ mirrors $(i',\mu(i',j')-1)$ with respect to $(U'_1,U'_2,<')$.
\end{proof}

\begin{lemma} \label{lem-minimum}
    Let $(U_1,U_2,<)$ be a hereditarily staggered extended word equation. Suppose $G_{U_1,U_2,<}$ contains a cycle
    \[
        C = ((i_1,j_1), (i_2,j_2), \dots, (i_{n-1},j_{n-1}), (i_1,j_1))
    \]
    that is pointed with respect to some auxiliary set. If $(i_1,j_1)$ is the minimum boundary of $B$, then it is possible to apply a coherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$ such that $G_{U'_1,U'_2,<'}$ is cyclic.
\end{lemma}
\begin{proof}
    By Lemma~\ref{lem-fallback}, we may assume that every extended Nielsen transformation applied to $(U_1,U_2,<)$ yielding a staggered extended word equation is in fact a coherent extended Nielsen transformation.

    The cycle $C$ is pointed with respect to some auxiliary set
    \[
        S = \left\{(i_1,j_1), (i'_1,j'_1), (i_2,j_2), (i'_2,j'_2), \dots, (i_{n-1},j_{n-1}), (i'_{n-1},j'_{n-1})\right\},
    \]
    where for each $k \in [n-1]$, we have $(i_k,j_k)$ cuts $(i'_k,j'_k)$ and $(i'_k,j'_k)$ mirrors $(i_{k+1},j_{k+1})$ (where $(i_n,j_n) = (i_1,j_1)$). Without loss of generality, assume that $(1,1) > (2,1)$. Then, $(i_1,j_1) = (2,1)$ and $(i'_1,j'_1) = (1,1)$. Since $(i'_1,j'_1)$ mirrors $(i_2,j_2)$, we have $U_{i_2,j_2} = U_{1,1}$. Thus, in any case II extended Nielsen transformation of $(U_1,U_2,<)$, we have $(i_2,\mu(i_2,j_2)-1) \in B'^+$.

    We may assume that $C$ is a cycle of minimum length in $G_{U_1,U_2,<}$. Indeed, by Lemma~\ref{lem-pointed}, $G_{U_1,U_2,<}$ has a cycle of minimum length that is pointed with respect to some auxiliary set; this cycle either satisfies the conditions of Lemma~\ref{lem-not-minimum}, in which case we are done, or it satisfies the conditions of the current lemma. From this assumption, it follows that $(i_k,j_k) \neq (i_\ell,j_\ell)$ and $(i'_k,j'_k) \neq (i'_\ell,j'_\ell)$ for all $k,\ell \in [n-1]$ such that $k \neq \ell$.

    It also follows that if $U_{i'_k,j'_k} = U_{1,1}$ for some $k \in [n-1]$, then $(i'_k,j'_k) \in \{(1,1), (i_2,j_2)\}$. Indeed, if $U_{i'_k,j'_k} = U_{1,1}$ for some $(i'_k,j'_k) \notin \{(1,1), (i_2,j_2)\}$, then we have the shorter cycle
    \[
        ((i_2,j_2), (i_3,j_3), \dots, (i_k,j_k), (i_2,j_2)).
    \]

    We may also assume that if $(i'_k,j'_k) = (i_2,j_2)$ for some $k \in [n-1]$, then $(i'_2,j'_2) \lesssim (i_k, j_k)$. Indeed, if $(i_k, j_k) < (i'_2,j'_2)$, then we may instead consider the cycle
    \[
        \left((i_1,j_1), (i_2,j_2), (i'_{k-1},j'_{k-1}), (i'_{k-2},j'_{k-2}), \dots, (i'_2,j'_2), (i_{k+1},j_{k+1}), \dots, (i_{n-1},j_{n-1}), (i_1,j_1)\right),
    \]
    in which the roles of $(i_k, j_k)$ and $(i'_2,j'_2)$ are reversed.

    At this point in the proof, we split into cases.

    \textbf{Case 1:} $(i'_k,j'_k) \neq (i_2,j_2)$ for all $k \in [n-1]$. Let $(U'_1,U'_2,<')$ be the unique staggered extended word equation resulting from applying a case II extended Nielsen transformation to $(U_1,U_2,<)$ such that $(i_2,\mu(i_2,j_2)-1) \lessdot' (i_2,\mu(i_2,j_2))$ and $(i,j-1) \lessdot' (i,j)$ for each $(i,j) \in B'^+ \setminus \{(i_2,\mu(i_2,j_2)-1)\}$.

    We claim $(i'_k,j'_k) \neq (2,1)$ for all $k \in [n-1]$. Indeed, if $(i'_k,j'_k) = (2,1)$, then $(i_k,j_k) = (1,1)$. It follows that $(i'_{k-1}, j'_{k-1}) \neq (1,1)$ and $U_{i'_{k-1}, j'_{k-1}} = U_{1,1}$. Hence, $(i'_{k-1}, j'_{k-1}) = (i_2,j_2)$, a contradiction. It follows from this claim that $(i_k,\mu(i_k,j_k)), (i'_k,\mu(i'_k,j'_k)) \in B'$ for each $k \in [2,n-1]$.

    We claim that
    \[
        C' = ((i_2,\mu(i_2,j_2)-1), (i_3,\mu(i_3,j_3)), \dots, (i_{n-1},\mu(i_{n-1},j_{n-1})), (i_2,\mu(i_2,j_2)-1))
    \]
    is a cycle in $G_{U'_1,U'_2,<'}$.

    We have $(i_2,\mu(i_2,j_2)-1)$ cuts $(i'_2,\mu(i'_2,j'_2))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-minus-1-cut}. Also, $(i'_{n-1},\mu(i'_{n-1}, j'_{n-1}))$ mirrors $(i_2,\mu(i_2,j_2)-1)$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-minus-1-mirror}. For each $k \in [3,n-1]$, we have $(i_k,\mu(i_k,j_k))$ cuts $(i'_k,\mu(i'_k,j'_k))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-minus-1-order}. For each $k \in [2,n-2]$, we have $(i'_k,\mu(i'_k,j'_k))$ mirrors $(i_{k+1},\mu(i_{k+1},j_{k+1}))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-mirror}. Therefore, $C'$ is a cycle in $G_{U'_1,U'_2,<'}$.

    \textbf{Case 2:} $(i'_k,j'_k) = (2,1)$ for some $k \in [n-1]$. Let $(U'_1,U'_2,<')$ be as in Case 1.

    Let $k \in [n-1]$ be such that $(i'_k,j'_k) = (2,1)$. Then, $(i_k,j_k) = (1,1)$, so $(i'_{k-1}, j'_{k-1}) \neq (1,1)$ and $U_{i'_{k-1}, j'_{k-1}} = U_{1,1}$. Hence, $(i'_{k-1}, j'_{k-1}) = (i_2,j_2)$.

    We claim that
    \begin{align*}
        C' = &((i_2,\mu(i_2,j_2)-1), (i_3,\mu(i_3,j_3)), \dots, (i_{k-1},\mu(i_{k-1},j_{k-1})), \\
        &(i_{k+1},\mu(i_{k+1},j_{k+1})), \dots, (i_{n-1},\mu(i_{n-1},j_{n-1})), (i_2,\mu(i_2,j_2)-1))
    \end{align*}
    is a cycle in $G_{U'_1,U'_2,<'}$.

    By Lemma~\ref{lem-mu-minus-1-cut}, we have $(i_2,\mu(i_2,j_2)-1)$ cuts $(i'_2,\mu(i'_2,j'_2))$ and $(i_{k-1},\mu(i_{k-1},j_{k-1}))$ cuts $(i_2,\mu(i_2,j_2)-1)$, both with respect to $(U'_1,U'_2,<')$. By Lemma~\ref{lem-mu-minus-1-mirror}, $(i_2,\mu(i_2,j_2)-1)$ mirrors $(i_{k+1},\mu(i_{k+1},j_{k+1}))$ and $(i'_{n-1},\mu(i'_{n-1}, j'_{n-1}))$ mirrors $(i_2,\mu(i_2,j_2)-1)$, both with respect to $(U'_1,U'_2,<')$. For each $\ell \in [3,k-2] \cup [k+1,n-1]$, we have $(i_\ell,\mu(i_\ell,j_\ell))$ cuts $(i'_\ell,\mu(i'_\ell,j'_\ell))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-minus-1-order}. For each $\ell \in [2,k-2] \cup [k+1,n-2]$, we have $(i'_\ell,\mu(i'_\ell,j'_\ell))$ mirrors $(i_{\ell+1},\mu(i_{\ell+1},j_{\ell+1}))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-mirror}. Therefore, $C'$ is a cycle in $G_{U'_1,U'_2,<'}$.

    \textbf{Case 3:} $(i'_k,j'_k) = (i_2,j_2)$ for some $k \in [n-1]$ and $(i'_k,j'_k) \neq (2,1)$ for all $k \in [n-1]$. We first show that if $(U'_1,U'_2,<')$ is a case II extended Nielsen transformation of $(U_1,U_2,<)$, then $(i_2,\mu(i_2,j_2)-2) <' (i'_2,\mu(i'_2,j'_2))$ and $(i'_2,\mu(i'_2,j'_2) - 1) <' (i_2,\mu(i_2,j_2))$. Since $(i_2,j_2)$ cuts $(i'_2,j'_2)$ with respect to $(U_1,U_2,<)$, we have $(i_2,j_2 - 1) < (i'_2,j'_2)$ and $(i'_2,j'_2 - 1) < (i_2,j_2)$. We have $j_2,j'_2 \neq 1$ (we have $(i'_2,j'_2) \neq (1,1)$, since $C$ is of minimum length), so by Lemma~\ref{lem-mu-order}, $(i_2,\mu(i_2,j_2 - 1)) <' (i'_2,\mu(i'_2,j'_2))$ and $(i'_2,\mu(i'_2,j'_2 - 1)) <' (i_2,\mu(i_2,j_2))$. Since $(i_2,\mu(i_2,j_2)-1) \in B'^+$, we have $\mu(i_2,j_2 - 1) = \mu(i_2,j_2)-2$. We have $U_{i'_2,j'_2} \neq U_{1,1}$, so $\mu(i'_2,j'_2 - 1) = \mu(i'_2,j'_2) - 1$. Therefore, $(i_2,\mu(i_2,j_2)-2) <' (i'_2,\mu(i'_2,j'_2))$ and $(i'_2,\mu(i'_2,j'_2) - 1) <' (i_2,\mu(i_2,j_2))$.

    In light of the previous paragraph, we can let $(U'_1,U'_2,<')$ be the unique staggered extended word equation resulting from applying a case II extended Nielsen transformation to $(U_1,U_2,<)$ such that $(i'_2,\mu(i'_2,j'_2)-1) <' (i_2,\mu(i_2,j_2) - 1) <' (i'_2,\mu(i'_2,j'_2))$ and $(i,j-1) \lessdot' (i,j)$ for each $(i,j) \in B'^+ \setminus \{(i_2,\mu(i_2,j_2)-1)\}$.

    We claim that
    \[
        C' = ((i_2,\mu(i_2,j_2)-1), (i_3,\mu(i_3,j_3)), \dots, (i_{n-1},\mu(i_{n-1},j_{n-1})), (i_2,\mu(i_2,j_2)-1))
    \]
    is a cycle in $G_{U'_1,U'_2,<'}$.

    First, we show that $(i_2,\mu(i_2,j_2)-1)$ cuts $(i'_2,\mu(i'_2,j'_2))$ with respect to $(U'_1,U'_2,<')$. Above, we showed that $(i_2,\mu(i_2,j_2)-2) <' (i'_2,\mu(i'_2,j'_2))$, and we have $(i'_2,\mu(i'_2,j'_2)-1) <' (i_2,\mu(i_2,j_2) - 1)$ by construction. Therefore, $(i_2,\mu(i_2,j_2)-1)$ cuts $(i'_2,\mu(i'_2,j'_2))$ with respect to $(U'_1,U'_2,<')$.

    Let $k \in [n-1]$ be such that $(i'_k,j'_k) = (i_2,j_2)$. We now show that $(i_k,\mu(i_k,j_k))$ cuts $(i'_k,\mu(i'_k,j'_k))$ with respect to $(U'_1,U'_2,<')$. By Lemma~\ref{lem-mu-minus-1-order}, we have $(i_k,\mu(i_k,j_k) - 1) <' (i'_k,\mu(i'_k,j'_k))$. We have $(i'_2,j'_2) \lesssim (i_k, j_k)$, so by Lemma~\ref{lem-mu-order}, $(i'_2,\mu(i'_2,j'_2)) \lesssim' (i_k, \mu(i_k,j_k))$. Then,
    \[
        (i'_k,\mu(i'_k,j'_k)-1) = (i_2,\mu(i_2,j_2) - 1) <' (i'_2,\mu(i'_2,j'_2)) \lesssim' (i_k, \mu(i_k,j_k))
    \]
    by construction. Therefore, $(i_k,\mu(i_k,j_k))$ cuts $(i'_k,\mu(i'_k,j'_k))$ with respect to $(U'_1,U'_2,<')$.

    We have $(i'_{n-1},\mu(i'_{n-1}, j'_{n-1}))$ mirrors $(i_2,\mu(i_2,j_2)-1)$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-minus-1-mirror}. For each $\ell \in [3,k-1] \cup [k+1,n-1]$, we have $(i_\ell,\mu(i_\ell,j_\ell))$ cuts $(i'_\ell,\mu(i'_\ell,j'_\ell))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-minus-1-order}. For each $\ell \in [2,n-2]$, we have $(i'_\ell,\mu(i'_\ell,j'_\ell))$ mirrors $(i_{\ell+1},\mu(i_{\ell+1},j_{\ell+1}))$ with respect to $(U'_1,U'_2,<')$ by Lemma~\ref{lem-mu-mirror}. Therefore, $C'$ is a cycle in $G_{U'_1,U'_2,<'}$.
\end{proof}

We can now prove Theorem~\ref{thm-necessary}.

\begin{proof}[Proof of Theorem~\ref{thm-necessary}]
    Let $(U_1,U_2,<)$ be a hereditarily staggered extended word equation such that $G_{U_1,U_2,<}$ is cyclic. By Lemma~\ref{lem-pointed}, $G_{U_1,U_2,<}$ contains a cycle that is pointed with respect to some auxiliary set. By Lemmas~\ref{lem-not-minimum} and \ref{lem-minimum}, it is possible to apply a coherent extended Nielsen transformation to $(U_1,U_2,<)$ that yields a staggered extended word equation $(U'_1,U'_2,<')$ such that $G_{U'_1,U'_2,<'}$ is cyclic. Since $(U_1,U_2,<)$ is hereditarily staggered, so is $(U'_1,U'_2,<')$. This can be iterated \emph{ad infinitum}, which proves that $(U_1,U_2,<)$ is non-terminating.
\end{proof}

\section{Miscellaneous propositions} \label{sec-misc}

This section contains miscellaneous propositions about extended word equations.

\subsection{Applying a coherent extended Nielsen transformation}

\begin{proposition} \label{prop-coherent-ext}
    If $(U_1, U_2, <)$ is a nontrivial coherent extended word equation, there is some coherent extended Nielsen transformation that can be applied to it.
\end{proposition}
\begin{proof}
    Let $L : \mathcal{X}^* \to (\mathbb{N}, +)$ be a homomorphism such that $L(X) > 0$ for all $X \in \mathcal{X}$ and
    \[
        (i,j) < (i',j') \Longleftrightarrow L(U_{i,1} U_{i,2} \cdots U_{i,j}) < L(U_{i',1} U_{i',2} \cdots U_{i',j'})
    \]
    for all $(i,j), (i',j') \in B$, where $B$ is the set of boundaries of $(U_1,U_2)$.

    If $(1,1) \approx (2,1)$, then let $(U'_1, U'_2, <')$ be the case I extended Nielsen transformation to $(U_1, U_2, <)$. In this case, the same homomorphism $L$ demonstrates that $(U'_1, U'_2, <')$ is coherent.

    If $(1,1) \not\approx (2,1)$, we may assume without loss of generality that $(1,1) > (2,1)$, since cases II and III are symmetric. Let $L' : \mathcal{X}^* \to (\mathbb{N}, +)$ be the homomorphism given by $L'(U_{1,1}) = L(U_{1,1}) - L(U_{2,1})$ and $L'(X) = L(X)$ for all $X \in \mathcal{X} \setminus \{U_{1,1}\}$. Then, let $(U'_1, U'_2)$ be the case II Nielsen transformation of $(U_1, U_2)$, and let $<'$ be the boundary order given by
    \[
        (i,j) <' (i',j') \Longleftrightarrow L'(U'_{i,1} U'_{i,2} \cdots U'_{i,j}) < L'(U'_{i',1} U'_{i',2} \cdots U'_{i',j'})
    \]
    for all $(i,j), (i',j') \in B'$, where $B'$ is the set of boundaries of $(U'_1,U'_2)$. Let $\mu$, $\nu$, and $B'^-$ be defined as in Section~\ref{sec-ext-nielsen}. Given $(i,j) \in B'^-$, let $k$ be such that $\mu(i,k) = j$. Then, we have
    \begin{align*}
        L'(U'_{i,1} U'_{i,2} \cdots U'_{i,j}) &= L'(U'_{i,1} U'_{i,2} \cdots U'_{i,\mu(i,k)}) \\
        &= L'(T(U_{i,1} U_{i,2} \cdots U_{i,k})^+) \\
        &= L'(T(U_{i,1} U_{i,2} \cdots U_{i,\nu(i,\mu(i,k))})^+) \quad\text{by Lemma~\ref{lem-left-inverse}} \\
        &= L'(T(U_{i,1} U_{i,2} \cdots U_{i,\nu(i,j)})^+) \\
        &= L'(T(U_{i,1} U_{i,2} \cdots U_{i,\nu(i,j)})) - L'(U_{2,1}) \\
        &= L(U_{i,1} U_{i,2} \cdots U_{i,\nu(i,j)}) - L'(U_{2,1}),
    \end{align*}
    where $T$ is the endomorphism on $\mathcal{X}^*$ given by $T(U_{1,1}) = U_{2,1} U_{1,1}$ and the identity function on other elements of $\mathcal{X}$. Hence, for any $(i,j), (i',j') \in B'^-$, we have
    \begin{align*}
        (i,j) <' (i',j') &\Longleftrightarrow L'(U'_{i,1} U'_{i,2} \cdots U'_{i,j}) < L'(U'_{i',1} U'_{i',2} \cdots U'_{i',j'}) \\
        &\Longleftrightarrow L(U_{i,1} U_{i,2} \cdots U_{i,\nu(i,j)}) < L(U_{i',1} U_{i',2} \cdots U_{i',\nu(i',j')}) \\
        &\Longleftrightarrow (i,\nu(i,j)) < (i',\nu(i',j')).
    \end{align*}
    Therefore, $(U'_1, U'_2, <')$ is a case II coherent extended Nielsen transformation of $(U_1, U_2, <)$.
\end{proof}

\subsection{Preserving acyclicity}

\begin{proposition}
    Suppose $(U'_1,U'_2,<')$ is the result of applying a coherent extended Nielsen transformation to $(U_1,U_2,<)$. If $G_{U_1,U_2,<}$ is acyclic, then so is $G_{U'_1,U'_2,<'}$.
\end{proposition}
\begin{proof}
    This is immediate from Lemmas~\ref{lem-walk-case1} and \ref{lem-walk-case2}.
\end{proof}

\subsection{A sufficient condition for coherence}

In this subsection, we prove the following proposition.
\begin{proposition} \label{prop-acyclic-coherent}
    Let $(U_1,U_2,<)$ be an extended word equation. If $G_{U_1,U_2,<}$ is acyclic, then $(U_1,U_2,<)$ is coherent.
\end{proposition}

\noindent
First, we need a definition and a lemma.

\begin{definition}
    Given an extended word equation $(U_1,U_2,<)$, we say that the boundaries $(i,j)$ and $(i',j')$ are \emph{twins} if $U_{i,j} = U_{i',j'}$, $(i,j) \neq (i',j')$, $(i,j) \approx (i',j')$, and $(i,j-1) \approx (i',j'-1)$. We say that a cover $(A,B)$ is \emph{twin-free} if neither $A$ nor $B$ contains a twin.
\end{definition}

\begin{lemma} \label{lem-twin-free-incoherent-core}
    If $(U_1,U_2,<)$ is incoherent, then there is an incoherent core such that no cover impinges on another and every cover is twin-free.
\end{lemma}
\begin{proof}
    Let $C = \{(A_\ell, B_\ell) \mid \ell \in [N]\}$ be an incoherent core. By Lemma~\ref{lem-incoherent-char}, for some $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$, we have
    \begin{equation} \label{subset-4}
        \sum_{\ell \in [N]} y_\ell \cdot U_{B_\ell} \subseteq \sum_{\ell \in [N]} y_\ell \cdot U_{A_\ell}
    \end{equation}
    such that either the inclusion is strict or $y_\ell > 0$ for some $\ell \in [N]$ such that $(A_\ell, B_\ell)$ is a strict cover. We may choose $C$ and the coefficients $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$ so that $y_\ell > 0$ for all $\ell \in [N]$ and
    \begin{equation} \label{minimizer-2}
        \sum_{\ell \in [N]} y_\ell \cdot (|A_\ell| + |B_\ell|)
    \end{equation}
    is minimal. As in Lemma~\ref{lem-disjoint-incoherent-core}, all the covers in $C$ are tight and no cover impinges on another.

    We claim that every cover is twin-free. For the sake of contradiction, suppose otherwise. Without loss of generality, $(A_1,B_1)$ is not twin-free. Since $(A_1,B_1)$ is tight, both $A_1$ and $B_1$ contain a twin. Let $(i,j)$ and $(i',j')$ be twins such that $(i,j) \in A_1$ and $(i',j') \in B_1$. We will contradict our assumption that \eqref{minimizer-2} is minimal.

    Write
    \begin{align*}
        A_1 &= \ang{i, [j_1,k_1]} \\
        B_1 &= \ang{i', [j_2,k_2]}.
    \end{align*}
    Let
    \begin{align*}
        A'_1 &= \ang{i, [j_1,j-1]} \\
        B'_1 &= \ang{i', [j_2,j'-1]} \\
        A''_1 &= \ang{i, [j+1,k_1]} \\
        B''_1 &= \ang{i', [j'+1,k_2]}.
    \end{align*}
    Both $(A'_1,B'_1)$ and $(A''_1,B''_1)$ are covers. We have
    \[
        U_{A_1} + U_{B'_1} + U_{B''_1} = U_{A_1} + U_{B_1} - U_{i',j'} = U_{A_1} + U_{B_1} - U_{i,j} = U_{B_1} + U_{A'_1} + U_{A''_1}.
    \]
    Hence,
    \[
        U_{A_1} + U_{B'_1} + U_{B''_1} + \sum_{\ell \in [N]} y_\ell \cdot U_{B_\ell} \subseteq U_{B_1} + U_{A'_1} + U_{A''_1} + \sum_{\ell \in [N]} y_\ell \cdot U_{A_\ell}.
    \]
    Canceling terms, we get
    \begin{equation} \label{subset-5}
        U_{B'_1} + U_{B''_1} + (y_1 - 1) \cdot U_{B_1} + \sum_{\ell \in [2,N]} y_\ell \cdot U_{B_\ell} \subseteq U_{A'_1} + U_{A''_1} + (y_1 - 1) \cdot U_{A_1} + \sum_{\ell \in [2,N]} y_\ell \cdot U_{A_\ell}.
    \end{equation}
    If the inclusion \eqref{subset-4} is strict, then so is \eqref{subset-5}. If $(A_1,B_1)$ is a strict cover, then at least one of $(A'_1,B'_1)$ and $(A''_1,B''_1)$ is a strict cover. Thus, \eqref{subset-5} satisfies the condition from Lemma~\ref{lem-incoherent-char}.

    We have
    \[
        |A'_1| + |B'_1| + |A''_1| + |B''_1| < |A_1| + |B_1|.
    \]
    This inequality together with the inclusion \eqref{subset-5} contradicts our assumption that \eqref{minimizer-2} is minimal.
\end{proof}

We can now prove Proposition~\ref{prop-acyclic-coherent}.
\begin{proof}[Proof of Proposition~\ref{prop-acyclic-coherent}]
    We prove the contrapositive. Suppose that $(U_1,U_2,<)$ is incoherent. By Lemma~\ref{lem-twin-free-incoherent-core}, $(U_1,U_2,<)$ has an incoherent core $C = \{(A_\ell, B_\ell) \mid \ell \in [N]\}$ such that no cover impinges on another and every cover is twin-free.

    By Lemma~\ref{lem-incoherent-char}, there are some $\{y_\ell \in \mathbb{N} \mid \ell \in [N]\}$ such that
    \begin{equation} \label{subset-6}
        \sum_{\ell \in [N]} y_\ell \cdot U_{B_\ell} \subseteq \sum_{\ell \in [N]} y_\ell \cdot U_{A_\ell}.
    \end{equation}
    By Lemma~\ref{lem-cover-cut}, for any $\ell \in [N]$, if $(i_1,j_1) \in A_\ell$ cuts some $(i'_1,j'_1)$, then $(i'_1,j'_1) \in B_\ell$. In particular, for any $\ell \in [N]$, every $(i_1,j_1) \in A_\ell$ cuts some $(i'_1,j'_1) \in B_\ell$.

    Next, we claim that for any $\ell \in [N]$, every $(i'_1,j'_1) \in B_\ell$ mirrors some $(i_2,j_2) \in A_{\ell'}$ for some $\ell' \in [N]$. Let $(i'_1,j'_1) \in B_\ell$. By the inclusion \eqref{subset-6}, there is some $(i_2,j_2) \in A_{\ell'}$ with $U_{i'_1,j'_1} = U_{i_2,j_2}$. Since no cover of $C$ impinges on another, $(i'_1,j'_1) \neq (i_2,j_2)$. Since every cover of $C$ is twin-free, $(i'_1,j'_1) \not\approx (i_2,j_2)$ or $(i'_1,j'_1 - 1) \not\approx (i_2,j_2 - 1)$. Hence, $(i'_1,j'_1)$ mirrors $(i_2,j_2)$.

    Therefore, for any $(i_1,j_1) \in A_\ell$, there is some $(i_2,j_2) \in A_{\ell'}$ such that $((i_1,j_1), (i_2,j_2)) \in E$, where $G_{U_1,U_2,<} = (B,E)$. Hence, we have an infinite walk in $G_{U_1,U_2,<}$. It follows that $G_{U_1,U_2,<}$ is cyclic.
\end{proof}

\section{Future directions}

The most obvious future direction is to find a necessary and sufficient condition for a coherent extended word equation to be terminating. This will require a better understanding of non-staggered extended word equations. It is somewhat vague what would count as a satisfactory necessary and sufficient condition, but we at least expect the following to be true.
\begin{conjecture}
    It is decidable whether a coherent extended word equation is terminating.
\end{conjecture}

It would also be interesting to prove results about which coherent extended word equations are weakly terminating. We expect that the methods developed in this paper can help make progress on that front too.

