\begin{abstract}
This paper identifies and rectifies a fundamental mathematical flaw in the classical formulation of the $\ztransform$-transform and its relationship to the inverse Laplace transform ($\laplace^{-1}$). We demonstrate that conventional implementations—based on residue calculus in classical control and Dunford-Taylor integrals in modern state-space methods—systematically neglect the contribution from the infinite arc in the complex plane. This oversight induces discontinuity errors at critical points (e.g., $t=0$) and propagates inconsistencies into step-function definitions. By incorporating the full Bromwich contour integral with all boundary contributions, we establish a mathematically complete framework that restores consistency between $\laplace^{-1}$, $\ztransform$-transform, and DTFT aliasing theory. Our correction resolves decades of contention regarding initial-value discrepancies and extends to modified $\ztransform$-transforms for delayed systems. The work transitions sampled-data theory from empirical patching to mathematical completeness, providing rigorous foundations for both classical and modern control applications.
\end{abstract}

\begin{IEEEkeywords}
Z-transform, inverse Laplace transform, sampled-data systems, Bromwich integral, residue theorem, Dunford-Taylor integral, discrete-time systems
\end{IEEEkeywords}

\section{Introduction}
\IEEEPARstart{M}{athematical} foundations of sampled-data theory have long relied on two flawed implementations of the inverse Laplace transform ($\laplace^{-1}$): \textbf{residue calculus in classical control} and \textbf{Dunford-Taylor integrals in modern state-space methods}. This paper reveals how both approaches systematically neglect critical contributions from the infinite arc in the complex plane—a fundamental oversight that propagates errors into $\ztransform$-transform theory, step-function definitions, and physical system modeling.  

\subsection{The Dual Pathology of Inverse Laplace Implementations}

\subsubsection{Classical Control: Misapplied Residue Calculus}
Traditional impulse-invariance methods compute sampled sequences as:
\begin{equation}
x_c(n\Ts) = \sum \res\left[X_c(s)e^{sn\Ts}\right]
\label{eq:residue_error}
\end{equation}
This erroneously assumes $\int_{\arcR} \!\!\! X_c(s)e^{st}ds \to 0$—valid for $t>0$ but \textbf{indefensible at $t=0$}:
\begin{IEEEeqnarray}{c}
\lim_{R\to\infty} \int_{\arcR} \!\!\! X_c(s)e^{s\cdot0}ds \neq 0 \\
\text{when poles exist at infinity}
\label{eq:arc_error}
\end{IEEEeqnarray}
The neglected term introduces \textbf{discontinuity errors at initialization}.

\subsubsection{Modern Control: Abridged Dunford-Taylor Integrals}
State-space discretization employs:
\begin{equation}
x_c(t) = \frac{1}{2\pi i} \oint_{\mathcal{C}} X_c(s)e^{st}  ds
\label{eq:dunford_error}
\end{equation}
This formulation \textbf{ignores arc contributions} while \textbf{analytic continuation masks boundary effects}.

\subsection{Ambiguous Step-Function Definitions}
Heaviside $u(t)$ suffers inconsistent definitions:
\begin{align}
&\text{Left-continuous: } u(0)=0 \\
&\text{Right-continuous: } u(0)=1 \\
&\text{Physical: } u(0)=0.5
\end{align}
Sampled-data theory defaults to \textbf{unphysical right-continuous convention}.

\subsection{Superficial Fixes and Their Failures}

\subsubsection{Definition-Centric Correction}
\begin{equation}
X_s(z) = \frac{1}{\Ts}\sum_{k=-\infty}^{\infty}X\left(s - j\tfrac{2\pi}{\Ts}k\right) + \frac{x(0^+)}{2}
\label{eq:definition_fix}
\end{equation}
\textbf{Flaws}:
\begin{itemize}
\item Inherits infinite-arc error
\item Enforces unphysical $u(0)=1$
\end{itemize}

\subsubsection{Method-Centric Alignment}
\begin{equation}
X_{\text{imp}}(z) = \frac{1}{\Ts} \sum_{k} X\left(s - j \tfrac{2\pi}{\Ts} k \right) - \frac{x(0^+)}{2}
\label{eq:method_fix}
\end{equation}
\textbf{Flaws}:
\begin{itemize}
\item Lacks mathematical proof
\item Ignores Dunford-integral errors
\end{itemize}

\begin{center}
\fbox{\parbox{\columnwidth}{\centering \textbf{Core Issue}: Both fixes ignore \\ pathological arc neglect and step-function arbitrariness}}
\end{center}

\subsection{Foundational Correction}

\subsubsection{Rigorous Inverse Laplace via Full Bromwich Integration}
We rectify $\laplace^{-1}$:
\begin{equation}
x_c(t) = \frac{1}{2\pi i} \lim_{R\to\infty} \left( \int_{\sigma-iR}^{\sigma+iR} \!\!\!\!\! + \!\!\! \int_{\arcR} \right) X_c(s)e^{st}  ds
\label{eq:bromwich_full}
\end{equation}
\textbf{Key proof}:
\begin{equation}
\frac{1}{2\pi i} \int_{\arcR} \!\!\! X_c(s) ds = \frac{x(0^+) - x(0^-)}{2} \neq 0
\label{eq:arc_contribution}
\end{equation}

\subsubsection{Physical Step-Function Definition}
Sampled systems require:
\begin{equation}
u(0) = \frac{u(0^-) + u(0^+)}{2} = 0.5
\label{eq:step_correction}
\end{equation}
Validated by Dirac-comb convolution.

\subsubsection{Triple Unification}
\begin{IEEEeqnarray*}{ll}
\textbf{Domain} & \textbf{Consistency Restoration} \\
\hline
$\laplace^{-1} \leftrightarrow \ztransform$ & Full-boundary $\laplace^{-1}$ at $t=n\Ts$ $\equiv$ $\ztransform$ \\
$\ztransform \leftrightarrow \text{DTFT}$ & Corrected $\ztransform = \frac{1}{\Ts}\sum_k X(s+jk\ws)$ \\
Math $\leftrightarrow$ Physics & $u(0)=0.5$ matches analog measurements
\end{IEEEeqnarray*}
where $\ws = 2\pi/\Ts$.

\subsection{Engineering Impact}
\begin{enumerate}
\item \textbf{Classical}: Corrects residue-based methods
\item \textbf{Modern}: Fixes Dunford integrals
\item \textbf{Extensions}: Modified $\ztransform$-transforms for delayed systems
\end{enumerate}

