\vspace{-.25cm}
\section{Methods}
\vspace{-.25cm}

\begin{algorithm}[t]
\caption{\ourmethod{}}
\label{alg:self-distillation}
\begin{algorithmic}
\REQUIRE Model $\theta$, Image $x$, Instruction $I$, 
\STATE Generate initial plan: $p_0 \gets \theta(x, I)$
\STATE Initialize: $p_{\text{curr}} \gets p_0$
\REPEAT
    \STATE Critique: $c \gets \text{Crit}(p_{\text{curr}})$ \hfill // Self-critique
    \STATE Revise: $p_{\text{rev}} \gets \text{Rev}(p_{\text{curr}}, c)$ \hfill // Generate improved plan
    \STATE Verify: $p_{\text{best}} \gets \text{Ver}(p_{\text{curr}}, p_{\text{rev}})$ \hfill // Choose better plan
    \IF{$p_{\text{best}} = p_{\text{rev}}$}
        \STATE \textbf{break} \hfill // Improvement found; terminate loop
    \ELSE
        \STATE \textbf{continue} \hfill // No improvement; keep current plan and revise again
    \ENDIF
\UNTIL{Convergence or max iterations reached}
\RETURN Final plan $p_{\text{curr}}$
    \vspace{-.1cm}
\end{algorithmic}
\end{algorithm}

