\subsection{Cyclic Execution of Sub-protocols}
Using the phase clock~\cite{AAE08} described in Section~\ref{sec:phase_clock}, $\ssrk(\rho)$ invokes the sub-protocols $\findtarget$, $\ccd(r,\rho)$, and $\ranking$ in phases $[T_1,T_2-2]$, $[T_2,T_3-2]$, and $[T_3,T_4-2]$, respectively (line~17), where
$$
T_1 = 2,\quad
T_2 = T_1 + \constT \left\lceil \sqrt{n}\ \right\rceil,\quad
T_3 = T_2 + \constT \left\lceil \frac{n \lg \rho }{\rho \log n} \right\rceil,\quad
T_4 = T_3 + 2\constT \left\lceil \sqrt{n} \right\rceil,
$$
and $\constT=\Theta(1)$ is a sufficiently large constant to ensure the correctness of each component.
If an agent enters phase $\tmax$, it raises a reset flag (lines 11--12), returning all agents to the initial phase $0$ by the epidemic protocol (lines 2--6). Since each phase completes in $\Theta(n\log n)$ interactions w.h.p.\ by Lemma~\ref{lemma:phaseclock}, one cycle of $\tmax$ phases requires only $\Theta(\goalI)$ interactions w.h.p.

A variable $\mode \in \{\bot,\modeF,\modeD,\modeR\}$ plays a key role in self-stabilization. The modes $\modeF$, $\modeD$, and $\modeR$ correspond to the sub-protocols $\findtarget$, $\ccd$, and $\ranking$, respectively. When an agent switches its $\mode$ from $x$ to a different mode $y \neq \bot$, it runs the initialization procedure for component $y$. The initialization procedures for $\ccd$ and $\ranking$ are given in the preambles of Algorithms~\ref{al:ccd} and~\ref{al:ranking}, respectively, while the procedure for $\findtarget$ is described in Section~\ref{sec:findtarget}. Note that $\ccd(r,\rho)$ requires the target rank $r$; upon entering mode $\modeD$, each agent $a$ adopts $a.\target$ for $r$.
Mode switching occurs in phases $T_1-1$, $T_2-1$, and $T_3-1$, i.e., immediately before each component starts (line~15). An agent $a$ enters mode $\modeR$ only if $a.\detected=1$, i.e., its rank-collision-detected flag is raised,
so rank reassignment cannot begin until $\ccd(r,\rho)$ detects a collision. Each component executes only when both interacting agents share the same mode; additionally, during mode $\modeD$ (collision detection), they must have the same target rank (lines~16–17).


The first part of the main function (Lines 2–12) resets all agents to phase~0 within $O(\goalI)$ interactions w.h.p., regardless of the initial configuration (Lemma \ref{lemma:reset}). By Lemma~9, this ensures the population completes one full cycle of the three components in the next $\Theta(\goalI)$ interactions w.h.p.
This reset mechanism relies on two timers, $\rst\in[0,\constR\lg n]$ and $\delay\in[0,\constD\cdot\logn]$, where a constant $\constD=\Theta(1)$ is chosen sufficiently larger than $\constR=\Theta(1)$.
We omit the update rules for $\rst$ and $\delay$ (as specified inlines 2–12) here, as they follow standard techniques~\cite{BCC+21,SEIM21} and closely mirror the \protocol{PropagateReset} sub-protocol of Burman et al.~\cite{BCC+21}.

\begin{note}
\label{note:variable_reset}
When an agent observes $\rst>0$, it resets $\mode=\bot$ and $\detected=0$ (line~6). These resets are not required for correctness but simplify the subsequent proof.
\end{note}


\begin{definition}
\label{def:initialized_configurations}
Let $\calI$ be the set of configurations in which
$a.\clock = a.\rst = a.\delay = \detected=0$ and $a.\mode = \bot$ hold for all $a \in A$.
\end{definition}

\begin{lemma}
\label{lemma:reset}
Starting from any configuration, the population under $\ssrk(\rho)$ enters $\calI$ within $O(\tmax\cdot n\log n)$ interactions w.h.p. 
\end{lemma}
\begin{psketch}
Follows from Lemma 1 of \cite{ADK+17}, Lemma 5 of \cite{SOK+20}, and Lemma~\ref{lemma:phaseclock}.
\end{psketch}

For the subsequent analysis, we introduce the following sets of configurations.
\begin{definition}
For each $X\in\{\modeF,\modeD,\modeR\}$, let $\cinit(X)$ be the set of configurations of $\ssrk(\rho)$ in which every agent
\begin{enumerate}
  \item is in mode $X$ and in phase $T_1-1$, $T_2-1$, or $T_3-1$ for $X=\modeF,\modeD,\modeR$, respectively, and
  \item has all variables of the corresponding component correctly initialized.
\end{enumerate}
Moreover, for any $r\in [1,n]$, we define $\cinit(\modeD,r)$ as the set of configurations in $\cinit(\modeD)$ where $a.\target = r$ for every agent $a\in A$.
\end{definition}



\begin{algorithm}[t]
\caption{
$\ccd(r,\rho)$ at an interaction where initiator $\ini$ and responder $\res$ meets. 
Whenever this sub-protocol is invoked, $r = \ini.\target = \res.\target$.
} 
\label{al:ccd}
\Notation{
$\rname = [1,\mname] \setminus \{r\}$
}
\Variables{
$\vlist \in \{S \subseteq \rname: |S| \le \rho\}$, 
$\kid \in \rname\cup \{\bot\}$,
$\susp \in \{0,1\}$
}
\Predicates{
$\isKing(a) \equiv (a.\rank = r)$,\\
\hspace{2.1cm} $\isVassal(a) \equiv (a.\rank \in a.\vlist)$,\\
\hspace{2.1cm} $\isRonin(a) \equiv (a.\rank \in \rname\, \land\, a.\rank \notin a.\vlist)$\\
\hspace{2.1cm} $
\trust(a,b) \equiv
\left(
\begin{aligned}
&a.\kid = b.\kid\, \land\, a.\vlist \subseteq b.\vlist\, \land\, |b.\vlist|=\rho\\
&\land (\isKing(b) \lor \isVassal(b))
\end{aligned}
\right)
$
}
\Initially{
$a.\detected = 0$, $a.\vlist = \emptyset$, $a.\kid=\bot$, $a.\susp = 0$%, $a.\nonce = \bot$
}
\uIf{$\isKing(\ini) \land |\ini.\vlist| <  \rho \land \res.\rank \notin \ini.\vlist \land \isRonin(\res)$}{
$\res.\vlist \gets \ini.\vlist \gets \ini.\vlist \cup \{\res.\rank\}$\;
$
\res.\kid \gets \ini.\kid \gets
\begin{cases}
\res.\rank & \tif \ini.\kid = \bot \\
\ini.\kid & \totherwise
\end{cases}
$\;
}
\uElseIf{$\isVassal(\res) \land \trust(\res,\ini)$}{
$\res.\vlist \gets \ini.\vlist \cup \res.\vlist$\;
}
\uElseIf{$\isKing(\ini)\, \land\, \isVassal(\res)\ \land\, \ini.\kid \neq \res.\kid$}{
$\res.\susp \gets 1$\;
}\ElseIf{$\trust(\ini,\res)\, \land\, \trust(\res,\ini)$}{
$\res.\susp \gets \max(\ini.\susp,\res.\susp)$\;
}
$
\res.\detected \gets 
\begin{cases}
1 & \tif
\left (
\begin{aligned}
&(\isKing(\res) \land \res.\susp = 1)\\
&\ \lor (\ini.\rank = \res.\rank)
\end{aligned}
\right )
\\
\max(\ini.\detected,\res.\detected) & \totherwise
\end{cases}
$\;
\end{algorithm}


\subsection{Careful Collision Detection}
\label{sec:ccd}
Given a target rank $r$, the sub-protocol $\ccd(r,\rho)$, shown in Algorithm~\ref{al:ccd},
detects whether two or more agents share rank $r$, storing the result in each agent’s $\detected$ variable.
When agents collide on some other rank $r'\neq r$, $\ccd(r,\rho)$ may detect a collision even if only one agent currently holds rank $r$. Such misdetections are harmless: any detected collision should trigger
a rank reassignment. 

Every agent maintains a set variable $\vlist\subseteq\rname$ with $|\vlist|\le\rho$, where $\rname=[1,\mname]\setminus\{r\}$, a variable $\kid\in\rname\cup\{\bot\}$, and a Boolean variable $\susp\in\{0,1\}$. When an agent $a$ switches to mode $\modeD$ (line~15), it initializes $a.\detected=0$, $a.\vlist=\emptyset$, $a.\kid=\bot$, and $a.\susp=0$. Once any agent sets its $\detected$ flag to $1$, this information propagates to the entire population via the epidemic protocol (line~27). We now explain how $\ccd(r,\rho)$ ensures that, whenever a collision exists, at least one agent raises its $\detected$ flag within $O(\goalI)$ interactions with probability $\Omega(1)$.

We classify agents into four roles: kings, vassals, ronins, and commoners. An agent of rank $r$ is a \emph{king}. A non-king agent $a$ with $a.\rank\in\rname$ is a \emph{vassal} if $a.\rank\in a.\vlist$, and a \emph{ronin} (i.e., a masterless warrior) otherwise. All other agents (those with rank in $[\,\mname+1,n]\setminus\{r\}$) are \emph{commoners}. This protocol concerns only kings, vassals, and ronins; commoners are ignored except by direct collision detection: whenever two agents of the same rank interact, the responder immediately sets $\detected=1$ (line~27). Direct collision detection simplifies our analysis: we may, without loss of generality, restrict attention to initial configurations with few colliding pairs, particularly those with few kings and many ronins, thanks to the following simple observation.
%. We will formalize this later (Lemma \ref{obs:many_ronins}). 


\begin{observation}[Generalization of Lemma~3 of \cite{AS25}]
\label{obs:many_ronins}
In a population of $n$ agents with $x\ge1$ colliding pairs (i.e., unordered pairs of agents sharing the same rank), the direct collision detection protocol detects a collision within $O(n^2/x)$ interactions both in expectation and with probability $\Omega(1)$.
\end{observation}
\begin{proof}
Each interaction involves a colliding pair with probability at least $x/\binom{n}{2} = \Omega(x/n^2)$, so the expected detection time is $O(n^2/x)$. The constant‐probability bound then follows by Markov’s inequality.
\end{proof}


The goal of a king is to detect the presence of any other king. Roughly, each king adopts up to $\rho$ vassals and records their ranks in its $\vlist$. If a vassal encounters another king, it sets its $\susp$ flag to $1$, and this flag propagates to all of the king’s vassals via a variant of the epidemic protocol. When the king later interacts with a trusted vassal whose $\susp=1$, it sets its own $\detected$ flag to $1$. This high-level overview omits many rules needed to achieve fast detection and avoid false positives. In the remainder of this subsection, we formalize this process and prove it satisfies both:
\begin{itemize}
  \item \textbf{Liveness} (Lemma \ref{lemma:detect}): for any $C\in\cinit(\modeD,r)$ with at least two agents of rank $r$, a collision is detected with probability $\Omega(1)$ within $O(\goalI)$ interactions; and 
  \item \textbf{Safety} (Lemma \ref{lemma:closure}): once the population under $\ssrk(\rho)$ reaches a \emph{safe} configuration, no false positives occur.
\end{itemize}


Let $a_K$ be a king. When $a_K$ (as initiator) meets a ronin $b$, $a_K$ adopts $b$ as a vassal: it adds $b.\rank$ to $a_K.\vlist$, and $b$ copies this into $b.\vlist$ (line~19). If $a_K.\vlist$ already contains $\rho$ ranks or includes $b.\rank$, then $a_K$ ignores $b$. Simultaneously, $a_K$ records the rank of its first vassal in $a_K.\kid$ as its \emph{kingdom identifier} and disseminates it to all adopted vassals (line~20). As we will show later, we may assume w.l.o.g.\ that
no other king shares the same kingdom identifier as $a_K$.
We say that an agent $a$ is \emph{saturated} if $|a.\vlist|=\rho$,
while an agent $a$ \emph{trusts} an agent $b$ if $a.\kid = b.\kid$, $a.\vlist \subseteq b.\vlist$, and $b$ is saturated. Vassals always attempt to acquire the complete vassal list from any trusted agent, especially a king: whenever a vassal $\res$ (as responder) meets a trusted agent $\ini$, the vassal $\res$ adds all ranks in $\ini.\vlist$ to its own list if capacity allows (lines 21–22). If a vassal $\res$ interacts with a king with a different kingdom identifier, then $\res$ sets its $\susp$ flag to $1$, indicating a suspected collision (line 23). Note that this event can occur even when there is exactly one king, if $\res$ is outdated---i.e., the unique king $\ini$ has already started the next cycle and obtains a new kingdom identifier. Although the phase clock synchronizes the population w.h.p., making this event exceedingly rare, we must handle it to solve SS-RK (whereas LS-RK could safely ignore it). After a vassal raises its $\susp$ flag, this information spreads among vassals via a variant of the epidemic protocol: the raised $\susp$ flag propagates from an initiator to a responder if and only if they trust each other (line 23).
Once a king’s $\susp$ flag is set, the king finally sets its $\detected$ flag.


\begin{lemma}
\label{lemma:detect}
Starting from any configuration $C \in \cinit(\modeD,r)$ with $r \in [1,n]$, in which at least two agents hold the target rank $r$, the population under $\ssrk(\rho)$ reaches a configuration where every agent has $\detected=1$ within $O(\goalI)$ interactions with probability $\Omega(1)$.
\end{lemma}
\begin{proof}
Fix any king $a_K$ in $C$. It suffices to show that $a_K$ raises its $\detected$ flag within $O(\goalI)$ interactions with probability $\Omega(1)$; by Lemma~\ref{lemma:epidemic}, this flag then propagates to all agents within $O(n\log n)=O(\goalI)$ interactions w.h.p. We may assume w.l.o.g.\ that $\rho=\omega(1)$, since if $\rho=O(1)$, direct collision detection alone raises $\detected$ within $O(n^2)=O(\goalI)$ interactions with probability $\Omega(1)$, as desired.



Let $x_C$, $n_K$, and $n_R$ be the numbers of colliding pairs (i.e., unordered pairs of agents sharing the same rank), kings, and ronins, respectively, in configuration $C$. By Observation~\ref{obs:many_ronins}, we may assume w.l.o.g.\ that $x_C = o(\rho/\log \rho)$. Since $x_C \ge \binom{n_K}{2}$, this implies $n_K = o(\sqrt{\rho/\log \rho})$.
Because $C\in\cinit(\modeD,r)$ contains no vassals, only ronins occupy ranks in $\rname=[1,\mname]\setminus\{r\}$. If $n_R<|\rname|$, the pigeonhole principle gives $x_C \ge |\rname|-n_R$. Hence $n_R = |\rname|-o(\rho/\log \rho)=\Omega(\mname)$.

We may assume w.l.o.g.\ that $a_K$ obtains a unique kingdom identifier. Call an agent \emph{colliding} if it shares its rank with another agent; at most $2x_C$ agents are colliding in $C$. Since each of the $n_K$ kings adopts at most $\rho$ vassals, there are always at least $n_R - n_K\cdot\rho = \Omega(\mname)$ ronins. Hence, when $a_K$ meets a ronin for the first time, that ronin is non‐colliding with probability $1 - 2x_C/(n_R - n_K\cdot\rho) = 1 - o(1)$. Therefore, with probability $1 - o(1)$, $a_K$’s first‐vassal rank is unique, giving it a unique kingdom identifier. This negligible failure probability does not affect the lemma.

By Lemma~\ref{lemma:phaseclock}, we may lengthen each phase by an arbitrarily large constant factor $\cmin$. Hence, by Markov’s inequality, it suffices to show that $a_K$ raises its $\detected$ flag within $O(\goalI)$ expected interactions, assuming no agent leaves mode $\modeD$.

Since $\Omega(\mname)$ ronins always exist as mentioned above, $a_K$ meets a ronin with probability $\Omega(\mname/n^2)$ per step.
Therefore, $a_K$ collects $\rho$ distinct ranks (allowing for up to $x_C$ redundant collisions) and becomes saturated within $O((\rho + x_C)\,n^2/\mname) = O(\goalI)$ expected interactions. 
Let $V=\{v_1,\dots,v_\rho\}$ be the vassals of $a_K$, and let $R=\{v.\rank : v\in V\}$ be their ranks. Since $a_K$ and every $v\in V$ share the unique identifier $g=a_K.\kid$, no vassal trusts agents outside $V\cup\{a_K\}$, so each $v\in V$ only ever learns ranks in $R$. Therefore, each $v\in V$ always trusts $a_K$ and any saturated vassal in $V$ (after $a_K$ becomes saturated), reducing the spread of \emph{saturation} to an epidemic on $V\cup\{a_K\}$: a vassal in $V$ becomes saturated each time it (as responder) meets any saturated agent in $V\cup\{a_K\}$.
Interactions within $V\cup\{a_K\}$ occur with probability $\binom{\rho+1}{2}/\binom{n}{2}=\Theta(\rho^2/n^2)$ per step.
Since the epidemic on the entire population completes within $O(n \log n)$ interactions w.h.p.\ (hence also in expectation), this restricted epidemic disseminates $R$ to all vassals in $V$ within $O(\sfrac{n^2}{\rho^2}\cdot \rho \log \rho)=O(\goalI)$ expected interactions.

Subsequently, within $O(n^2/\rho)$ expected interactions, some vassal in $V$ interacts with a king other than $a_K$, which must have a different kingdom identifier, causing that vassal to set its $\susp$ flag.
Since all saturated vassals in $V$ trust one another,
this $\susp$ flag then spreads to all agents in $V\cup\{a_K\}$ via the epidemic on $V\cup\{a_K\}$ within $O(\goalI)$ expected interactions. During this spread, $a_K$ meets a vassal with $\susp=1$ and raises its own $\detected$ flag, as desired.
\end{proof}




\begin{definition}[Safe Configuration]
\label{def:safe}
Let $\ssafe$ be the set of configurations of $\ssrk(\rho)$ satisfying:
  (i) all agents have distinct ranks;
  (ii) no agent is in the mode $\modeR$;
  (iii) every agent has $\detected=0$;  
  (iv) every king and ronin has $\susp=0$, i.e., for all $a \in A$,
  $$(a.\mode = \modeD \land (\isKing(a) \lor \isRonin(a)) \to a.\susp=0;$$
  (v) If a king's $\vlist$ contains a vassal's $\vlist$, then the vassal has $\susp=0$ and shares the same kingdom identifier as the king, i.e., for all $a,b \in A$,
$$
\left(
\begin{aligned}
 &a.\mode = b.\mode = \modeD \;\land\; a.\target = b.\target\\
 &\;\land\;\isKing(a)\;\land\;\isVassal(b)\;\land\; b.\vlist \subseteq a.\vlist
\end{aligned}
\right)
\;\to\;(b.\susp = 0 \land a.\kid = b.\kid).
$$  
\end{definition}


\begin{lemma}
\label{lemma:closure}
$\ssafe$ is closed under interactions: any configuration in $\ssafe$ remains in $\ssafe$ after a single interaction.
\end{lemma}
\begin{proof}
Let $C\in\ssafe$, and suppose $C$ transitions to $C'$ by one interaction between initiator $\ini$ and responder $\res$. We show $C'\in\ssafe$.

First, $C'$ clearly satisfies (i) and (ii): no rank changes (since $\res\notin\modeR$) and no agent switches to $\modeR$ (since $\res.\detected=0$). It remains to check (iii), (iv), and (v). If any of these were violated in $C'$, then either $\ini$ or $\res$ must have updated one of the variables $\detected,\susp,\mode,\target,\vlist,\kid$. There are two cases:

\textbf{Case (A)}: $\res$ switches its mode to $\modeD$.\\
Then $\res$ reinitializes $\detected=0$, $\vlist=\emptyset$, $\kid=\bot$, and $\susp=0$. This preserves (iii) and (iv). For (v), note $\res$ is not a vassal in $C'$, and if $\res$ is a king, its empty $\vlist$ cannot contain any vassal's list, which must not be empty. Thus (v) holds.

\textbf{Case (B)}: $\ini$ and $\res$ share the same target rank $r$ and execute $\ccd(r,\rho)$.\\
By (i), exactly one agent---call it $a_K$---has rank $r$. If $a_K.\mode\neq\modeD$ or $a_K.\target\neq r$, then (iii)--(v) remain intact. So assume $a_K.\mode=\modeD$ and $a_K.\target=r$.

\emph{Subcase (B--1)}: $\res$ is a vassal in $C$.\\
Then $\res$ cannot violate (iii) or (iv). To violate (v), $\res$ would have to raise $\susp=1$ while still having $\res.\vlist\subseteq a_K.\vlist$ (no vassal changes its $\kid$). That requires the initiator to be a trusted agent: if $\ini=a_K$, then by (v) in $C$, $\res$ has $\susp=0$; if $\ini$ is another vassal, line~24 raises $\susp$ only when $\ini.\vlist=\res.\vlist$ and $\ini.\susp=1$, which violates (v). Hence no violation occurs.

\emph{Subcase (B--2)}: $\res=a_K$.\\
Then only lines~25--27 can update $\susp$. But since all vassals trusted by $a_K$ have $\susp=0$ in $C$, $a_K$ cannot set $\susp=1$. Thus (iii) and (iv) are preserved. Since a king never updates its $\vlist$ when it is a responder, (v) clearly holds.

In every case, $C'\in\ssafe$.
\end{proof}


\begin{algorithm}[t]
\caption{$\ranking$ at an interaction where initiator $\ini$ and responder $\res$ meets.
} 
\label{al:ranking}
\Notation{
$\rem = \lceil \sqrt{n} \rceil$,\ 
$\phase(a) = \lfloor a.\clock/\constM \rfloor$
}
