$a.\ind = 0$, $a.\rank =
\begin{cases}
1& \tif a.\leader = 1\\
\bot& \totherwise
\end{cases}
$\\
\hspace{1.68cm}
$a.\nonce = 0$, $a.\parity = (\tmid \bmod 2)$
}
\Remark{
\violet{
Within this subprotocol, $\rank\in[1,n]\cup\{\bot\}$ (see Note~\ref{note:domain}).
}
}
Let $\pini = \phase(\ini),\ \pres = \phase(\res)$ \violet{\tcp*{$\pini \le \pres$}}
\If{$\pres < \tmid$}{
\If{$\ini.\rank \neq \bot  \land \ini.\ind < \logn \land \res.\rank = \bot$}{
$\ini.\ind \gets \ini.\ind + 1$\;
Let $\rnew = \ini.\rank + 2^{\logn - \ini.\ind}$\;
\If{$\rnew \le n-\rem$}{
$\res.\rank \gets \rnew$\;
$\res.\ind \gets \ini.\ind$
}
}
}
\If{
$\pres\ge \tmid$ and $\pres \equiv \res.\parity \pmod{2}$
}{
$\res.\parity \gets 1-\res.\parity$\;
Let $h=\pres-\tmid$\;
\If{$h \equiv 0 \pmod{\rept}$}{
