\subsection{Formal Guarantees on Random Projections}
\label{sec:JLtheory}

To give a more principled view of our random projection step, we restate a version of the Johnson--Lindenstrauss (JL) lemma \citep{dasgupta2003elementary} and show how it applies in our multi-view volumetric setting.

\paragraph{Full Proof of the Johnson--Lindenstrauss Lemma}
\label{appendix:jl-proof}

Let $\mathbf{x}_1, \mathbf{x}_2, \dots, \mathbf{x}_n \in \mathbb{R}^d$ be arbitrary vectors, and fix $0 < \varepsilon < 1$. Let $\mathbf{R} \in \mathbb{R}^{K \times d}$ be a random projection matrix whose entries are drawn i.i.d.\ from a sub-Gaussian distribution (e.g., Gaussian) with zero mean and variance $\sigma^2$ chosen so that $\mathbb{E}\bigl[\|\mathbf{R}\mathbf{z}\|_2^2\bigr] = \|\mathbf{z}\|_2^2$ for any $\mathbf{z}\in \mathbb{R}^d$. We show that if $K$ is on the order of $\varepsilon^{-2} \log(n)$, then with high probability for all pairs $i\neq j$,
\[
(1-\varepsilon)\,\|\mathbf{x}_i - \mathbf{x}_j\|_2^2 
\;\le\;
\|\mathbf{R}\,\mathbf{x}_i - \mathbf{R}\,\mathbf{x}_j\|_2^2 
\;\le\;
(1+\varepsilon)\,\|\mathbf{x}_i - \mathbf{x}_j\|_2^2.
\]

\textbf{I: \emph{Single-Pair Analysis.}}
Consider a single pair $(i, j)$ and let $\mathbf{z} = \mathbf{x}_i - \mathbf{x}_j$. The vector $\mathbf{R}\mathbf{z}$ has i.i.d.\ sub-Gaussian components with mean $0$ and variance on the order of $\|\mathbf{z}\|_2^2 / K$. In particular, if $\mathbf{R}$ has Gaussian entries $\sim \mathcal{N}(0, 1/K)$, then each $\langle \mathbf{r}_\ell, \mathbf{z}\rangle$ is $\mathcal{N}(0, \|\mathbf{z}\|_2^2 / K)$ and $\|\mathbf{R}\mathbf{z}\|_2^2$ follows a scaled $\chi^2(K)$ distribution with expected value $\|\mathbf{z}\|_2^2$.

\textbf{II: \emph{Concentration Inequality.}}
Sub-Gaussian concentration (or standard $\chi^2$ tail bounds) implies that for any $\varepsilon > 0$, there exist positive constants $c_1, c_2$ so that
\[
\Pr\!\Bigl[
\bigl|\|\mathbf{R}\mathbf{z}\|_2^2 - \|\mathbf{z}\|_2^2\bigr|
\;\ge\;
\varepsilon\,\|\mathbf{z}\|_2^2
\Bigr]
\;\le\;
c_1\,\exp\bigl(-c_2\,\varepsilon^2\,K\bigr).
\]
Hence, $\|\mathbf{R}\mathbf{z}\|_2^2$ is within $(1 \pm \varepsilon)\|\mathbf{z}\|_2^2$ with high probability for one pair $(i,j)$.

\textbf{III: \emph{Union Bound over All Pairs.}}
There are $\binom{n}{2} \leq n^2/2$ distinct pairs $(i,j)$. A union bound over these pairs requires
\[
n^2\,c_1\,\exp\bigl(-c_2\,\varepsilon^2\,K\bigr)
\;\le\; 1,
\]
which rearranges to 
\[
K
\;\ge\;
C\,\varepsilon^{-2}\,\log(n)
\]
for some constant $C$. This guarantees that with high probability, for all $i \neq j$,
\[
(1-\varepsilon)\,\|\mathbf{x}_i - \mathbf{x}_j\|_2^2
\;\le\;
\|\mathbf{R}\,\mathbf{x}_i - \mathbf{R}\,\mathbf{x}_j\|_2^2 
\;\le\;
(1+\varepsilon)\,\|\mathbf{x}_i - \mathbf{x}_j\|_2^2.
\]
This completes the proof that random projections preserve pairwise distances among $\{\mathbf{x}_1, \dots, \mathbf{x}_n\}$ up to $(1\pm \varepsilon)$ distortion.
