    \centering
    \includegraphics[width=0.4\textwidth]{H1.png}
    \caption{In the dark-gray and light-gray regions, system \eqref{kcc-ex-2} has one and zero Jacobi stable fixed point, respectively. The blue curve is defined by $R_0=0$.}\label{fig:kcc-equilibria}
