\section{Proof of Lemma \ref{lem-main-1}}\label{sec-A}

\begin{proof}
The proof can be done by using the ideas from \cite[Section 4]{HPPS2016}. It should be noted that our fixed point here has arbitrariness and is not limited to the origin.

By taking the derivative of system \eqref{eq1-0} with respect to the time parameter $t$, we obtain
\begin{equation}\label{kcc-main-1}
\begin{split}
\frac{d^2x_1}{dt^2}&=f_{11}(\boldsymbol{x},\boldsymbol{\mu})y_1+f_{12}(\boldsymbol{x},\boldsymbol{\mu})y_2+
\cdots+f_{1n}(\boldsymbol{x},\boldsymbol{\mu})y_n,\\
\frac{d^2x_2}{dt^2}&=f_{21}(\boldsymbol{x},\boldsymbol{\mu})y_1+f_{22}(\boldsymbol{x},\boldsymbol{\mu})y_2+
\cdots+f_{2n}(\boldsymbol{x},\boldsymbol{\mu})y_n,\\
&\vdots\\
\frac{d^2x_n}{dt^2}&=f_{n1}(\boldsymbol{x},\boldsymbol{\mu})y_1+f_{n2}(\boldsymbol{x},\boldsymbol{\mu})y_2+
\cdots+f_{nn}(\boldsymbol{x},\boldsymbol{\mu})y_n,\nonumber
\end{split}
\end{equation}
where
\begin{equation}\label{kcc-main-2}
\begin{split}
f_{ij}=\frac{\partial f_i(\boldsymbol{x},\boldsymbol{\mu})}{\partial x_j},\quad y_i=\frac{dx_i}{dt}, \quad i,j=1,\ldots,n.
\end{split}
\end{equation}
The system can be written as
\begin{equation}\label{kcc-main-3}
\begin{split}
\frac{d^2x_i}{dt^2}-\sum_{k=1}^nf_{ik}(\boldsymbol{x},\boldsymbol{\mu})y_k=0, \quad i=1,\ldots,n.
\end{split}
\end{equation}
By comparing equations \eqref{kcc-main-3} and \eqref{kcc-4} we find
\begin{equation}\label{kcc-main-4}
\begin{split}
G^i=-\frac{1}{2}\sum_{k=1}^nf_{ik}(\boldsymbol{x},\boldsymbol{\mu})y_k=-\frac{1}{2}J(\boldsymbol{x},\boldsymbol{\mu})\boldsymbol{y}^T, \quad i=1,\ldots,n,
\end{split}
\end{equation}
where $J(\boldsymbol{x},\boldsymbol{\mu})$ is the Jacobian matrix of system \eqref{eq1-0} evaluated at the point $\boldsymbol{x}=(x_1,x_2,\ldots,x_n)$.

A direct computation shows that the coefficients of the nonlinear connection $N_j^i$ in \eqref{kcc-5} are the following:
\begin{equation}\label{kcc-main-5}
\begin{split}
N_j^i=\frac{\partial G^i}{\partial y_j}=-\frac{1}{2}f_{ij}(\boldsymbol{x},\boldsymbol{\mu}), \quad i,j=1,\ldots,n,
\end{split}
\end{equation}
and hence
\begin{equation}\label{kcc-main-6}
\begin{split}
G^i_{j\ell}=\frac{\partial N_j^i}{\partial y_{\ell}}=0.\nonumber
\end{split}
\end{equation}
Then, for the components of the deviation curvature tensor $(P_j^i)$, given by \eqref{kcc-10}, we have
\begin{equation}\label{kcc-main-7}
\begin{split}
P_j^i=-2\frac{\partial G^i}{\partial x_j}+y_{\ell}\frac{\partial N_j^i}{\partial x_{\ell}}+N_{\ell}^iN_j^{\ell}.
\end{split}
\end{equation}
Then, with the use of \eqref{kcc-main-4} and \eqref{kcc-main-5} we obtain
\begin{equation}\label{kcc-main-8}
\begin{split}
P_j^i=\frac{1}{2}\sum_{\ell=1}^nf_{ij\ell}(\boldsymbol{x},\boldsymbol{\mu})y_{\ell}+
\frac{1}{4}\sum_{\ell=1}^nf_{i\ell}(\boldsymbol{x},\boldsymbol{\mu})f_{\ell j}(\boldsymbol{x},\boldsymbol{\mu}),
\end{split}
\end{equation}
where
\begin{equation}\label{kcc-main-9}
\begin{split}
f_{ij\ell}=\frac{\partial f_{ij}(\boldsymbol{x},\boldsymbol{\mu})}{\partial x_{\ell}}, \quad \ell=1,\ldots,n.\nonumber
\end{split}
\end{equation}

Evaluating $P_j^i$ at the fixed point $\bar{\boldsymbol{x}}=(\bar{x}_1,\bar{x}_2,\ldots,\bar{x}_n)$ we obtain
\begin{equation}\label{kcc-main-10}
\begin{split}
P=(P_j^i)\big|_{\boldsymbol{x}=\bar{\boldsymbol{x}}}=\frac{1}{4}\sum_{\ell=1}^nf_{i\ell}(\boldsymbol{x},\boldsymbol{\mu})f_{\ell j}(\boldsymbol{x},\boldsymbol{\mu})\big|_{\boldsymbol{x}=\bar{\boldsymbol{x}}}=\frac{1}{4}J^2(\bar{\boldsymbol{x}},\boldsymbol{\mu}).
\end{split}
\end{equation}
According to Definition \ref{kcc-def}, we complete the proof of Lemma \ref{lem-main-1}.
\end{proof}


