There are two central reasons why \cref{eqn:language-levy} holds. Firstly, the stochastic process $\Prob_{\delta_{\Phi_n}}(\mc \in L)$ is a non-negative martingale. This implies that, if the value of the stochastic process ever hits 0, it must remain at 0 at all times thereafter. 
Secondly, the process $\Prob_{\delta_{\Phi_n}}(\mc \in L)$ almost-surely converges to 1 when $\mc \in L$ and to 0 otherwise,
as a consequence of L{\'e}vy's 0-1 Law. 
Since $\Prob_{\delta_{\Phi_n}}(\mc \in L)$ converges to either 0 or 1 almost surely,
the probability of the variable $\Prob_{\delta_{\Phi_n}}(\mc \in L)$ converging to 1 corresponds to the probability of not converging to 0, and
since 0 is an absorbing value for a non-negative martingale,
this corresponds to the probability that its infimum is positive. \qed
\end{example}

A consequence of the relation between shift-invariant specifications and 
the random variables associated with their satisfaction probability is that, 
for every desired approximation error $\epsilon > 0$, 
we can always choose an appropriate level set of this random variable to define a sufficiently tight stochastic invariant.

\begin{theorem}\label{thm:approx-general}
    Suppose that $L \in {\cal F}$ is shift-invariant. Then, for every $\epsilon > 0$ there exists a measurable set $I \in \Sigma$ such that $\Prob_\mu({\bf \Phi} \in I^\omega \land {\bf \Phi} \notin L) = 0$ and
    \begin{equation}
        \Prob_\mu({\bf {\Phi}} \in L) - \epsilon \leq \Prob_\mu({\bf {\Phi}} \in I^\omega) \leq \Prob_\mu({\bf {\Phi}} \in L). %\leq \Prob_\mu({\bf {\Phi}} \in I^\omega) + \epsilon
        \label{eqn:approx-general}
    \end{equation}
\end{theorem}

\begin{example}[The Gambler's Ruin]\label{ex:gambler}
    The Markov chain in \cref{ex:language-levy} corresponds to the Gambler's Ruin problem~\cite[p.~345]{FellerVol1}. 
    It is a classic result that if the process starts from $x > 0$, the probability of hitting any other value $y > x$---equivalent to 
    the probability of exiting the set $I = \{0, \dots, y-1\}$---is given by
    \begin{equation}
        \Prob_{\delta_x}(\mc \notin I^\omega) = \frac{1 -  (49/51)^x}{1 - (49/51)^{y}}. 
    \end{equation}
    It follows that the probability of avoiding $y$ converges asymptotically, for increasing $y$, 
    to the probability of hitting 0:
    \begin{equation}
        \lim_{y \to \infty} \underbrace{1 - \frac{1-(49/51)^x}{1-(49/51)^{y}}}_{\Prob_{\delta_x}(\mc \in I^\omega)} = 
        \underbrace{\left( 49/51 \right)^x}_{\Prob_{\delta_x}(\mc \in L)}.
    \end{equation}
    This shows that, for every $\epsilon > 0$, there exists a sufficiently large $y$ such that $I$ satisfies \cref{eqn:approx-general} with $\mu = \delta_x$. 
    Moreover, for every $y$ the event of eventually hitting either 0 or $y$ has probability 1; in other words $\Prob_{\delta_x}({\bf \Phi} \in I^\omega \land {\bf \Phi} \notin L) = 0$. \qed
\end{example}

We further demonstrate that, for finite systems, a stochastic invariant that exactly quantifies the probability of the specification always exists.
\begin{theorem}\label{thm:exact-finite}
    Suppose that $L \in {\cal F}$ is shift-invariant and $S$ 
    is finite. Then, there exists a measurable set $I \in \Sigma$ such that $\Prob_\mu({\bf \Phi} \in I^\omega \land {\bf \Phi} \notin L) = 0$ and
    \begin{equation}
        \Prob_\mu({\bf {\Phi}} \in I^\omega) = \Prob_\mu({\bf {\Phi}} \in L). \label{eqn:exact-finite}
    \end{equation}
\end{theorem}

\begin{example}
    Assume that the Markov chain in \cref{ex:language-levy} has an upper bound $N > 0$ that is a sink state, making its state space finite. 
    Then, the event of hitting 0---which is the event $L$---corresponds exactly to the event of avoiding $N$---which is the event $I^\omega$ 
    with $I = \{0, \dots, N - 1\}$. Since the two events are equivalent, their probabilities are as well, satisfying \cref{eqn:exact-finite}. \qed
\end{example}

\begin{remark}[Existence of Value Functions]
    Our converse theorems establish the existence of invariant regions $I \in \Sigma$. 
    This implies the existence of appropriate value functions, which can be
    defined as $V_0(s) = \Prob_{\delta_s}(\mc \notin I^\omega)$. 
    These are necessarily measurable and are guaranteed to satisfy \cref{eqn:invar-noninc,eqn:invar-one}.\qed
\end{remark}


\section{Quantitative Supermartingale Certificates}

We propose a general methodology for the formalisation of proof rules to 
establish probability bounds for a broad variety of specifications. 
We show that the problem of computing lower bounds for the probability of satisfaction 
of shift-invariant specifications can be decomposed into two problems: 
computing a stochastic invariant alongside a lower bound for its probability, and 
deciding the almost-sure satisfaction of the specification conditional to the stochastic invariant. 

\begin{theorem}\label{thm:decomp}
    Suppose that $L \in {\cal F}$ is shift-invariant and, 
    for some probability bound $p \in (0, 1]$ and measurable set $I \in \Sigma$, the following two conditions hold:
    \begin{align}
        &{\sf P}_\mu(\mathbf{\Phi} \in I^\omega) \geq p, \label{eqn:pee} \\
        &{\sf P}_\mu (\mathbf{\Phi} \in L \mid \mathbf{\Phi} \in I^\omega) = 1. \label{eqn:one}
    \end{align}
    Then, ${\sf P}_\mu(\mathbf{\Phi} \in L) \geq p$.
\end{theorem}

This result enables the extension of every supermartingale certificate proof rule for almost-sure satisfaction, conditional 
to a deterministic invariant, towards a quantitative proof rule for the same specification. 
Specifically, our proof rule for stochastic invariants presented in \cref{thm:invar} provides the appropriate 
constraints for the formalisation of quantitative supermartingale certificates.
\begin{example}[{\protect A Proof Rule for Quantitative Termination \cite[Theorem 4]{DBLP:conf/cav/ChatterjeeGMZ22}}]\label{example:quant-reach-rule}
    Using our methodology, we formalise a supermartingale certificate proof rule for the quantitative finite-time 
    termination of probabilistic programs. For the set of terminal states $A \in \Sigma$, which are assumed to be sink states, this corresponds to determining the probability of $L = \{ \sum_{n=0}^\infty {\bf 1}_{A}(\Phi_n) = \infty \}$, which is shift-invariant.
    We combine the proof rule for ranking supermartingales~\cite[Definition 9]{DBLP:conf/cav/ChakarovS13} (cf. \cref{eqn:ranking})---which proves almost-sure termination in expected finite time---with \cref{thm:invar}, and obtain the following (known) proof rule:
    \begin{align}
        \forall s \in I \colon &PV_0(s) \leq V_0(s),\label{eqn:reach-drift}\\
        \forall s \notin I \colon &V_0(s) \geq 1,\label{eqn:reach-one}\\
        \forall s \in I \setminus A \colon & PV_1(s) \leq V_1(s) - \varepsilon. \label{eqn:ranking}
    \end{align}
    Here, any region $I \in \Sigma$, non-negative value functions $V_0,V_1\colon S\to\Real_{\geq 0}$, and 
    positive constant $\varepsilon > 0$ constitute a quantitative supermartingale certificate where $1 - \mu V_0$ is a lower bound 
    upon the probability of hitting target $A$.

    Consider the quantitative verification problem developed in \cref{ex:language-levy,ex:gambler}, 
    which corresponds to the termination question with terminal state $A = \{ 0 \}$. A valid supermartingale certificate is given by the following components:
    \begin{equation}
        V_0(x) = \frac{1 -  (49/51)^x}{1 - (49/51)^{y}},\quad V_1(x) = y-x,\quad I = \{0, \dots, y-1\},\quad \varepsilon = 0.02,\label{eq:term-cert}
    \end{equation}
    where $y \in \Nat$ is any value larger than the initial state. For initial state 10, 
    the true probability is approximately $0.6703 \approx (49/51)^{10}$. 
    With $y = 50$, we obtain bound $1 - V_0(10) \approx 0.62$; 
    with $y = 100$, we obtain the tighter bound $1 - V_0(10) \approx 0.66$; 
    with $y = 200$, we obtain the much tighter bound $1 - V_0(10) \approx 0.6702$. 
    Notably, the true probability $(49/51)^x$ would violate \cref{eqn:reach-one}, and in this example
    a bounded invariant is essential to construct a ranking supermartingale $V_1$. \qed
\end{example}

Our converse results presented in \cref{thm:approx-general,thm:exact-finite} guarantee that our methodology yields complete certificates
up to arbitrary approximation for systems with general state space, and complete certificates for finite systems.
\begin{theorem}[$\epsilon$-Completeness for General Markov Chains]\label{thm:epsilon-complete}
    Suppose that $L \in {\cal F}$ is shift-invariant. Then, for every arbitrary $\epsilon > 0$, 
    there exists a measurable set $I \in \Sigma$ such that 
    \cref{eqn:pee,eqn:one} hold with $p = {\sf P}_\mu(\mathbf{\Phi} \in L) - \epsilon$.
\end{theorem}
\begin{theorem}[Completeness for Finite Markov Chains]
\label{thm:complete}
    Suppose that $L \in {\cal F}$ is shift-invariant and $S$ is finite. 
    Then, there exists a measurable set $I \in \Sigma$ such that \cref{eqn:pee,eqn:one} hold with $p = {\sf P}_\mu(\mathbf{\Phi} \in L)$.
\end{theorem}
\begin{remark}\label{rmk:relative}
    Composing stochastic invariants and almost-sure certificates, as described in \cref{thm:decomp}, 
    results in complete proof rules for probabilistic lower bounds under the assumption that the proof rule for conditional almost-sure satisfaction is complete. In other words, all completeness guarantees of the proof rule for almost-sure satisfaction carry over to their quantitative extension, up to approximation or exactly, as described in \cref{thm:epsilon-complete,thm:complete} respectively. \qed
\end{remark}

Our methodology generalises and unifies existing proof rules for quantitative model checking and control synthesis, 
while providing the foundation for formalising quantitative supermartingale certificates for new specifications and objectives. 
It applies to the rich class of shift-invariant specifications, which includes and extends beyond a broad variety of special cases.
This includes specifications defined as limits\cite[Lemma 5.1.6]{douc2018markov}, such as the limit objectives on cost and reward considered in reinforcement learning, and asymptotic stability considered in control theory, all of which are also tail events (cf.~\cref{rmk:tail}). 
Moreover, it also includes B\"uchi, co-B\"uchi, Rabin, Streett, Muller, and parity acceptance conditions of automata over infinite words~\cite{DBLP:journals/tcs/Chatterjee07}. 
As we demonstrate, this enables in particular the development of quantitative supermartingale certificates for $\omega$-regular specifications.


\section{Quantitative $\omega$-Regular Verification and Control}

We present the first quantitative supermartingale certificate for $\omega$-regular specifications, 
which we obtain as a result of \cref{thm:invar,thm:decomp} 
and the supermartingale certificate for the almost-sure acceptance of Streett conditions~\cite{DBLP:conf/cav/AbateGR24}. 

An $\omega$-regular specification (or language) over a finite set of atomic propositions $\Pi$, 
which we define as predicates over the state space of the system under analysis, corresponds to the language
of an $\omega$-regular expression
whose alphabet is the Boolean truth valuations of $\Pi$.
An important class of $\omega$-regular specifications is the temporal behaviour described using linear temporal logic (LTL).
An LTL formula $\varphi$ extends propositional logic (over the atomic propositions $\Pi$) with the temporal  
{\em next} operator ${\sf X}\varphi$, indicating that $\varphi$ holds after one step in the future, 
the {\em eventually} operator ${\sf F}\varphi$, indicating that $\varphi$ holds at some point in the future, 
the {\em always} operator ${\sf G} \varphi$, indicating that $\varphi$ holds at all times in the future, 
and the {\em until} operator $\varphi {\sf U} \psi$, indicating that $\varphi$ holds at all times in the future before $\psi$, which in turn holds at some point in the future~\cite{DBLP:conf/focs/Pnueli77}. 

We treat the problem of determining the probability of satisfying an $\omega$-regular specification over $\Pi$ 
for a system under analysis %$\cal M$ 
whose semantics is a time-homogeneous Markov chain $\hat{\mc}$ %$\mc_{\cal M}$ 
with general state space 
$(\hat{S}, \hat{\Sigma})$, initial probability measure $\hat{\mu}$ and transition probability kernel $\hat{P}$.
The problem is defined in terms of 
a measurable labelling function $\llangle \cdot \rrangle \colon \hat{S} \to {\cal P}(\Pi)$ where
$\llangle s \rrangle \subseteq \Pi$ indicates the set of atomic propositions  
that hold true in state $s \in \hat{S}$, which we call the labelling of $s$, 
and interpret the $\omega$-regular specification according to its usual semantics 
over the set of traces ${\cal P}(\Pi)^\omega$. 
Notably, $\omega$-regular specifications lack shift invariance.
For example, the LTL formula $\varphi = {\sf F}a$, defining the event
${L}_{\varphi} = \{ \exists n \in \Nat \colon a \in \llangle \Phi_n \rrangle\}$, is not invariant to time shift (cf. \cref{rmk:liveness}).

Automata over infinite words reduce $\omega$-regular specifications to equivalent acceptance conditions that are shift-invariant, by extending the state space with additional memory which is given by the states of an $\omega$-automaton.
Büchi automata are the canonical example, but they require the presence of 
non-determinism, with which standard probability theory is limited.
Conversely, automata with Muller, Rabin, parity, 
and Streett acceptance conditions recognise   $\omega$-regular languages in their deterministic form~\cite{DBLP:conf/dagstuhl/2001automata}, which preserves the probabilistic nature of the system.
We consider the case of Streett automata, 
and generalise the existing supermartingale certificates for their almost-sure acceptance (from the literature~\cite{DBLP:conf/cav/AbateGR24}) 
to additionally produce lower and upper probability bounds for $\omega$-regular specifications. 
\begin{definition}[Deterministic Streett Automata]
A deterministic Streett automaton (DSA) over the finite set of propositions $\Pi$ consists of 
a finite set of states $Q$,  
an initial state $q_0 \in Q$, 
a transition function $T \colon Q \times {\cal P}(\Pi) \to Q $, 
and an acceptance condition $(F_1, G_1), \dots, (F_k,G_k)$ where $F_i, G_i \subseteq Q$ for $i = 1, \dots k$.
An infinite input trace $(p_0, p_1, p_2, \dots ) \in {\cal P}(\Pi)^\omega$ is accepted if there exists 
an infinite run $(q_0, q_1, q_2, \dots) \in Q^\omega$ such that $q_{n+1} = T(q_n, p_n)$ for every $n \in \Nat$ and,  
for every $i = 1, \dots, k$, either $\sum_{n=0}^\infty {\bf 1}_{F_i}(q_n) < \infty$ or $\sum_{n=0}^\infty {\bf 1}_{G_i}(q_n) = \infty$.
\end{definition}

There are multiple algorithms for the automatic construction of DSA,
in particular from LTL formulae~\cite{DBLP:conf/cav/KretinskyMSZ18,DBLP:conf/cav/Duret-LutzRCRAS22}. 
Given a DSA, the original $\omega$-regular verification 
question reduces to a question of Streett acceptance over the synchronous composition between the system under analysis $\hat{\mc}$ and the automaton. The synchronous composition is a Markov chain over state space $S = \hat{S} \times Q$ 
with the $\sigma$-algebra $\Sigma = \hat{\Sigma} \otimes {\cal P}(Q)$,  whose transition probability kernel $P \colon S \times \Sigma \to [0,1]$ and initial probability measure $\mu \colon \Sigma \to [0,1]$ 
are defined as follows:
\begin{align}
    P
    ((s, q), A)
    &= \int_{(u,r) \in A}
    \hat{P}(s, {\rm d}u)
    \cdot 
    \mathbf{1}_{\{r\}}(T(q, \llangle s \rrangle)), \\
    \mu(A) &= \int_{(u,r) \in A} \hat{\mu}({\rm d}u) \cdot {\bf 1}_{\{ r \}}(q_0).
\end{align}
This is associated with the Streett acceptance condition $(A_1,B_1) \in \Sigma^2, \dots, (A_k,\allowbreak B_k) \in \Sigma^2$ 
defined as $A_i = \hat{S} \times F_i, B_i = \hat{S} \times G_i$ for $i = 1, \dots k$.
\begin{remark}[Streett Acceptance is Shift-Invariant]
    As we establish in \cref{ex:language-levy}, the B\"uchi acceptance condition $\{ \sum_{n = 0}^{\infty} \ind_{ A }(\Phi_n) = \infty \}$ 
    is shift-invariant. We note that shift-invariant events are closed under countable Boolean operations~\cite[Proposition 5.1.5]{douc2018markov}, 
    and that Streett acceptance corresponds to the event $\cap_{i=1}^k (\{ \sum_{n = 0}^{\infty} \ind_{ A_i }(\Phi_n) = \infty \}^{\sf c} \cup \{ \sum_{n = 0}^{\infty} \ind_{ B_i }(\Phi_n) = \infty \})$.\qed
\end{remark}
